import subprocess,re,os
ANSI=re.compile(r'\x1b\[[0-9;]*m')
D='/tmp/pr'
os.makedirs(D,exist_ok=True)
def run(src,name='p.nix',sub='check',args=None,d=D,fmt='stderr'):
    p=os.path.join(d,name); open(p,'w').write(src)
    if sub=='check': a=['check']+ (args or []) + (['-o',fmt] if fmt else []) + [name]
    elif sub=='fix': a=['fix']+ (args or ['-d']) + [name]
    else: a=[sub]+(args or [])+[name]
    r=subprocess.run(['/workspace/executable']+a,capture_output=True,cwd=d)
    return r.returncode, ANSI.sub('',(r.stdout+r.stderr).decode())
def err(src,name='p.nix',sub='check',args=None,d=D):
    return run(src,name,sub,args,d,'errfmt')
