            Imply => "TOKEN_IMPLY",
            Update => "TOKEN_UPDATE",
            Assert => "TOKEN_ASSERT",
            If => "TOKEN_IF",
            Then => "TOKEN_THEN",
            Else => "TOKEN_ELSE",
            Rec => "TOKEN_REC",
