                        Some(c) if Self::is_ident_cont(c) => self.bump(),
                        Some(b'.') => self.bump(),
                        _ => break,
                    }
                }
                _ => break,
            }
        }
    }

    fn lex_uri_tail(&mut self) {
        while let Some(c) = self.peek() {
            if matches!(
                c,
                b'a'..=b'z'
                    | b'A'..=b'Z'
                    | b'0'..=b'9'
                    | b'%'| b'/' | b'?' | b':' | b'@' | b'&' | b'=' | b'+' | b'$' | b','
                    | b'.' | b'!' | b'~' | b'*' | b'\'' | b'(' | b')' | b'[' | b']' | b'-' | b'_'
            ) {
                self.bump();
            } else {
                break;
            }
        }
    }

    fn lex_number(&mut self, after_dot: bool) -> Tk {
        let mut saw_dot = after_dot;
        let mut saw_digit = false;
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() {
                saw_digit = true;
                self.bump();
            } else if c == b'.' && !saw_dot && matches!(self.peek_at(1), Some(d) if d.is_ascii_digit())
            {
                saw_dot = true;
                self.bump();
            } else if c == b'.'
                && !saw_dot
                && !matches!(self.peek_at(1), Some(d) if Self::is_ident_cont(d))
            {
                // trailing dot e.g. `1.`
                saw_dot = true;
                self.bump();
                break;
            } else {
                break;
            }
        }
        if saw_dot && saw_digit {
            Tk::Float
        } else {
            Tk::Integer
        }
    }

    fn lex_dquoted_string(&mut self) -> Tk {
        self.bump(); // opening quote
        loop {
            match self.peek() {
                None => return Tk::StringStart,
                Some(b'"') => {
                    self.bump();
                    return Tk::StringStart;
                }
                Some(b'\\') => {
                    self.bump();
                    self.bump();
                }
                Some(b'$') if self.peek_at(1) == Some(b'{') => {
                    return Tk::StringStart;
                }
                _ => {
                    self.bump();
                }
            }
        }
    }

    fn lex_squoted_string(&mut self) -> Tk {
        self.bump();
        self.bump();
        loop {
            match self.peek() {
                None => return Tk::StringStart,
                Some(b'\'') if self.peek_at(1) == Some(b'\'') => {
                    // '' closes, but ''$ is an escape for a literal '$'
                    if self.peek_at(2) == Some(b'$') {
                        self.bump();
                        self.bump();
                        continue;
                    }
                    if self.peek_at(2) == Some(b'\'') && self.peek_at(3) == Some(b'\'') {
                        // '''' -> escaped ''
                        self.bump();
                        self.bump();
                        continue;
                    }
                    self.bump();
                    self.bump();
                    return Tk::StringStart;
                }
                Some(b'$') if self.peek_at(1) == Some(b'{') => {
                    return Tk::StringStart;
                }
                _ => {
                    self.bump();
                }
            }
        }
    }
}
RSEOF
echo done"}

