    }
}

#[derive(Clone, Copy, PartialEq)]
enum Ctx {
    DQuote,
    SQuote,
    Group,
}

pub struct Lexer<'a> {
    src: &'a [u8],
    pos: usize,
    stack: Vec<Ctx>,
}

impl<'a> Lexer<'a> {
    pub fn new(src: &'a str) -> Self {
        Lexer { src: src.as_bytes(), pos: 0, stack: Vec::new() }
    }

    pub fn tokenize(src: &str) -> Vec<Tok> {
        let mut lx = Lexer::new(src);
        let mut out = Vec::new();
        while let Some(t) = lx.next_token() {
            out.push(t);
        }
        out
    }

    fn peek(&self) -> Option<u8> {
        self.src.get(self.pos).copied()
    }
    fn peek_at(&self, n: usize) -> Option<u8> {
        self.src.get(self.pos + n).copied()
    }
    fn bump(&mut self) -> u8 {
        let c = self.src[self.pos];
        self.pos += 1;
        c
    }

    fn is_ident_start(c: u8) -> bool {
        c.is_ascii_alphabetic() || c == b'_'
    }
    fn is_ident_cont(c: u8) -> bool {
        c.is_ascii_alphanumeric() || c == b'_' || c == b'\'' || c == b'-'
    }

    fn next_token(&mut self) -> Option<Tok> {
        let start = self.pos;
        let ctx = *self.stack.last().unwrap_or(&Ctx::Group);
        let kind = match ctx {
            Ctx::DQuote => {
                let c = self.peek()?;
                match c {
                    b'"' => {
                        self.bump();
                        self.stack.pop();
                        Tk::StringEnd
                    }
                    b'\\' => {
                        self.bump();
                        self.bump();
                        Tk::StringContent
                    }
                    b'$' if self.peek_at(1) == Some(b'{') => {
                        self.bump();
                        self.bump();
                        self.stack.push(Ctx::Group);
                        Tk::InterpolStart
                    }
                    _ => {
                        while let Some(c) = self.peek() {
                            match c {
                                b'"' | b'\\' => break,
                                b'$' if self.peek_at(1) == Some(b'{') => break,
                                _ => {
                                    self.bump();
                                }
                            }
                        }
                        Tk::StringContent
                    }
                }
            }
            Ctx::SQuote => {
                let c = self.peek()?;
                match c {
                    b'\'' if self.peek_at(1) == Some(b'\'') => {
                        if self.peek_at(2) == Some(b'$') || self.peek_at(2) == Some(b'\'') {
                            self.bump();
                            self.bump();
                            if self.peek_at(0) == Some(b'$') {
                                self.bump();
                            } else {
                                self.bump();
                                self.bump();
                            }
                            Tk::StringContent
                        } else {
                            self.bump();
                            self.bump();
                            self.stack.pop();
                            Tk::StringEnd
                        }
                    }
                    b'$' if self.peek_at(1) == Some(b'{') => {
                        self.bump();
                        self.bump();
                        self.stack.push(Ctx::Group);
                        Tk::InterpolStart
                    }
                    _ => {
                        while let Some(c) = self.peek() {
                            match c {
                                b'\'' if self.peek_at(1) == Some(b'\'') => break,
                                b'$' if self.peek_at(1) == Some(b'{') => break,
                                _ => {
                                    self.bump();
                                }
                            }
                        }
                        Tk::StringContent
                    }
                }
            }
            Ctx::Group => {
                let c = self.peek()?;
                match c {
                    b'"' => {
                        self.bump();
                        self.stack.push(Ctx::DQuote);
                        Tk::StringStart
                    }
                    b'\'' if self.peek_at(1) == Some(b'\'') => {
                        self.bump();
                        self.bump();
                        self.stack.push(Ctx::SQuote);
                        Tk::StringStart
                    }
                    b'$' if self.peek_at(1) == Some(b'{') => {
                        self.bump();
                        self.bump();
                        self.stack.push(Ctx::Group);
                        Tk::InterpolStart
                    }
                    b'{' => {
                        self.bump();
                        self.stack.push(Ctx::Group);
                        Tk::LBrace
                    }
                    b'}' => {
                        self.bump();
                        self.stack.pop();
                        Tk::RBrace
                    }
                    b'[' => {
                        self.bump();
                        self.stack.push(Ctx::Group);
                        Tk::LBracket
                    }
                    b']' => {
                        self.bump();
                        self.stack.pop();
                        Tk::RBracket
                    }
                    b'(' => {
                        self.bump();
                        self.stack.push(Ctx::Group);
                        Tk::LParen
                    }
                    b')' => {
                        self.bump();
                        self.stack.pop();
                        Tk::RParen
                    }
                    b';' => {
                        self.bump();
                        Tk::Semicolon
                    }
                    b':' => {
                        self.bump();
                        Tk::Colon
                    }
                    b',' => {
                        self.bump();
                        Tk::Comma
                    }
                    b'=' if self.peek_at(1) == Some(b'=') => {
                        self.bump();
                        self.bump();
                        Tk::Equal
                    }
                    b'!' if self.peek_at(1) == Some(b'=') => {
                        self.bump();
                        self.bump();
                        Tk::NotEqual
                    }
                    b'!' => {
                        self.bump();
                        Tk::Error
                    }
                    b'=' => {
                        self.bump();
                        Tk::Assign
                    }
                    b'@' => {
                        self.bump();
                        Tk::PatEntry
                    }
                    b'.' => {
                        if matches!(self.peek_at(1), Some(d) if d.is_ascii_digit()) {
                            self.lex_number(true)
                        } else {
                            self.bump();
                            Tk::Select
                        }
                    }
                    b'?' => {
                        self.bump();
                        Tk::Question
                    }
                    b'+' if self.peek_at(1) == Some(b'+') => {
                        self.bump();
                        self.bump();
                        Tk::Concat
                    }
                    b'+' => {
                        self.bump();
                        Tk::Error
                    }
                    b'-' if self.peek_at(1) == Some(b'>') => {
                        self.bump();
                        self.bump();
                        Tk::Imply
                    }
                    b'-' => {
                        self.bump();
                        Tk::Minus
                    }
                    b'*' => {
                        self.bump();
                        Tk::Multiply
                    }
                    b'/' if self.peek_at(1) == Some(b'*') => self.lex_block_comment(),
                    b'/' => {
                        self.bump();
                        Tk::Divide
                    }
                    b'<' if self.peek_at(1) == Some(b'=') => {
                        self.bump();
                        self.bump();
                        Tk::LessOrEq
                    }
                    b'<' => {
                        self.bump();
                        Tk::Less
                    }
                    b'>' if self.peek_at(1) == Some(b'=') => {
                        self.bump();
                        self.bump();
                        Tk::GreaterOrEq
                    }
                    b'>' => {
                        self.bump();
                        Tk::Greater
                    }
                    b'&' if self.peek_at(1) == Some(b'&') => {
                        self.bump();
                        self.bump();
                        Tk::And
                    }
                    b'|' if self.peek_at(1) == Some(b'|') => {
                        self.bump();
                        self.bump();
                        Tk::Error
                    }
                    b'|' => {
                        self.bump();
                        Tk::Error
                    }
                    b'~' | b'^' | b'%' | b'\\' => {
                        self.bump();
                        Tk::Error
                    }
                    b'#' => {
                        while let Some(c) = self.peek() {
                            if c == b'\n' {
                                break;
                            }
                            self.bump();
                        }
                        Tk::Comment
                    }
                    c if c.is_ascii_digit() => self.lex_number(false),
                    c if Self::is_ident_start(c) => self.lex_word(),
                    _ => {
                        self.bump();
                        Tk::Error
                    }
                }
            }
        };
        Some(Tok { kind, start, end: self.pos })
    }

    fn lex_block_comment(&mut self) -> Tk {
        let start = self.pos;
        self.bump();
        self.bump();
        let mut closed = false;
        while let Some(c) = self.peek() {
            if c == b'*' && self.peek_at(1) == Some(b'/') {
                self.bump();
                self.bump();
                closed = true;
                break;
            }
            self.bump();
        }
        if closed {
            Tk::Comment
        } else {
            let _ = start;
            Tk::Error
        }
    }

    fn lex_word(&mut self) -> Tk {
        let start = self.pos;
        while let Some(c) = self.peek() {
            if Self::is_ident_cont(c) {
                self.bump();
            } else {
                break;
            }
        }
        if matches!(self.peek(), Some(b'/')) && self.peek_at(1) != Some(b'*') {
            self.lex_path_tail();
            return Tk::Path;
        }
        let word = &self.src[start..self.pos];
        match word {
            b"assert" => Tk::Assert,
            b"if" => Tk::If,
            b"then" => Tk::Then,
            b"else" => Tk::Else,
            b"rec" => Tk::Rec,
            b"let" => Tk::Let,
            b"in" => Tk::In,
            b"or" => Tk::Or,
            b"true" | b"false" | b"null" => Tk::Ident,
            _ => {
                if let Some(colon) = word.iter().position(|c| *c == b':') {
                    if colon > 0 && Self::valid_scheme(&word[..colon]) {
                        self.lex_uri_tail();
                        return Tk::Uri;
                    }
                }
                Tk::Ident
            }
        }
    }

    fn valid_scheme(s: &[u8]) -> bool {
        if s.is_empty() {
            return false;
        }
        if !s[0].is_ascii_alphabetic() {
            return false;
        }
        s.iter()
            .all(|c| c.is_ascii_alphanumeric() || matches!(*c, b'+' | b'-' | b'.'))
    }

    fn lex_path_tail(&mut self) {
        self.bump(); // the '/'
        loop {
            match self.peek() {
                Some(c) if Self::is_ident_cont(c) => {
                    self.bump();
                }
                Some(b'.') => {
                    self.bump();
                }
                Some(b'/') => match self.peek_at(1) {
                    Some(c) if Self::is_ident_cont(c) => self.bump(),
                    Some(b'.') => self.bump(),
                    _ => break,
                },
                _ => break,
            }
        }
    }

    fn lex_uri_tail(&mut self) {
        while let Some(c) = self.peek() {
            let ok = c.is_ascii_alphanumeric()
                || matches!(
                    c,
                    b'%' | b'/'
                        | b'?'
                        | b':'
                        | b'@'
                        | b'&'
                        | b'='
                        | b'+'
                        | b'$'
                        | b','
                        | b'.'
                        | b'!'
                        | b'~'
                        | b'*'
                        | b'\''
                        | b'('
                        | b')'
                        | b'['
                        | b']'
                        | b'-'
                        | b'_'
                );
            if ok {
                self.bump();
            } else {
                break;
            }
        }
    }

    fn lex_number(&mut self, after_dot: bool) -> Tk {
        let mut saw_dot = after_dot;
        let mut saw_digit = false;
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() {
                saw_digit = true;
                self.bump();
            } else if c == b'.'
                && !saw_dot
                && !matches!(self.peek_at(1), Some(d) if Self::is_ident_cont(d) || d == b'.')
            {
                saw_dot = true;
                self.bump();
            } else {
                break;
            }
        }
        if saw_dot {
            Tk::Float
        } else {
            Tk::Integer
        }
    }
}
RSEOF
echo done"}

