                    b'$' if self.peek_at(1) == Some(b'{') => {
                        self.bump();
                        self.bump();
                        self.stack.push(Ctx::Group);
                        Tk::InterpolStart
                    }
                    _ => {
                        while let Some(c) = self.peek() {
                            match c {
                                b'"' | b'\\' => break,
                                b'$' if self.peek_at(1) == Some(b'{') => break,
                                _ => {
                                    self.bump();
                                }
                            }
                        }
                        Tk::StringContent
                    }
                }
            }
            Ctx::SQuote => {
                let c = self.peek()?;
                match c {
                    b'\'' if self.peek_at(1) == Some(b'\'') => {
                        if self.peek_at(2) == Some(b'$') || self.peek_at(2) == Some(b'\'') {
                            self.bump();
                            self.bump();
                            if self.peek_at(0) == Some(b'$') {
                                self.bump();
                            } else {
                                self.bump();
                                self.bump();
                            }
                            Tk::StringContent
                        } else {
                            self.bump();
                            self.bump();
                            self.stack.pop();
                            Tk::StringEnd
                        }
                    }
                    b'$' if self.peek_at(1) == Some(b'{') => {
                        self.bump();
                        self.bump();
                        self.stack.push(Ctx::Group);
                        Tk::InterpolStart
                    }
