                        self.bump();
                        Tk::Semicolon
                    }
                    b':' => {
                        self.bump();
                        Tk::Colon
                    }
                    b',' => {
                        self.bump();
                        Tk::Comma
                    }
                    b'=' if self.peek_at(1) == Some(b'=') => {
                        self.bump();
                        self.bump();
                        Tk::Equal
                    }
                    b'!' if self.peek_at(1) == Some(b'=') => {
                        self.bump();
                        self.bump();
                        Tk::NotEqual
                    }
                    b'!' => {
                        self.bump();
                        Tk::Error
                    }
                    b'=' => {
                        self.bump();
                        Tk::Assign
                    }
                    b'@' => {
                        self.bump();
                        Tk::PatEntry
                    }
