    fn lex_block_comment(&mut self) -> Tk {
        let start = self.pos;
        self.bump();
        self.bump();
        let mut closed = false;
        while let Some(c) = self.peek() {
            if c == b'*' && self.peek_at(1) == Some(b'/') {
                self.bump();
                self.bump();
                closed = true;
                break;
            }
            self.bump();
        }
        if closed {
            Tk::Comment
        } else {
            let _ = start;
            Tk::Error
        }
    }

    fn lex_word(&mut self) -> Tk {
        let start = self.pos;
        while let Some(c) = self.peek() {
            if Self::is_ident_cont(c) {
                self.bump();
            } else {
                break;
            }
        }
        if matches!(self.peek(), Some(b'/')) && self.peek_at(1) != Some(b'*') {
            self.lex_path_tail();
            return Tk::Path;
        }
        let word = &self.src[start..self.pos];
        match word {
            b"assert" => Tk::Assert,
            b"if" => Tk::If,
            b"then" => Tk::Then,
            b"else" => Tk::Else,
            b"rec" => Tk::Rec,
            b"let" => Tk::Let,
            b"in" => Tk::In,
            b"or" => Tk::Or,
            b"true" | b"false" | b"null" => Tk::Ident,
            _ => {
                if let Some(colon) = word.iter().position(|c| *c == b':') {
                    if colon > 0 && Self::valid_scheme(&word[..colon]) {
                        self.lex_uri_tail();
                        return Tk::Uri;
                    }
                }
                Tk::Ident
            }
        }
    }

    fn valid_scheme(s: &[u8]) -> bool {
        if s.is_empty() {
            return false;
        }
        if !s[0].is_ascii_alphabetic() {
            return false;
        }
        s.iter()
            .all(|c| c.is_ascii_alphanumeric() || matches!(*c, b'+' | b'-' | b'.'))
    }

    fn lex_path_tail(&mut self) {
        self.bump(); // the '/'
        loop {
            match self.peek() {
                Some(c) if Self::is_ident_cont(c) => {
                    self.bump();
                }
                Some(b'.') => {
                    self.bump();
                }
                Some(b'/') => match self.peek_at(1) {
                    Some(c) if Self::is_ident_cont(c) => self.bump(),
                    Some(b'.') => self.bump(),
                    _ => break,
                },
                _ => break,
            }
        }
    }

    fn lex_uri_tail(&mut self) {
        while let Some(c) = self.peek() {
            let ok = c.is_ascii_alphanumeric()
                || matches!(
                    c,
                    b'%' | b'/'
                        | b'?'
                        | b':'
                        | b'@'
                        | b'&'
                        | b'='
                        | b'+'
                        | b'$'
                        | b','
                        | b'.'
                        | b'!'
                        | b'~'
                        | b'*'
                        | b'\''
                        | b'('
                        | b')'
                        | b'['
                        | b']'
                        | b'-'
                        | b'_'
                );
            if ok {
                self.bump();
            } else {
                break;
            }
        }
    }

    fn lex_number(&mut self, after_dot: bool) -> Tk {
        let mut saw_dot = after_dot;
        let mut saw_digit = false;
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() {
                saw_digit = true;
                self.bump();
            } else if c == b'.'
                && !saw_dot
                && !matches!(self.peek_at(1), Some(d) if Self::is_ident_cont(d) || d == b'.')
            {
                saw_dot = true;
                self.bump();
            } else {
                break;
            }
        }
        if saw_dot {
            Tk::Float
        } else {
            Tk::Integer
        }
    }
}
