    Float,
    Path,
    Uri,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Op {
    Add,
    Sub,
    Mul,
    Div,
    Update,
    Concat,
    Eq,
    Ne,
    Lt,
    Gt,
    Le,
    Ge,
    And,
    Or,
    Imply,
}

impl Op {
    pub fn from_tk(t: Tk) -> Option<Op> {
        use Op::*;
        Some(match t {
            Tk::Add => Add,
            Tk::Minus => Sub,
            Tk::Multiply => Mul,
            Tk::Divide => Div,
            Tk::Update => Update,
            Tk::Concat => Concat,
            Tk::Equal => Eq,
            Tk::NotEqual => Ne,
            Tk::Less => Lt,
            Tk::Greater => Gt,
            Tk::LessOrEq => Le,
            Tk::GreaterOrEq => Ge,
            Tk::And => And,
            Tk::Or => Or,
            Tk::Imply => Imply,
            _ => return None,
        })
    }

    /// Precedence: higher binds tighter. `?` (HasAttr) is 8.
    pub fn prec(self) -> u8 {
        use Op::*;
        match self {
            Imply => 0,
            Or => 1,
            And => 2,
            Eq | Ne | Lt | Gt | Le | Ge => 3,
            Update => 4,
            Add | Sub => 5,
            Mul | Div => 6,
            Concat => 7,
        }
    }

    /// Right associative / non associative?
    pub fn assoc(self) -> Assoc {
        use Op::*;
        match self {
            Imply | Concat => Assoc::Right,
            Eq | Ne | Lt | Gt | Le | Ge | Update => Assoc::None,
            _ => Assoc::Left,
        }
    }

    pub fn as_str(self) -> &'static str {
        use Op::*;
        match self {
            Add => "+",
            Sub => "-",
            Mul => "*",
            Div => "/",
            Update => "//",
            Concat => "++",
            Eq => "==",
            Ne => "!=",
            Lt => "<",
            Gt => ">",
            Le => "<=",
            Ge => ">=",
            And => "&&",
            Or => "||",
            Imply => "->",
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Assoc {
    Left,
    Right,
    None,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum UOp {
    Invert,
    Negate,
}

#[derive(Clone, Debug)]
pub struct Node {
    pub kind: Nk,
    pub sub: u8,
    pub start: usize,
    pub end: usize,
    pub children: Vec<Node>,
    /// Pattern bind: byte range of the bound identifier.
    pub bind: Option<(usize, usize)>,
}

impl Node {
    pub fn new(kind: Nk, start: usize, end: usize) -> Node {
        Node { kind, sub: 0, start, end, children: Vec::new(), bind: None }
    }
    pub fn lit(&self) -> Option<Lit> {
        if self.kind == Nk::Literal {
            Some(match self.sub {
                0 => Lit::Integer,
                1 => Lit::Float,
                2 => Lit::Path,
                _ => Lit::Uri,
            })
        } else {
            None
        }
    }
    pub fn op(&self) -> Option<Op> {
        if self.kind == Nk::BinOp {
            Some(match self.sub {
                0 => Op::Add,
                1 => Op::Sub,
                2 => Op::Mul,
                3 => Op::Div,
                4 => Op::Update,
                5 => Op::Concat,
                6 => Op::Eq,
                7 => Op::Ne,
                8 => Op::Lt,
                9 => Op::Gt,
                10 => Op::Le,
                11 => Op::Ge,
                12 => Op::And,
                13 => Op::Or,
                _ => Op::Imply,
            })
        } else {
            None
        }
    }
    pub fn uop(&self) -> Option<UOp> {
        if self.kind == Nk::UnaryOp {
            Some(if self.sub == 0 { UOp::Invert } else { UOp::Negate })
        } else {
            None
        }
    }
    pub fn is_rec(&self) -> bool {
        self.kind == Nk::AttrSet && self.sub == 1
    }

    /// Depth-first iteration over this node and all descendants.
    pub fn walk<'n>(&'n self, f: &mut dyn FnMut(&'n Node)) {
        f(self);
        for c in &self.children {
            c.walk(f);
        }
    }
}

