//! Recursive descent parser with error recovery.

use crate::tok::{Tk, Tok};
use crate::tree::{Assoc, Lit, Nk, Node, Op, UOp};

#[derive(Clone, Debug)]
pub struct PErr {
    pub start: usize,
    pub end: usize,
    pub msg: String,
}

pub struct ParseResult {
    pub root: Node,
    pub errors: Vec<PErr>,
}

const ATOM_SET: &[Tk] = &[
    Tk::LParen,
    Tk::Rec,
    Tk::LBrace,
    Tk::LBracket,
    Tk::StringStart,
    Tk::Ident,
];

const SEL_SET: &[Tk] = &[Tk::Ident, Tk::Or];

pub struct Parser<'a> {
    toks: Vec<Tok>,
    src: &'a str,
    sig: Vec<usize>,
    si: usize,
    errors: Vec<PErr>,
}

fn set_str(set: &[Tk]) -> String {
    set.iter()
        .map(|t| t.name())
        .collect::<Vec<_>>()
        .join(", ")
}

impl<'a> Parser<'a> {
    pub fn parse(src: &'a str) -> ParseResult {
        let toks = Lexer_::lex(src);
        let sig: Vec<usize> = toks
            .iter()
            .enumerate()
            .filter(|(_, t)| !t.kind.is_trivia())
            .map(|(i, _)| i)
            .collect();
        let mut p = Parser { toks, src, sig, si: 0, errors: Vec::new() };
        let root = p.root();
        ParseResult { root, errors: p.errors }
    }

    fn cur_kind(&self) -> Option<Tk> {
        self.sig.get(self.si).map(|i| self.toks[*i].kind)
    }
    fn cur_tok(&self) -> Option<&Tok> {
        self.sig.get(self.si).map(|i| &self.toks[*i])
    }
    fn cur_start(&self) -> usize {
        self.cur_tok().map(|t| t.start).unwrap_or(self.src.len())
    }
    fn cur_end(&self) -> usize {
        self.cur_tok().map(|t| t.end).unwrap_or(self.src.len())
    }
    fn eof(&self) -> bool {
        self.si >= self.sig.len()
    }

    /// Text of source range.
    pub fn text(&self, a: usize, b: usize) -> &'a str {
        &self.src[a..b]
    }

    /// Byte offset of the last significant token's end (used for region ends).
    fn prev_end(&self) -> usize {
        if self.si == 0 {
            0
        } else {
            self.toks[self.sig[self.si - 1]].end
        }
    }

    fn advance(&mut self) {
        if !self.eof() {
            self.si += 1;
        }
    }

    fn eat(&mut self, k: Tk) -> bool {
        if self.cur_kind() == Some(k) {
            self.advance();
            true
        } else {
            false
        }
    }

    /// Compute the error region: from `from` up to (exclusive) the first token
    /// in `sync`, then trim trailing trivia.
    fn region(&self, from: usize, sync: &[Tk]) -> (usize, usize) {
        let mut end = self.cur_end();
        // find first sync token strictly after the current token
        let mut j = self.si;
        loop {
            j += 1;
            if j >= self.sig.len() {
                end = self.src.len();
                break;
            }
            let t = &self.toks[self.sig[j]];
            if sync.contains(&t.kind) {
                end = t.start;
                break;
            }
            end = t.end;
        }
        if end < from {
            end = from;
        }
        // trim trailing trivia
        let mut e = end;
        while e > from {
            let ch = self.src.as_bytes()[e - 1];
            if ch.is_ascii_whitespace() {
                e -= 1;
            } else {
                break;
            }
        }
        (from, e)
    }

    /// Report "Unexpected TOKEN_X at A..B, wanted any of [...]" or the generic form.
    fn err_expected(&mut self, want: &[Tk], sync: &[Tk]) {
        if self.eof() {
            self.err_eof(want);
            return;
        }
        let kind = self.cur_kind().unwrap();
        let start = self.cur_start();
        let (s, e) = self.region(start, sync);
        let msg = if want.is_empty() {
            format!("Unexpected token at {}..{}", s, e)
        } else {
            format!(
                "Unexpected {} at {}..{}, wanted any of [{}]",
                kind.name(),
                s,
                e,
                set_str(want)
            )
        };
        self.errors.push(PErr { start: s, end: e, msg });
    }

    /// Report a generic unexpected token.
    fn err_generic(&mut self) {
        self.err_expected(&[], &[]);
    }

    fn err_eof(&mut self, want: &[Tk]) {
        let p = self.src.len();
        let msg = if want.is_empty() {
            "Unexpected end of file".to_string()
        } else {
            format!(
                "Unexpected end of file, wanted any of [{}]",
                set_str(want)
            )
        };
        self.errors.push(PErr { start: p, end: p, msg });
    }

    /// Skip tokens until a sync token, returning the region consumed.
    fn skip_to(&mut self, sync: &[Tk]) -> (usize, usize) {
        let start = self.cur_start();
        let mut end = self.cur_end();
        while !self.eof() {
            if sync.contains(&self.cur_kind().unwrap()) {
                break;
            }
            end = self.cur_end();
            self.advance();
        }
        (start, end)
    }

    // ---------------------------------------------------------------- root

    fn root(&mut self) -> Node {
        let start = self.cur_start();
        if self.eof() {
            let mut n = Node::new(Nk::Root, 0, self.src.len());
            return n;
        }
        let e = self.expr();
        let mut n = Node::new(Nk::Root, start, e.end);
        n.children.push(e);
        // trailing junk
        if !self.eof() {
            let (s, en) = self.region(self.cur_start(), &[]);
            self.errors.push(PErr {
                start: s,
                end: en,
                msg: format!("Unexpected token at {}..{}", s, en),
            });
            self.skip_to(&[]);
        }
        n.end = self.src.len();
        n
    }

    // ------------------------------------------------------------ operators

    fn peek_op(&self) -> Option<Op> {
        self.cur_kind().and_then(Op::from_tk)
    }

    /// Full expression (keyword-led heads allowed).
    fn expr(&mut self) -> Node {
        self.expr_min(0)
    }

    fn expr_min(&mut self, min: u8) -> Node {
        let mut lhs = self.operand();
        loop {
            let op = match self.peek_op() {
                Some(o) if o.prec() >= min => o,
                _ => break,
            };
            let prec = op.prec();
            self.advance();
            let assoc = op.assoc();
            let rhs_min = match assoc {
                Assoc::Right => prec,
                _ => prec + 1,
            };
            let rhs = self.rhs_min(rhs_min, op);
            let span = (lhs.start, rhs.end);
            let mut n = Node::new(Nk::BinOp, span.0, span.1);
            n.sub = match op {
                Op::Add => 0,
                Op::Sub => 1,
                Op::Mul => 2,
                Op::Div => 3,
                Op::Update => 4,
                Op::Concat => 5,
                Op::Eq => 6,
                Op::Ne => 7,
                Op::Lt => 8,
                Op::Gt => 9,
                Op::Le => 10,
                Op::Ge => 11,
                Op::And => 12,
                Op::Or => 13,
                Op::Imply => 14,
            };
            n.children.push(lhs);
            n.children.push(rhs);
            lhs = n;
            if assoc == Assoc::None {
                break;
            }
        }
        lhs
    }

    /// RHS of a binary operator: keyword heads are not allowed.
    fn rhs_min(&mut self, min: u8, _op: Op) -> Node {
        if self.eof() {
            let _ = self.src.len();
            self.err_eof(&[]);
            return Node::new(Nk::Error, self.src.len(), self.src.len());
        }
        if matches!(self.cur_kind(), Some(Tk::Let) | Some(Tk::If) | Some(Tk::Assert)) {
            self.err_expected(ATOM_SET, &[]);
            let (s, e) = self.skip_to(&[]);
            let mut n = Node::new(Nk::Error, s, e);
            n.start = s;
            n.end = e;
            return n;
        }
        let mut lhs = self.select();
        loop {
            let op = match self.peek_op() {
                Some(o) if o.prec() >= min => o,
                _ => break,
            };
            let prec = op.prec();
            self.advance();
            let assoc = op.assoc();
            let rhs_min = match assoc {
                Assoc::Right => prec,
                _ => prec + 1,
            };
            if self.eof() {
                self.err_eof(&[]);
                let n = Node::new(Nk::Error, self.src.len(), self.src.len());
                let mut bn = Node::new(Nk::BinOp, lhs.start, self.src.len());
                bn.sub = opidx(op);
                bn.children.push(lhs);
                bn.children.push(n);
                lhs = bn;
                break;
            }
            let rhs = self.rhs_min(rhs_min, op);
            let mut n = Node::new(Nk::BinOp, lhs.start, rhs.end);
            n.sub = opidx(op);
            n.children.push(lhs);
            n.children.push(rhs);
            lhs = n;
            if assoc == Assoc::None {
                break;
            }
        }
        lhs
    }

    /// An expression that may start with `let`/`if`/`assert`.
    fn operand(&mut self) -> Node {
        if self.eof() {
            return Node::new(Nk::Error, self.src.len(), self.src.len());
        }
        match self.cur_kind().unwrap() {
            Tk::Let => self.let_expr(),
            Tk::If => self.if_expr(),
            Tk::Assert => self.assert_expr(),
            Tk::Invert | Tk::Minus => self.unary(),
            _ => self.select(),
        }
    }

    fn unary(&mut self) -> Node {
        let start = self.cur_start();
        let k = self.cur_kind().unwrap();
        self.advance();
        let operand = self.unary_operand();
        let mut n = Node::new(Nk::UnaryOp, start, operand.end);
        n.sub = if k == Tk::Invert { 0 } else { 1 };
        n.children.push(operand);
        n
    }

    fn unary_operand(&mut self) -> Node {
        if self.eof() {
            self.err_eof(&[]);
            return Node::new(Nk::Error, self.src.len(), self.src.len());
        }
        match self.cur_kind().unwrap() {
            Tk::Invert | Tk::Minus => self.unary(),
            Tk::Let | Tk::If | Tk::Assert => self.operand(),
            _ => self.select(),
        }
    }

    // ------------------------------------------------------------ select chain

    fn select(&mut self) -> Node {
        let base = self.simple();
        self.select_from(base)
    }

    fn select_from(&mut self, mut base: Node) -> Node {
        loop {
            match self.cur_kind() {
                Some(Tk::Select) => {
                    self.advance();
                    let attrs = self.attr_path(true);
                    if attrs.is_empty() {
                        break;
                    }
                    let mut n = Node::new(Nk::Select, base.start, attrs.last().unwrap().end);
                    n.children.push(base);
                    for a in attrs {
                        n.children.push(a);
                    }
                    base = n;
                }
                Some(Tk::Question) => {
                    let qstart = self.cur_start();
                    self.advance();
                    let attrs = self.attr_path(false);
                    if attrs.is_empty() {
                        break;
                    }
                    let end = attrs.last().unwrap().end;
                    let mut n = Node::new(Nk::HasAttr, base.start, end);
                    n.children.push(base);
                    for a in attrs {
                        n.children.push(a);
                    }
                    base = n;
                    let _ = qstart;
                }
                _ => break,
            }
        }
        base
    }

    fn attr_path(&mut self, select: bool) -> Vec<Node> {
        let mut out = Vec::new();
        loop {
            match self.cur_kind() {
                Some(Tk::Ident) | Some(Tk::Or) => {
                    let t = self.cur_tok().unwrap();
                    let mut a = Node::new(Nk::Attr, t.start, t.end);
                    out.push(a);
                    self.advance();
                }
                _ => {
                    let sync: &[Tk] = if select { &[] } else { &[] };
                    self.err_expected(SEL_SET, sync);
                    let (s, e) = self.skip_to(&[]);
                    if out.is_empty() {
                        let _ = s;
                        let mut n = Node::new(Nk::Error, s, e);
                        out.push(n);
                    } else {
                        // set end of last attr to include skipped region
                        if let Some(last) = out.last_mut() {
                            last.end = e;
                        }
                    }
                    break;
                }
            }
            if self.cur_kind() == Some(Tk::Select) {
                self.advance();
            } else {
                break;
            }
        }
        out
    }

    // ------------------------------------------------------------ application

    fn simple(&mut self) -> Node {
        // application: atom applied to select-expressions
        let mut lhs = self.atom();
        loop {
            if self.eof() {
                break;
            }
            if !self.can_start_select() {
                break;
            }
            let arg = self.select();
            let mut n = Node::new(Nk::Apply, lhs.start, arg.end);
            n.children.push(lhs);
            n.children.push(arg);
            lhs = n;
        }
        lhs
    }

    fn can_start_select(&self) -> bool {
        match self.cur_kind() {
            Some(Tk::LParen) | Some(Tk::Rec) | Some(Tk::LBrace) | Some(Tk::LBracket)
            | Some(Tk::StringStart) | Some(Tk::Ident) | Some(Tk::Integer) | Some(Tk::Float)
            | Some(Tk::Path) | Some(Tk::Uri) => true,
            _ => false,
        }
    }

    // ------------------------------------------------------------ atoms

    fn atom(&mut self) -> Node {
        if self.eof() {
            self.err_eof(&[]);
            return Node::new(Nk::Error, self.src.len(), self.src.len());
        }
        match self.cur_kind().unwrap() {
            Tk::LParen => self.paren(),
            Tk::LBracket => self.list(),
            Tk::LBrace => {
                // pattern or attribute set
                self.pattern_or_set(false)
            }
            Tk::Rec => {
                self.advance();
                if self.cur_kind() == Some(Tk::LBrace) {
                    self.pattern_or_set(true)
                } else {
                    self.err_expected(&[Tk::LBrace], &[]);
                    let (s, e) = self.skip_to(&[]);
                    let mut n = Node::new(Nk::AttrSet, self.prev_end() - 3, e);
                    n.sub = 1;
                    let _ = s;
                    n
                }
            }
            Tk::StringStart => self.string(),
            Tk::Ident => {
                let t = self.cur_tok().unwrap();
                let mut n = Node::new(Nk::Ident, t.start, t.end);
                // possible lambda: ident ':' or ident '@' ... ':'
                if self.next_is_lambda_head() {
                    return self.lambda_from_ident(t.start, t.end);
                }
                self.advance();
                n
            }
            Tk::Integer | Tk::Float | Tk::Path | Tk::Uri => {
                let t = self.cur_tok().unwrap();
                let mut n = Node::new(Nk::Literal, t.start, t.end);
                n.sub = match t.kind {
                    Tk::Integer => 0,
                    Tk::Float => 1,
                    Tk::Path => 2,
                    _ => 3,
                };
                self.advance();
                n
            }
            _ => {
                self.err_expected(ATOM_SET, &[]);
                let (s, e) = self.skip_to(&[]);
                Node::new(Nk::Error, s, e)
            }
        }
    }

    fn next_is_lambda_head(&self) -> bool {
        // look ahead past trivia for ':' or '@'
        let mut j = self.si + 1;
        while j < self.sig.len() {
            let k = self.toks[self.sig[j]].kind;
            match k {
                Tk::Colon | Tk::PatEntry => return true,
                _ => return false,
            }
        }
        false
    }

    fn lambda_from_ident(&mut self, start: usize, end: usize) -> Node {
        let mut params = Node::new(Nk::Ident, start, end);
        // bind?
        if self.cur_kind() == Some(Tk::PatEntry) {
            self.advance();
            let st = self.pattern_start();
            let p = self.pattern();
            let mut pat = p;
            pat.bind = Some((start, end));
            let _ = st;
            params = pat;
        }
        self.expect_colon();
        let body = self.operand();
        let mut n = Node::new(Nk::Lambda, start, body.end);
        n.children.push(params);
        n.children.push(body);
        n
    }

    fn pattern_start(&mut self) -> usize {
        self.cur_start()
    }

    fn expect_colon(&mut self) {
        if self.cur_kind() == Some(Tk::Colon) {
            self.advance();
        } else {
            self.err_expected(&[Tk::Colon], &[]);
            let _ = self.skip_to(&[]);
        }
    }

    fn paren(&mut self) -> Node {
        let start = self.cur_start();
        self.advance(); // '('
        if self.cur_kind() == Some(Tk::RParen) {
            let end = self.cur_end();
            self.advance();
            return Node::new(Nk::Paren, start, end);
        }
        let inner = self.expr();
        let end;
        if self.cur_kind() == Some(Tk::RParen) {
            end = self.cur_end();
            self.advance();
        } else {
            self.err_eof(&[]);
            end = self.src.len();
        }
        let mut n = Node::new(Nk::Paren, start, end);
        n.children.push(inner);
        n
    }

    fn list(&mut self) -> Node {
        let start = self.cur_start();
        self.advance(); // '['
        let mut items = Vec::new();
        loop {
            match self.cur_kind() {
                Some(Tk::RBracket) => {
                    let end = self.cur_end();
                    self.advance();
                    let mut n = Node::new(Nk::List, start, end);
                    n.children = items;
                    return n;
                }
                None => {
                    self.err_eof(&[]);
                    let mut n = Node::new(Nk::List, start, self.src.len());
                    n.children = items;
                    return n;
                }
                _ => {
                    let it = self.list_item();
                    items.push(it);
                }
            }
        }
    }

    fn list_item(&mut self) -> Node {
        if matches!(self.cur_kind(), Some(Tk::Let) | Some(Tk::If) | Some(Tk::Assert)) {
            self.err_expected(ATOM_SET, &[]);
            let (s, e) = self.skip_to(&[]);
            return Node::new(Nk::Error, s, e);
        }
        self.expr_min(8)
    }

    fn string(&mut self) -> Node {
        let start = self.cur_start();
        // consume StringStart, contents, interpolations, StringEnd
        let mut children = Vec::new();
        loop {
            match self.cur_kind() {
                Some(Tk::StringStart) => {
                    self.advance();
                }
                Some(Tk::StringContent) => {
                    self.advance();
                }
                Some(Tk::InterpolStart) => {
                    let s = self.cur_start();
                    self.advance();
                    let e = self.expr();
                    if self.cur_kind() == Some(Tk::RBrace) {
                        let en = self.cur_end();
                        self.advance();
                        let mut d = Node::new(Nk::Dyn, s, en);
                        d.children.push(e);
                        children.push(d);
                    } else {
                        let mut d = Node::new(Nk::Dyn, s, e.end);
                        d.children.push(e);
                        children.push(d);
                    }
                }
                Some(Tk::StringEnd) => {
                    let end = self.cur_end();
                    self.advance();
                    let mut n = Node::new(Nk::Str, start, end);
                    n.children = children;
                    return n;
                }
                None => {
                    self.err_eof(&[]);
                    let mut n = Node::new(Nk::Str, start, self.src.len());
                    n.children = children;
                    return n;
                }
                Some(_) => {
                    // malformed
                    self.err_expected(
                        &[Tk::StringEnd, Tk::StringContent, Tk::InterpolStart],
                        &[],
                    );
                    let (s, e) = self.skip_to(&[]);
                    let mut n = Node::new(Nk::Str, s, e);
                    n.children = children;
                    return n;
                }
            }
        }
    }

    /// `{ ... }` used as an attribute set or a lambda pattern.
    fn pattern_or_set(&mut self, rec: bool) -> Node {
        let start = self.cur_start();
        self.advance(); // '{'
        let mut entries: Vec<Node> = Vec::new();
        let mut bind: Option<(usize, usize)> = None;
        loop {
            match self.cur_kind() {
                Some(Tk::RBrace) => {
                    let end = self.cur_end();
                    self.advance();
                    let mut n = Node::new(Nk::AttrSet, start, end);
                    n.sub = if rec { 1 } else { 0 };
                    n.children = entries;
                    n.bind = bind;
                    // possible lambda: pattern ':' or '@' ident ':'
                    if self.cur_kind() == Some(Tk::PatEntry) {
                        self.advance();
                        let b = self.expect_ident();
                        if let Some(b) = b {
                            self.advance();
                            bind = Some((b.start, b.end));
                        }
                        self.expect_colon();
                        let body = self.operand();
                        let mut lam = Node::new(Nk::Lambda, start, body.end);
                        let mut pat = Node::new(Nk::Pattern, start, end);
                        pat.children = entries;
                        pat.bind = bind;
                        lam.children.push(pat);
                        lam.children.push(body);
                        return lam;
                    }
                    if self.cur_kind() == Some(Tk::Colon) {
                        self.advance();
                        let body = self.operand();
                        let mut lam = Node::new(Nk::Lambda, start, body.end);
                        let mut pat = Node::new(Nk::Pattern, start, end);
                        pat.children = entries;
                        pat.bind = bind;
                        lam.children.push(pat);
                        lam.children.push(body);
                        return lam;
                    }
                    return n;
                }
                Some(Tk::PatEntry) => {
                    // `{ ... } @ ident :`  -- handled at '}' ; but bind may come first
                    self.advance();
                    let b = self.expect_ident();
                    if let Some(b) = b {
                        let bd = (b.start, b.end);
                        bind = Some(bd);
                        self.advance();
                    }
                    self.expect_colon();
                    let body = self.operand();
                    let end = self.prev_end();
                    let mut lam = Node::new(Nk::Lambda, start, body.end);
                    let mut pat = Node::new(Nk::Pattern, start, end);
                    pat.children = entries;
                    pat.bind = bind;
                    lam.children.push(pat);
                    lam.children.push(body);
                    return lam;
                }
                None => {
                    self.err_eof(&[]);
                    let mut n = Node::new(Nk::AttrSet, start, self.src.len());
                    n.sub = if rec { 1 } else { 0 };
                    n.children = entries;
                    n.bind = bind;
                    return n;
                }
                _ => {
                    let e = self.entry();
                    entries.push(e);
                }
            }
        }
    }

    fn expect_ident(&mut self) -> Option<Tok> {
        if self.cur_kind() == Some(Tk::Ident) {
            Some(*self.cur_tok().unwrap())
        } else {
            self.err_expected(&[Tk::Ident], &[]);
            None
        }
    }

    /// One entry of an attribute set or let binding.
    fn entry(&mut self) -> Node {
        // inherit?
        if self.cur_kind() == Some(Tk::Ident) {
            let t = self.cur_tok().unwrap();
            if self.text(t.start, t.end) == "inherit" {
                // note: `inherit` is an Ident token in rnix? verify below
            }
        }
        match self.cur_kind() {
            Some(Tk::Ident) if self.is_kw_ident("inherit") => self.inherit_entry(),
            _ => self.key_value(),
        }
    }

    fn is_kw_ident(&self, w: &str) -> bool {
        match self.cur_tok() {
            Some(t) => self.text(t.start, t.end) == w,
            None => false,
        }
    }

    fn inherit_entry(&mut self) -> Node {
        let start = self.cur_start();
        self.advance(); // 'inherit'
        let mut children = Vec::new();
        let mut from: Option<Node> = None;
        if self.cur_kind() == Some(Tk::LParen) {
            let e = self.paren();
            from = Some(e);
        }
        loop {
            match self.cur_kind() {
                Some(Tk::Ident) | Some(Tk::Or) | Some(Tk::StringStart) => {
                    let t = self.cur_tok().unwrap();
                    let mut a = Node::new(Nk::Attr, t.start, t.end);
                    self.advance();
                    // string attrs may contain interpolations
                    children.push(a);
                }
                Some(Tk::Semicolon) => {
                    let end = self.cur_end();
                    self.advance();
                    let mut n = Node::new(Nk::Inherit, start, end);
                    if let Some(f) = from {
                        n.children.push(f);
                    }
                    n.children.extend(children);
                    return n;
                }
                None => {
                    self.err_eof(&[Tk::Semicolon]);
                    let mut n = Node::new(Nk::Inherit, start, self.src.len());
                    if let Some(f) = from {
                        n.children.push(f);
                    }
                    n.children.extend(children);
                    return n;
                }
                _ => {
                    self.err_expected(SEL_SET, &[]);
                    let (s, e) = self.skip_to(&[]);
                    let mut n = Node::new(Nk::Inherit, start, e);
                    if let Some(f) = from {
                        n.children.push(f);
                    }
                    n.children.extend(children);
                    let _ = s;
                    return n;
                }
            }
        }
    }

    fn key_value(&mut self) -> Node {
        let start = self.cur_start();
        // key: attr path (idents / strings / interpolations separated by '.')
        let mut children = Vec::new();
        let mut have_key = false;
        loop {
            match self.cur_kind() {
                Some(Tk::Ident) | Some(Tk::Or) => {
                    let t = self.cur_tok().unwrap();
                    let mut a = Node::new(Nk::Attr, t.start, t.end);
                    self.advance();
                    children.push(a);
                    have_key = true;
                }
                Some(Tk::StringStart) => {
                    let s = self.string();
                    children.push(s);
                    have_key = true;
                }
                Some(Tk::InterpolStart) => {
                    let s = self.cur_start();
                    self.advance();
                    let e = self.expr();
                    let mut en = e.end;
                    if self.cur_kind() == Some(Tk::RBrace) {
                        en = self.cur_end();
                        self.advance();
                    }
                    let mut d = Node::new(Nk::Dyn, s, en);
                    d.children.push(e);
                    children.push(d);
                    have_key = true;
                }
                Some(Tk::Select) => {
                    self.advance();
                }
                _ => break,
            }
        }
        if !have_key {
            self.err_expected(SEL_SET, &[]);
            let (s, e) = self.skip_to(&[]);
            return Node::new(Nk::Error, s, e);
        }
        if self.cur_kind() == Some(Tk::Assign) {
            self.advance();
            let v = self.value_expr();
            let mut n = Node::new(Nk::KeyValue, start, v.end);
            n.children.extend(children);
            n.children.push(v);
            // expect ';'
            if self.cur_kind() == Some(Tk::Semicolon) {
                self.advance();
            } else {
                self.err_expected(&[Tk::Semicolon], &[Tk::Semicolon]);
                let (s, e) = self.skip_to(&[Tk::Semicolon]);
                n.end = e;
            }
            n
        } else {
            self.err_expected(&[Tk::Assign], &[Tk::Semicolon]);
            let (s, e) = self.skip_to(&[Tk::Semicolon]);
            let mut n = Node::new(Nk::KeyValue, start, e);
            n.children.extend(children);
            n
        }
    }

    /// Value of a binding: keyword-led expressions allowed.
    fn value_expr(&mut self) -> Node {
        self.expr()
    }

    // ------------------------------------------------------------ keyword forms

    fn let_expr(&mut self) -> Node {
        let start = self.cur_start();
        self.advance(); // 'let'
        // legacy: `let { ... }`
        if self.cur_kind() == Some(Tk::LBrace) {
            let set = self.attr_set_body(true);
            let mut n = Node::new(Nk::Let, start, set.end);
            n.sub = 1; // legacy
            n.children.extend(set.children);
            n.end = set.end;
            n.bind = Some((set.start, set.end));
            return n;
        }
        let mut entries = Vec::new();
        loop {
            match self.cur_kind() {
                Some(Tk::In) => {
                    let in_tok = self.cur_tok().unwrap();
                    self.advance();
                    let body = self.operand();
                    let mut n = Node::new(Nk::Let, start, body.end);
                    n.sub = 0;
                    n.children.extend(entries);
                    n.children.push(body);
                    let _ = in_tok;
                    return n;
                }
                None => {
                    self.err_eof(&[]);
                    let n = Node::new(Nk::Let, start, self.src.len());
                    let mut n2 = Node::new(Nk::Let, start, self.src.len());
                    n2.children = entries;
                    let _ = n;
                    self.errors.push(PErr {
                        start: self.src.len(),
                        end: self.src.len(),
                        msg: "Unexpected end of file".to_string(),
                    });
                    return n2;
                }
                _ => {
                    let e = self.let_entry();
                    entries.push(e);
                }
            }
        }
    }

    fn let_entry(&mut self) -> Node {
        match self.cur_kind() {
            Some(Tk::Ident) if self.is_kw_ident("inherit") => self.inherit_entry(),
            Some(Tk::In) => {
                // `in` in binding position -> error handled by caller
                let t = self.cur_tok().unwrap();
                let mut n = Node::new(Nk::Error, t.start, t.end);
                self.err_expected(SEL_SET, &[Tk::Semicolon]);
                let _ = self.skip_to(&[Tk::Semicolon]);
                n.end = self.prev_end();
                n
            }
            _ => self.key_value(),
        }
    }

    fn attr_set_body(&mut self, rec: bool) -> Node {
        let start = self.cur_start();
        self.advance(); // '{'
        let mut entries = Vec::new();
        loop {
            match self.cur_kind() {
                Some(Tk::RBrace) => {
                    let end = self.cur_end();
                    self.advance();
                    let mut n = Node::new(Nk::AttrSet, start, end);
                    n.sub = if rec { 1 } else { 0 };
                    n.children = entries;
                    return n;
                }
                None => {
                    self.err_eof(&[]);
                    let mut n = Node::new(Nk::AttrSet, start, self.src.len());
                    n.sub = if rec { 1 } else { 0 };
                    n.children = entries;
                    return n;
                }
                _ => {
                    let e = self.entry();
                    entries.push(e);
                }
            }
        }
    }

    fn if_expr(&mut self) -> Node {
        let start = self.cur_start();
        self.advance(); // 'if'
        let cond = self.expr();
        if !self.eat(Tk::Then) {
            self.err_eof(&[Tk::Then]);
        }
        let then = self.expr();
        if !self.eat(Tk::Else) {
            self.err_eof(&[Tk::Else]);
        }
        let els = self.expr();
        let mut n = Node::new(Nk::IfThenElse, start, els.end);
        n.children = vec![cond, then, els];
        n
    }

    fn assert_expr(&mut self) -> Node {
        let start = self.cur_start();
        self.advance(); // 'assert'
        let cond = self.expr();
        if !self.eat(Tk::Semicolon) {
            self.err_eof(&[Tk::Semicolon]);
        }
        let body = self.expr();
        let mut n = Node::new(Nk::Assert, start, body.end);
        n.children = vec![cond, body];
        n
    }
}

fn opidx(op: Op) -> u8 {
    match op {
        Op::Add => 0,
        Op::Sub => 1,
        Op::Mul => 2,
        Op::Div => 3,
        Op::Update => 4,
        Op::Concat => 5,
        Op::Eq => 6,
        Op::Ne => 7,
        Op::Lt => 8,
        Op::Gt => 9,
        Op::Le => 10,
        Op::Ge => 11,
        Op::And => 12,
        Op::Or => 13,
        Op::Imply => 14,
    }
}

/// Minimal wrapper so `parse.rs` does not need to import the lexer crate-wide.
mod Lexer_ {
    use crate::tok::{Lexer, Tok};
    pub fn lex(src: &str) -> Vec<Tok> {
        Lexer::tokenize(src)
    }
}
RSEOF
echo ok"}

