//! Recursive descent parser with error recovery.

use crate::tok::{Lexer, Tk, Tok};
use crate::tree::{Assoc, Nk, Node, Op};

#[derive(Clone, Debug)]
pub struct PErr {
    pub start: usize,
    pub end: usize,
    pub msg: String,
}

pub struct ParseResult {
    pub root: Node,
    pub errors: Vec<PErr>,
}

const ATOM_SET: &[Tk] = &[
    Tk::LParen,
    Tk::Rec,
    Tk::LBrace,
    Tk::LBracket,
    Tk::StringStart,
    Tk::Ident,
];

const SEL_SET: &[Tk] = &[Tk::Ident, Tk::Or];

const SYNC_VAL: &[Tk] = &[Tk::Semicolon, Tk::Ident];
const SYNC_NONE: &[Tk] = &[];
const SYNC_IDENT: &[Tk] = &[Tk::Ident];

pub struct Parser<'a> {
    toks: Vec<Tok>,
    src: &'a str,
    sig: Vec<usize>,
    si: usize,
    errors: Vec<PErr>,
}

fn set_str(set: &[Tk]) -> String {
    set.iter()
        .map(|t| t.name())
        .collect::<Vec<_>>()
        .join(", ")
}

impl<'a> Parser<'a> {
    pub fn parse(src: &'a str) -> ParseResult {
        let toks = Lexer::tokenize(src);
        let sig: Vec<usize> = toks
            .iter()
            .enumerate()
            .filter(|(_, t)| !t.kind.is_trivia())
            .map(|(i, _)| i)
            .collect();
        let mut p = Parser { toks, src, sig, si: 0, errors: Vec::new() };
        let root = p.root();
        ParseResult { root, errors: p.errors }
    }

    pub fn text(&self, a: usize, b: usize) -> &'a str {
        &self.src[a..b]
    }

    fn cur_kind(&self) -> Option<Tk> {
        self.sig.get(self.si).map(|i| self.toks[*i].kind)
    }
    fn cur_tok(&self) -> Option<&Tok> {
        self.sig.get(self.si).map(|i| &self.toks[*i])
    }
    fn cur_start(&self) -> usize {
        self.cur_tok().map(|t| t.start).unwrap_or(self.src.len())
    }
    fn cur_end(&self) -> usize {
        self.cur_tok().map(|t| t.end).unwrap_or(self.src.len())
    }
    fn eof(&self) -> bool {
        self.si >= self.sig.len()
    }
    fn src_len(&self) -> usize {
        self.src.len()
    }

    fn advance(&mut self) {
        if !self.eof() {
            self.si += 1;
        }
    }

    fn eat(&mut self, k: Tk) -> bool {
        if self.cur_kind() == Some(k) {
            self.advance();
            true
        } else {
            false
        }
    }

    /// Compute the error region: from `from` up to (exclusive) the first token
    /// in `sync` (searching from the current token onwards), then trim
    /// trailing trivia.
    fn region(&self, from: usize, sync: &[Tk]) -> (usize, usize) {
        let err_end = self.cur_end();
        let mut end = err_end;
        let mut j = self.si;
        loop {
            if j >= self.sig.len() {
                end = self.src.len();
                break;
            }
            let t = &self.toks[self.sig[j]];
            if j > self.si && sync.contains(&t.kind) {
                end = t.start;
                break;
            }
            if j >= self.si {
                end = t.end;
            }
            j += 1;
        }
        if end < from {
            end = from;
        }
        let mut e = end;
        let bytes = self.src.as_bytes();
        while e > from && bytes[e - 1].is_ascii_whitespace() {
            e -= 1;
        }
        (from, e)
    }

    fn err_expected(&mut self, want: &[Tk], sync: &[Tk]) {
        if self.eof() {
            self.err_eof(want);
            return;
        }
        let kind = self.cur_kind().unwrap();
        let start = self.cur_start();
        let (s, e) = self.region(start, sync);
        let msg = if want.is_empty() {
            format!("Unexpected token at {}..{}", s, e)
        } else {
            format!(
                "Unexpected {} at {}..{}, wanted any of [{}]",
                kind.name(),
                s,
                e,
                set_str(want)
            )
        };
        self.errors.push(PErr { start: s, end: e, msg });
    }

    fn err_eof(&mut self, want: &[Tk]) {
        let p = self.src.len();
        let msg = if want.is_empty() {
            "Unexpected end of file".to_string()
        } else {
            format!("Unexpected end of file, wanted any of [{}]", set_str(want))
        };
        self.errors.push(PErr { start: p, end: p, msg });
    }

    fn skip_to(&mut self, sync: &[Tk]) -> (usize, usize) {
        if self.eof() {
            return (self.src_len(), self.src_len());
        }
        let start = self.cur_start();
        while !self.eof() && !sync.contains(&self.cur_kind().unwrap()) {
            self.advance();
        }
        (start, self.prev_end())
    }

    // ---------------------------------------------------------------- root

    fn root(&mut self) -> Node {
        if self.eof() {
            return Node::new(Nk::Root, 0, self.src.len());
        }
        let e = self.expr();
        let mut n = Node::new(Nk::Root, e.start, e.end);
        n.children.push(e);
        if !self.eof() {
            let (s, en) = self.region(self.cur_start(), &[]);
            self.errors.push(PErr {
                start: s,
                end: en,
                msg: format!("Unexpected token at {}..{}", s, en),
            });
            self.skip_to(&[]);
        }
        n.end = self.src.len();
        n
    }

    // ------------------------------------------------------------ operators

    fn peek_op(&self) -> Option<Op> {
        self.cur_kind().and_then(Op::from_tk)
    }

    fn expr(&mut self) -> Node {
        self.expr_min(0)
    }

    fn expr_min(&mut self, min: u8) -> Node {
        let mut lhs = self.operand();
        loop {
            let op = match self.peek_op() {
                Some(o) if o.prec() >= min => o,
                _ => break,
            };
            let prec = op.prec();
            self.advance();
            let rhs_min = match op.assoc() {
                Assoc::Right => prec,
                _ => prec + 1,
            };
            let rhs = self.rhs_min(rhs_min);
            let mut n = Node::new(Nk::BinOp, lhs.start, rhs.end);
            n.sub = opidx(op);
            n.children.push(lhs);
            n.children.push(rhs);
            lhs = n;
            if op.assoc() == Assoc::None {
                break;
            }
        }
        lhs
    }

    fn rhs_min(&mut self, min: u8) -> Node {
        if self.eof() {
            self.err_eof(&[]);
            return Node::new(Nk::Error, self.src_len(), self.src_len());
        }
        if matches!(self.cur_kind(), Some(Tk::Let) | Some(Tk::If) | Some(Tk::Assert)) {
            self.err_expected(ATOM_SET, SYNC_VAL);
            self.skip_to(SYNC_VAL);
            return Node::new(Nk::Error, self.prev_end(), self.prev_end());
        }
        let mut lhs = self.select();
        loop {
            let op = match self.peek_op() {
                Some(o) if o.prec() >= min => o,
                _ => break,
            };
            let prec = op.prec();
            self.advance();
            let rhs_min = match op.assoc() {
                Assoc::Right => prec,
                _ => prec + 1,
            };
            if self.eof() {
                self.err_eof(&[]);
                let e = Node::new(Nk::Error, self.src_len(), self.src_len());
                let mut bn = Node::new(Nk::BinOp, lhs.start, self.src_len());
                bn.sub = opidx(op);
                bn.children.push(lhs);
                bn.children.push(e);
                lhs = bn;
                break;
            }
            let rhs = self.rhs_min(rhs_min);
            let mut n = Node::new(Nk::BinOp, lhs.start, rhs.end);
            n.sub = opidx(op);
            n.children.push(lhs);
            n.children.push(rhs);
            lhs = n;
            if op.assoc() == Assoc::None {
                break;
            }
        }
        lhs
    }

    fn operand(&mut self) -> Node {
        if self.eof() {
            return Node::new(Nk::Error, self.src_len(), self.src_len());
        }
        match self.cur_kind().unwrap() {
            Tk::Let => self.let_expr(),
            Tk::If => self.if_expr(),
            Tk::Assert => self.assert_expr(),
            Tk::Invert | Tk::Minus => self.unary(),
            _ => self.select(),
        }
    }

    fn unary(&mut self) -> Node {
        let start = self.cur_start();
        let k = self.cur_kind().unwrap();
        self.advance();
        let operand = if self.eof() {
            self.err_eof(&[]);
            Node::new(Nk::Error, self.src_len(), self.src_len())
        } else {
            match self.cur_kind().unwrap() {
                Tk::Invert | Tk::Minus => self.unary(),
                Tk::Let | Tk::If | Tk::Assert => self.operand(),
                _ => self.select(),
            }
        };
        let mut n = Node::new(Nk::UnaryOp, start, operand.end);
        n.sub = if k == Tk::Invert { 0 } else { 1 };
        n.children.push(operand);
        n
    }

    // ------------------------------------------------------------ select chain

    fn select(&mut self) -> Node {
        let base = self.simple();
        self.select_from(base)
    }

    fn select_from(&mut self, mut base: Node) -> Node {
        loop {
            match self.cur_kind() {
                Some(Tk::Select) => {
                    self.advance();
                    let attrs = self.attr_path(SEL_SET, SYNC_NONE);
                    if attrs.is_empty() {
                        break;
                    }
                    let end = attrs.last().unwrap().end;
                    let mut n = Node::new(Nk::Select, base.start, end);
                    n.children.push(base);
                    n.children.extend(attrs);
                    base = n;
                }
                Some(Tk::Question) => {
                    self.advance();
                    let attrs = self.attr_path(SEL_SET, SYNC_NONE);
                    if attrs.is_empty() {
                        break;
                    }
                    let end = attrs.last().unwrap().end;
                    let mut n = Node::new(Nk::HasAttr, base.start, end);
                    n.children.push(base);
                    n.children.extend(attrs);
                    base = n;
                }
                _ => break,
            }
        }
        base
    }

    fn attr_path(&mut self, want: &[Tk], sync: &[Tk]) -> Vec<Node> {
        let mut out: Vec<Node> = Vec::new();
        loop {
            match self.cur_kind() {
                Some(Tk::Ident) | Some(Tk::Or) | Some(Tk::StringStart) => {
                    let t = self.cur_tok().unwrap();
                    let start = t.start;
                    let mut end = t.end;
                    if t.kind == Tk::StringStart {
                        // parse the string (with interpolations)
                        let s = self.string();
                        end = s.end;
                        let mut a = Node::new(Nk::Attr, start, end);
                        a.children = s.children;
                        out.push(a);
                        self.si = self.si;
                    } else {
                        out.push(Node::new(Nk::Attr, start, end));
                        self.advance();
                    }
                }
                _ => {
                    self.err_expected(want, sync);
                    let (s, e) = self.skip_to(sync);
                    let n = Node::new(Nk::Error, s, e);
                    out.push(n);
                    break;
                }
            }
            if self.cur_kind() == Some(Tk::Select) {
                self.advance();
            } else {
                break;
            }
        }
        out
    }

    // ------------------------------------------------------------ application

    fn simple(&mut self) -> Node {
        let mut lhs = self.atom();
        loop {
            if self.eof() || !self.can_start_select() {
                break;
            }
            let arg = self.select();
            let mut n = Node::new(Nk::Apply, lhs.start, arg.end);
            n.children.push(lhs);
            n.children.push(arg);
            lhs = n;
        }
        lhs
    }

    fn can_start_select(&self) -> bool {
        matches!(
            self.cur_kind(),
            Some(Tk::LParen)
                | Some(Tk::Rec)
                | Some(Tk::LBrace)
                | Some(Tk::LBracket)
                | Some(Tk::StringStart)
                | Some(Tk::Ident)
                | Some(Tk::Integer)
                | Some(Tk::Float)
                | Some(Tk::Path)
                | Some(Tk::Uri)
        )
    }

    // ------------------------------------------------------------ atoms

    fn atom(&mut self) -> Node {
        if self.eof() {
            self.err_eof(&[]);
            return Node::new(Nk::Error, self.src_len(), self.src_len());
        }
        match self.cur_kind().unwrap() {
            Tk::LParen => self.paren(),
            Tk::LBracket => self.list(),
            Tk::StringStart => self.string(),
            Tk::Integer | Tk::Float | Tk::Path | Tk::Uri => {
                let t = self.cur_tok().unwrap();
                let mut n = Node::new(Nk::Literal, t.start, t.end);
                n.sub = match t.kind {
                    Tk::Integer => 0,
                    Tk::Float => 1,
                    Tk::Path => 2,
                    _ => 3,
                };
                self.advance();
                n
            }
            Tk::Ident => {
                let t = *self.cur_tok().unwrap();
                match self.next_kind() {
                    Some(Tk::Colon) => {
                        self.advance();
                        self.advance();
                        let body = self.operand();
                        let mut n = Node::new(Nk::Lambda, t.start, body.end);
                        let mut p = Node::new(Nk::Pattern, t.start, t.end);
                        p.sub = 1; // ident pattern
                        n.children.push(p);
                        n.children.push(body);
                        return n;
                    }
                    Some(Tk::PatEntry) => {
                        self.advance();
                        self.advance();
                        let (ps, pe) = self.pattern();
                        let bind = Some((t.start, t.end));
                        self.expect_colon();
                        let body = self.operand();
                        let mut n = Node::new(Nk::Lambda, t.start, body.end);
                        let mut p = Node::new(Nk::Pattern, ps, pe);
                        p.bind = bind;
                        n.children.push(p);
                        n.children.push(body);
                        return n;
                    }
                    _ => {
                        let mut n = Node::new(Nk::Ident, t.start, t.end);
                        self.advance();
                        n
                    }
                }
            }
            Tk::Rec => {
                let rstart = self.cur_start();
                self.advance();
                if self.cur_kind() == Some(Tk::LBrace) {
                    let st = self.cur_start();
                    let set = self.attr_set_body(true, st);
                    let mut n = Node::new(Nk::AttrSet, rstart, set.end);
                    n.sub = 1;
                    n.children = set.children;
                    self.maybe_lambda_from_set(n, rstart)
                } else {
                    self.err_expected(&[Tk::LBrace], SYNC_NONE);
                    let (s, e) = self.skip_to(SYNC_NONE);
                    let mut n = Node::new(Nk::AttrSet, rstart, e);
                    n.sub = 1;
                    let _ = s;
                    n
                }
            }
            Tk::LBrace => {
                let st = self.cur_start();
                let set = self.attr_set_body(false, st);
                self.maybe_lambda_from_set(set, st)
            }
            _ => {
                self.err_expected(ATOM_SET, SYNC_VAL);
                self.skip_to(SYNC_VAL);
                let e = self.prev_end();
                Node::new(Nk::Error, e, e)
            }
        }
    }

    fn next_kind(&self) -> Option<Tk> {
        self.sig.get(self.si + 1).map(|i| self.toks[*i].kind)
    }

    fn maybe_lambda_from_set(&mut self, set: Node, start: usize) -> Node {
        match self.cur_kind() {
            Some(Tk::Colon) => {
                self.advance();
                let body = self.operand();
                let mut n = Node::new(Nk::Lambda, start, body.end);
                let mut p = Node::new(Nk::Pattern, set.start, set.end);
                p.children = set.children;
                p.sub = if set.sub == 1 { 2 } else { 0 };
                n.children.push(p);
                n.children.push(body);
                n
            }
            Some(Tk::PatEntry) => {
                self.advance();
                let bind = self.cur_tok().filter(|t| t.kind == Tk::Ident).map(|t| (t.start, t.end));
                if bind.is_some() {
                    self.advance();
                }
                self.expect_colon();
                let body = self.operand();
                let mut n = Node::new(Nk::Lambda, start, body.end);
                let mut p = Node::new(Nk::Pattern, set.start, set.end);
                p.children = set.children;
                p.sub = if set.sub == 1 { 2 } else { 0 };
                p.bind = bind;
                n.children.push(p);
                n.children.push(body);
                n
            }
            _ => set,
        }
    }

    fn pattern(&mut self) -> (usize, usize) {
        // pattern following `ident @`
        let st = self.cur_start();
        let set = self.attr_set_body(false, st);
        (set.start, set.end)
    }

    fn expect_colon(&mut self) {
        if self.cur_kind() == Some(Tk::Colon) {
            self.advance();
        } else {
            self.err_expected(&[Tk::Colon], SYNC_NONE);
            let _ = self.skip_to(SYNC_NONE);
        }
    }

    fn paren(&mut self) -> Node {
        let start = self.cur_start();
        self.advance();
        if self.cur_kind() == Some(Tk::RParen) {
            let end = self.cur_end();
            self.advance();
            return Node::new(Nk::Paren, start, end);
        }
        let inner = self.expr();
        let end = if self.cur_kind() == Some(Tk::RParen) {
            let e = self.cur_end();
            self.advance();
            e
        } else {
            self.err_eof(&[]);
            self.src_len()
        };
        let mut n = Node::new(Nk::Paren, start, end);
        n.children.push(inner);
        n
    }

    fn list(&mut self) -> Node {
        let start = self.cur_start();
        self.advance();
        let mut items = Vec::new();
        loop {
            match self.cur_kind() {
                Some(Tk::RBracket) => {
                    let end = self.cur_end();
                    self.advance();
                    let mut n = Node::new(Nk::List, start, end);
                    n.children = items;
                    return n;
                }
                None => {
                    self.err_eof(&[]);
                    let mut n = Node::new(Nk::List, start, self.src_len());
                    n.children = items;
                    return n;
                }
                _ => items.push(self.list_item()),
            }
        }
    }

    fn list_item(&mut self) -> Node {
        if matches!(self.cur_kind(), Some(Tk::Let) | Some(Tk::If) | Some(Tk::Assert)) {
            self.err_expected(ATOM_SET, SYNC_VAL);
            self.skip_to(SYNC_VAL);
            return Node::new(Nk::Error, self.prev_end(), self.prev_end());
        }
        self.select()
    }

    fn string(&mut self) -> Node {
        let start = self.cur_start();
        let mut children: Vec<Node> = Vec::new();
        loop {
            match self.cur_kind() {
                Some(Tk::StringStart) | Some(Tk::StringContent) => {
                    self.advance();
                }
                Some(Tk::InterpolStart) => {
                    let s = self.cur_start();
                    self.advance();
                    let e = self.expr();
                    let mut end = e.end;
                    if self.cur_kind() == Some(Tk::RBrace) {
                        end = self.cur_end();
                        self.advance();
                    }
                    let mut d = Node::new(Nk::Dyn, s, end);
                    d.children.push(e);
                    children.push(d);
                }
                Some(Tk::StringEnd) => {
                    let end = self.cur_end();
                    self.advance();
                    let mut n = Node::new(Nk::Str, start, end);
                    n.children = children;
                    return n;
                }
                None => {
                    self.err_eof(&[]);
                    let mut n = Node::new(Nk::Str, start, self.src_len());
                    n.children = children;
                    return n;
                }
                Some(_) => {
                    self.err_expected(
                        &[Tk::StringEnd, Tk::StringContent, Tk::InterpolStart],
                        SYNC_NONE,
                    );
                    let (s, e) = self.skip_to(SYNC_NONE);
                    let mut n = Node::new(Nk::Str, s, e);
                    n.children = children;
                    return n;
                }
            }
        }
    }

    fn attr_set_body(&mut self, rec: bool, start: usize) -> Node {
        self.advance(); // '{'
        let mut entries: Vec<Node> = Vec::new();
        loop {
            match self.cur_kind() {
                Some(Tk::RBrace) => {
                    let end = self.cur_end();
                    self.advance();
                    let mut n = Node::new(Nk::AttrSet, start, end);
                    n.sub = if rec { 1 } else { 0 };
                    n.children = entries;
                    return n;
                }
                None => {
                    self.err_eof(&[]);
                    let mut n = Node::new(Nk::AttrSet, start, self.src_len());
                    n.sub = if rec { 1 } else { 0 };
                    n.children = entries;
                    return n;
                }
                _ => entries.push(self.entry(false)),
            }
        }
    }

    /// One entry of an attribute set or let binding.
    fn entry(&mut self, in_let: bool) -> Node {
        match self.cur_kind() {
            Some(Tk::Inherit) => self.inherit_entry(),
            Some(Tk::In) if in_let => Node::new(Nk::Error, self.cur_start(), self.cur_end()),
            _ => self.key_value(),
        }
    }

    fn inherit_entry(&mut self) -> Node {
        let start = self.cur_start();
        self.advance();
        let mut children = Vec::new();
        let mut from: Option<Node> = None;
        if self.cur_kind() == Some(Tk::LParen) {
            from = Some(self.paren());
        }
        loop {
            match self.cur_kind() {
                Some(Tk::Ident) | Some(Tk::Or) | Some(Tk::StringStart) => {
                    let t = self.cur_tok().unwrap();
                    let start = t.start;
                    if t.kind == Tk::StringStart {
                        let s = self.string();
                        let mut a = Node::new(Nk::Attr, start, s.end);
                        a.children = s.children;
                        children.push(a);
                    } else {
                        children.push(Node::new(Nk::Attr, start, t.end));
                        self.advance();
                    }
                }
                Some(Tk::Semicolon) => {
                    let end = self.cur_end();
                    self.advance();
                    let mut n = Node::new(Nk::Inherit, start, end);
                    if let Some(f) = from {
                        n.children.push(f);
                    }
                    n.children.extend(children);
                    return n;
                }
                None => {
                    self.err_eof(&[Tk::Semicolon]);
                    let mut n = Node::new(Nk::Inherit, start, self.src_len());
                    if let Some(f) = from {
                        n.children.push(f);
                    }
                    n.children.extend(children);
                    return n;
                }
                _ => {
                    self.err_expected(SEL_SET, SYNC_IDENT);
                    self.skip_to(SYNC_IDENT);
                    let end = self.prev_end();
                    let mut n = Node::new(Nk::Inherit, start, end);
                    if let Some(f) = from {
                        n.children.push(f);
                    }
                    n.children.extend(children);
                    return n;
                }
            }
        }
    }

    fn key_value(&mut self) -> Node {
        let start = self.cur_start();
        let mut children: Vec<Node> = Vec::new();
        let mut have_key = false;
        loop {
            match self.cur_kind() {
                Some(Tk::Ident) | Some(Tk::Or) => {
                    let t = self.cur_tok().unwrap();
                    children.push(Node::new(Nk::Attr, t.start, t.end));
                    self.advance();
                    have_key = true;
                }
                Some(Tk::StringStart) => {
                    let s = self.string();
                    children.push(s);
                    have_key = true;
                }
                Some(Tk::InterpolStart) => {
                    let s = self.cur_start();
                    self.advance();
                    let e = self.expr();
                    let mut end = e.end;
                    if self.cur_kind() == Some(Tk::RBrace) {
                        end = self.cur_end();
                        self.advance();
                    }
                    let mut d = Node::new(Nk::Dyn, s, end);
                    d.children.push(e);
                    children.push(d);
                    have_key = true;
                }
                Some(Tk::Select) => {
                    self.advance();
                }
                _ => break,
            }
        }
        if !have_key {
            self.err_expected(SEL_SET, SYNC_NONE);
            self.skip_to(SYNC_NONE);
            let e = self.prev_end();
            return Node::new(Nk::Error, e, e);
        }
        if self.cur_kind() == Some(Tk::Assign) {
            self.advance();
            let v = self.value_expr();
            let mut n = Node::new(Nk::KeyValue, start, v.end);
            n.children.extend(children);
            n.children.push(v);
            if self.cur_kind() == Some(Tk::Semicolon) {
                self.advance();
            } else {
                self.err_expected(&[Tk::Semicolon], SYNC_VAL);
                self.skip_to(SYNC_VAL);
                n.end = self.prev_end();
            }
            n
        } else {
            self.err_expected(&[Tk::Assign], SYNC_VAL);
            self.skip_to(SYNC_VAL);
            let e = self.prev_end();
            let mut n = Node::new(Nk::KeyValue, start, e);
            n.children.extend(children);
            n
        }
    }

    // ------------------------------------------------------------ keyword forms

    fn let_expr(&mut self) -> Node {
        let start = self.cur_start();
        self.advance();
        if self.cur_kind() == Some(Tk::LBrace) {
            let st = self.cur_start();
            let set = self.attr_set_body(true, st);
            let mut n = Node::new(Nk::Let, start, set.end);
            n.sub = 1; // legacy
            n.children.extend(set.children);
            n.bind = Some((set.start, set.end));
            return n;
        }
        let mut entries: Vec<Node> = Vec::new();
        loop {
            match self.cur_kind() {
                Some(Tk::In) => {
                    self.advance();
                    let body = self.operand();
                    let mut n = Node::new(Nk::Let, start, body.end);
                    n.children.extend(entries);
                    n.children.push(body);
                    return n;
                }
                None => {
                    self.err_eof(&[]);
                    self.errors.push(PErr {
                        start: self.src_len(),
                        end: self.src_len(),
                        msg: "Unexpected end of file".to_string(),
                    });
                    let mut n = Node::new(Nk::Let, start, self.src_len());
                    n.children = entries;
                    return n;
                }
                _ => entries.push(self.entry(true)),
            }
        }
    }

    fn if_expr(&mut self) -> Node {
        let start = self.cur_start();
        self.advance();
        let cond = self.expr();
        if !self.eat(Tk::Then) {
            self.err_eof(&[Tk::Then]);
        }
        let then = self.expr();
        if !self.eat(Tk::Else) {
            self.err_eof(&[Tk::Else]);
        }
        let els = self.expr();
        let mut n = Node::new(Nk::IfThenElse, start, els.end);
        n.children = vec![cond, then, els];
        n
    }

    fn assert_expr(&mut self) -> Node {
        let start = self.cur_start();
        self.advance();
        let cond = self.expr();
        if !self.eat(Tk::Semicolon) {
            self.err_eof(&[Tk::Semicolon]);
        }
        let body = self.expr();
        let mut n = Node::new(Nk::Assert, start, body.end);
        n.children = vec![cond, body];
        n
    }
}

fn opidx(op: Op) -> u8 {
    match op {
        Op::Add => 0,
        Op::Sub => 1,
        Op::Mul => 2,
        Op::Div => 3,
        Op::Update => 4,
        Op::Concat => 5,
        Op::Eq => 6,
        Op::Ne => 7,
        Op::Lt => 8,
        Op::Gt => 9,
        Op::Le => 10,
        Op::Ge => 11,
        Op::And => 12,
        Op::Or => 13,
        Op::Imply => 14,
    }
}
RSEOF
echo ok"}

actions.command:
cat > src/parse.rs <<'RSEOF'
//! Recursive descent parser with error recovery.

use crate::tok::{Lexer, Tk, Tok};
use crate::tree::{Assoc, Nk, Node, Op};

#[derive(Clone, Debug)]
pub struct PErr {
    pub start: usize,
    pub end: usize,
    pub msg: String,
}

pub struct ParseResult {
    pub root: Node,
    pub errors: Vec<PErr>,
}

const ATOM_SET: &[Tk] = &[
    Tk::LParen,
    Tk::Rec,
    Tk::LBrace,
    Tk::LBracket,
    Tk::StringStart,
    Tk::Ident,
];

const SEL_SET: &[Tk] = &[Tk::Ident, Tk::Or];

const SYNC_VAL: &[Tk] = &[Tk::Semicolon, Tk::Ident];
const SYNC_NONE: &[Tk] = &[];
const SYNC_IDENT: &[Tk] = &[Tk::Ident];

pub struct Parser<'a> {
    toks: Vec<Tok>,
    src: &'a str,
    sig: Vec<usize>,
    si: usize,
    errors: Vec<PErr>,
}

fn set_str(set: &[Tk]) -> String {
    set.iter()
        .map(|t| t.name())
        .collect::<Vec<_>>()
        .join(", ")
}

impl<'a> Parser<'a> {
    pub fn parse(src: &'a str) -> ParseResult {
        let toks = Lexer::tokenize(src);
        let sig: Vec<usize> = toks
            .iter()
            .enumerate()
            .filter(|(_, t)| !t.kind.is_trivia())
            .map(|(i, _)| i)
            .collect();
        let mut p = Parser { toks, src, sig, si: 0, errors: Vec::new() };
        let root = p.root();
        ParseResult { root, errors: p.errors }
    }

    pub fn text(&self, a: usize, b: usize) -> &'a str {
        &self.src[a..b]
    }

    fn cur_kind(&self) -> Option<Tk> {
        self.sig.get(self.si).map(|i| self.toks[*i].kind)
    }
    fn cur_tok(&self) -> Option<&Tok> {
        self.sig.get(self.si).map(|i| &self.toks[*i])
    }
    fn cur_start(&self) -> usize {
        self.cur_tok().map(|t| t.start).unwrap_or(self.src.len())
    }
    fn cur_end(&self) -> usize {
        self.cur_tok().map(|t| t.end).unwrap_or(self.src.len())
    }
    fn eof(&self) -> bool {
        self.si >= self.sig.len()
    }
    fn src_len(&self) -> usize {
        self.src.len()
    }

    fn advance(&mut self) {
        if !self.eof() {
            self.si += 1;
        }
    }

    fn eat(&mut self, k: Tk) -> bool {
        if self.cur_kind() == Some(k) {
            self.advance();
            true
        } else {
            false
        }
    }

    /// Compute the error region: from `from` up to (exclusive) the first token
    /// in `sync` (searching from the current token onwards), then trim
    /// trailing trivia.
    fn region(&self, from: usize, sync: &[Tk]) -> (usize, usize) {
        let err_end = self.cur_end();
        let mut end = err_end;
        let mut j = self.si;
        loop {
            if j >= self.sig.len() {
                end = self.src.len();
                break;
            }
            let t = &self.toks[self.sig[j]];
            if j > self.si && sync.contains(&t.kind) {
                end = t.start;
                break;
            }
            if j >= self.si {
                end = t.end;
            }
            j += 1;
        }
        if end < from {
            end = from;
        }
        let mut e = end;
        let bytes = self.src.as_bytes();
        while e > from && bytes[e - 1].is_ascii_whitespace() {
            e -= 1;
        }
        (from, e)
    }

    fn err_expected(&mut self, want: &[Tk], sync: &[Tk]) {
        if self.eof() {
            self.err_eof(want);
            return;
        }
        let kind = self.cur_kind().unwrap();
        let start = self.cur_start();
        let (s, e) = self.region(start, sync);
        let msg = if want.is_empty() {
            format!("Unexpected token at {}..{}", s, e)
        } else {
            format!(
                "Unexpected {} at {}..{}, wanted any of [{}]",
                kind.name(),
                s,
                e,
                set_str(want)
            )
        };
        self.errors.push(PErr { start: s, end: e, msg });
    }

    fn err_eof(&mut self, want: &[Tk]) {
        let p = self.src.len();
        let msg = if want.is_empty() {
            "Unexpected end of file".to_string()
        } else {
            format!("Unexpected end of file, wanted any of [{}]", set_str(want))
        };
        self.errors.push(PErr { start: p, end: p, msg });
    }

    fn skip_to(&mut self, sync: &[Tk]) -> (usize, usize) {
        if self.eof() {
            return (self.src_len(), self.src_len());
        }
        let start = self.cur_start();
        while !self.eof() && !sync.contains(&self.cur_kind().unwrap()) {
            self.advance();
        }
        (start, self.prev_end())
    }

    // ---------------------------------------------------------------- root

    fn root(&mut self) -> Node {
        if self.eof() {
            return Node::new(Nk::Root, 0, self.src.len());
        }
        let e = self.expr();
        let mut n = Node::new(Nk::Root, e.start, e.end);
        n.children.push(e);
        if !self.eof() {
            let (s, en) = self.region(self.cur_start(), &[]);
            self.errors.push(PErr {
                start: s,
                end: en,
                msg: format!("Unexpected token at {}..{}", s, en),
            });
            self.skip_to(&[]);
        }
        n.end = self.src.len();
        n
    }

    // ------------------------------------------------------------ operators

    fn peek_op(&self) -> Option<Op> {
        self.cur_kind().and_then(Op::from_tk)
    }

    fn expr(&mut self) -> Node {
        self.expr_min(0)
    }

    fn expr_min(&mut self, min: u8) -> Node {
        let mut lhs = self.operand();
        loop {
            let op = match self.peek_op() {
                Some(o) if o.prec() >= min => o,
                _ => break,
            };
            let prec = op.prec();
            self.advance();
            let rhs_min = match op.assoc() {
                Assoc::Right => prec,
                _ => prec + 1,
            };
            let rhs = self.rhs_min(rhs_min);
            let mut n = Node::new(Nk::BinOp, lhs.start, rhs.end);
            n.sub = opidx(op);
            n.children.push(lhs);
            n.children.push(rhs);
            lhs = n;
            if op.assoc() == Assoc::None {
                break;
            }
        }
        lhs
    }

    fn rhs_min(&mut self, min: u8) -> Node {
        if self.eof() {
            self.err_eof(&[]);
            return Node::new(Nk::Error, self.src_len(), self.src_len());
        }
        if matches!(self.cur_kind(), Some(Tk::Let) | Some(Tk::If) | Some(Tk::Assert)) {
            self.err_expected(ATOM_SET, SYNC_VAL);
            self.skip_to(SYNC_VAL);
            return Node::new(Nk::Error, self.prev_end(), self.prev_end());
        }
        let mut lhs = self.select();
        loop {
            let op = match self.peek_op() {
                Some(o) if o.prec() >= min => o,
                _ => break,
            };
            let prec = op.prec();
            self.advance();
            let rhs_min = match op.assoc() {
                Assoc::Right => prec,
                _ => prec + 1,
            };
            if self.eof() {
                self.err_eof(&[]);
                let e = Node::new(Nk::Error, self.src_len(), self.src_len());
                let mut bn = Node::new(Nk::BinOp, lhs.start, self.src_len());
                bn.sub = opidx(op);
                bn.children.push(lhs);
                bn.children.push(e);
                lhs = bn;
                break;
            }
            let rhs = self.rhs_min(rhs_min);
            let mut n = Node::new(Nk::BinOp, lhs.start, rhs.end);
            n.sub = opidx(op);
            n.children.push(lhs);
            n.children.push(rhs);
            lhs = n;
            if op.assoc() == Assoc::None {
                break;
            }
        }
        lhs
    }

    fn operand(&mut self) -> Node {
        if self.eof() {
            return Node::new(Nk::Error, self.src_len(), self.src_len());
        }
        match self.cur_kind().unwrap() {
            Tk::Let => self.let_expr(),
            Tk::If => self.if_expr(),
            Tk::Assert => self.assert_expr(),
            Tk::Invert | Tk::Minus => self.unary(),
            _ => self.select(),
        }
    }

    fn unary(&mut self) -> Node {
        let start = self.cur_start();
        let k = self.cur_kind().unwrap();
        self.advance();
        let operand = if self.eof() {
            self.err_eof(&[]);
            Node::new(Nk::Error, self.src_len(), self.src_len())
        } else {
            match self.cur_kind().unwrap() {
                Tk::Invert | Tk::Minus => self.unary(),
                Tk::Let | Tk::If | Tk::Assert => self.operand(),
                _ => self.select(),
            }
        };
        let mut n = Node::new(Nk::UnaryOp, start, operand.end);
        n.sub = if k == Tk::Invert { 0 } else { 1 };
        n.children.push(operand);
        n
    }

    // ------------------------------------------------------------ select chain

    fn select(&mut self) -> Node {
        let base = self.simple();
        self.select_from(base)
    }

    fn select_from(&mut self, mut base: Node) -> Node {
        loop {
            match self.cur_kind() {
                Some(Tk::Select) => {
                    self.advance();
                    let attrs = self.attr_path(SEL_SET, SYNC_NONE);
                    if attrs.is_empty() {
                        break;
                    }
                    let end = attrs.last().unwrap().end;
                    let mut n = Node::new(Nk::Select, base.start, end);
                    n.children.push(base);
                    n.children.extend(attrs);
                    base = n;
                }
                Some(Tk::Question) => {
                    self.advance();
                    let attrs = self.attr_path(SEL_SET, SYNC_NONE);
                    if attrs.is_empty() {
                        break;
                    }
                    let end = attrs.last().unwrap().end;
                    let mut n = Node::new(Nk::HasAttr, base.start, end);
                    n.children.push(base);
                    n.children.extend(attrs);
                    base = n;
                }
                _ => break,
            }
        }
        base
    }

    fn attr_path(&mut self, want: &[Tk], sync: &[Tk]) -> Vec<Node> {
        let mut out: Vec<Node> = Vec::new();
        loop {
            match self.cur_kind() {
                Some(Tk::Ident) | Some(Tk::Or) | Some(Tk::StringStart) => {
                    let t = self.cur_tok().unwrap();
                    let start = t.start;
                    let mut end = t.end;
                    if t.kind == Tk::StringStart {
                        // parse the string (with interpolations)
                        let s = self.string();
                        end = s.end;
                        let mut a = Node::new(Nk::Attr, start, end);
                        a.children = s.children;
                        out.push(a);
                        self.si = self.si;
                    } else {
                        out.push(Node::new(Nk::Attr, start, end));
                        self.advance();
                    }
                }
                _ => {
                    self.err_expected(want, sync);
                    let (s, e) = self.skip_to(sync);
                    let n = Node::new(Nk::Error, s, e);
                    out.push(n);
                    break;
                }
            }
            if self.cur_kind() == Some(Tk::Select) {
                self.advance();
            } else {
                break;
            }
        }
        out
    }

    // ------------------------------------------------------------ application

    fn simple(&mut self) -> Node {
        let mut lhs = self.atom();
        loop {
            if self.eof() || !self.can_start_select() {
                break;
            }
            let arg = self.select();
            let mut n = Node::new(Nk::Apply, lhs.start, arg.end);
            n.children.push(lhs);
            n.children.push(arg);
            lhs = n;
        }
        lhs
    }

    fn can_start_select(&self) -> bool {
        matches!(
            self.cur_kind(),
            Some(Tk::LParen)
                | Some(Tk::Rec)
                | Some(Tk::LBrace)
                | Some(Tk::LBracket)
                | Some(Tk::StringStart)
                | Some(Tk::Ident)
                | Some(Tk::Integer)
                | Some(Tk::Float)
                | Some(Tk::Path)
                | Some(Tk::Uri)
        )
    }

    // ------------------------------------------------------------ atoms

    fn atom(&mut self) -> Node {
        if self.eof() {
            self.err_eof(&[]);
            return Node::new(Nk::Error, self.src_len(), self.src_len());
        }
        match self.cur_kind().unwrap() {
            Tk::LParen => self.paren(),
            Tk::LBracket => self.list(),
            Tk::StringStart => self.string(),
            Tk::Integer | Tk::Float | Tk::Path | Tk::Uri => {
                let t = self.cur_tok().unwrap();
                let mut n = Node::new(Nk::Literal, t.start, t.end);
                n.sub = match t.kind {
                    Tk::Integer => 0,
                    Tk::Float => 1,
                    Tk::Path => 2,
                    _ => 3,
                };
                self.advance();
                n
            }
            Tk::Ident => {
                let t = *self.cur_tok().unwrap();
                match self.next_kind() {
                    Some(Tk::Colon) => {
                        self.advance();
                        self.advance();
                        let body = self.operand();
                        let mut n = Node::new(Nk::Lambda, t.start, body.end);
                        let mut p = Node::new(Nk::Pattern, t.start, t.end);
                        p.sub = 1; // ident pattern
                        n.children.push(p);
                        n.children.push(body);
                        return n;
                    }
                    Some(Tk::PatEntry) => {
                        self.advance();
                        self.advance();
                        let (ps, pe) = self.pattern();
                        let bind = Some((t.start, t.end));
                        self.expect_colon();
                        let body = self.operand();
                        let mut n = Node::new(Nk::Lambda, t.start, body.end);
                        let mut p = Node::new(Nk::Pattern, ps, pe);
                        p.bind = bind;
                        n.children.push(p);
                        n.children.push(body);
                        return n;
                    }
                    _ => {
                        let mut n = Node::new(Nk::Ident, t.start, t.end);
                        self.advance();
                        n
                    }
                }
            }
            Tk::Rec => {
                let rstart = self.cur_start();
                self.advance();
                if self.cur_kind() == Some(Tk::LBrace) {
                    let st = self.cur_start();
                    let set = self.attr_set_body(true, st);
                    let mut n = Node::new(Nk::AttrSet, rstart, set.end);
                    n.sub = 1;
                    n.children = set.children;
                    self.maybe_lambda_from_set(n, rstart)
                } else {
                    self.err_expected(&[Tk::LBrace], SYNC_NONE);
                    let (s, e) = self.skip_to(SYNC_NONE);
                    let mut n = Node::new(Nk::AttrSet, rstart, e);
                    n.sub = 1;
                    let _ = s;
                    n
                }
            }
            Tk::LBrace => {
                let st = self.cur_start();
                let set = self.attr_set_body(false, st);
                self.maybe_lambda_from_set(set, st)
            }
            _ => {
                self.err_expected(ATOM_SET, SYNC_VAL);
                self.skip_to(SYNC_VAL);
                let e = self.prev_end();
                Node::new(Nk::Error, e, e)
            }
        }
    }

    fn next_kind(&self) -> Option<Tk> {
        self.sig.get(self.si + 1).map(|i| self.toks[*i].kind)
    }

    fn maybe_lambda_from_set(&mut self, set: Node, start: usize) -> Node {
        match self.cur_kind() {
            Some(Tk::Colon) => {
                self.advance();
                let body = self.operand();
                let mut n = Node::new(Nk::Lambda, start, body.end);
                let mut p = Node::new(Nk::Pattern, set.start, set.end);
                p.children = set.children;
                p.sub = if set.sub == 1 { 2 } else { 0 };
                n.children.push(p);
                n.children.push(body);
                n
            }
            Some(Tk::PatEntry) => {
                self.advance();
                let bind = self.cur_tok().filter(|t| t.kind == Tk::Ident).map(|t| (t.start, t.end));
                if bind.is_some() {
                    self.advance();
                }
                self.expect_colon();
                let body = self.operand();
                let mut n = Node::new(Nk::Lambda, start, body.end);
                let mut p = Node::new(Nk::Pattern, set.start, set.end);
                p.children = set.children;
                p.sub = if set.sub == 1 { 2 } else { 0 };
                p.bind = bind;
                n.children.push(p);
                n.children.push(body);
                n
            }
            _ => set,
        }
    }

    fn pattern(&mut self) -> (usize, usize) {
        // pattern following `ident @`
        let st = self.cur_start();
        let set = self.attr_set_body(false, st);
        (set.start, set.end)
    }

    fn expect_colon(&mut self) {
        if self.cur_kind() == Some(Tk::Colon) {
            self.advance();
        } else {
            self.err_expected(&[Tk::Colon], SYNC_NONE);
            let _ = self.skip_to(SYNC_NONE);
        }
    }

    fn paren(&mut self) -> Node {
        let start = self.cur_start();
        self.advance();
        if self.cur_kind() == Some(Tk::RParen) {
            let end = self.cur_end();
            self.advance();
            return Node::new(Nk::Paren, start, end);
        }
        let inner = self.expr();
        let end = if self.cur_kind() == Some(Tk::RParen) {
            let e = self.cur_end();
            self.advance();
            e
        } else {
            self.err_eof(&[]);
            self.src_len()
        };
        let mut n = Node::new(Nk::Paren, start, end);
        n.children.push(inner);
        n
    }

    fn list(&mut self) -> Node {
        let start = self.cur_start();
        self.advance();
        let mut items = Vec::new();
        loop {
            match self.cur_kind() {
                Some(Tk::RBracket) => {
                    let end = self.cur_end();
                    self.advance();
                    let mut n = Node::new(Nk::List, start, end);
                    n.children = items;
                    return n;
                }
                None => {
                    self.err_eof(&[]);
                    let mut n = Node::new(Nk::List, start, self.src_len());
                    n.children = items;
                    return n;
                }
                _ => items.push(self.list_item()),
            }
        }
    }

    fn list_item(&mut self) -> Node {
        if matches!(self.cur_kind(), Some(Tk::Let) | Some(Tk::If) | Some(Tk::Assert)) {
            self.err_expected(ATOM_SET, SYNC_VAL);
            self.skip_to(SYNC_VAL);
            return Node::new(Nk::Error, self.prev_end(), self.prev_end());
        }
        self.select()
    }

    fn string(&mut self) -> Node {
        let start = self.cur_start();
        let mut children: Vec<Node> = Vec::new();
        loop {
            match self.cur_kind() {
                Some(Tk::StringStart) | Some(Tk::StringContent) => {
                    self.advance();
                }
                Some(Tk::InterpolStart) => {
                    let s = self.cur_start();
                    self.advance();
                    let e = self.expr();
                    let mut end = e.end;
                    if self.cur_kind() == Some(Tk::RBrace) {
                        end = self.cur_end();
                        self.advance();
                    }
                    let mut d = Node::new(Nk::Dyn, s, end);
                    d.children.push(e);
                    children.push(d);
                }
                Some(Tk::StringEnd) => {
                    let end = self.cur_end();
                    self.advance();
                    let mut n = Node::new(Nk::Str, start, end);
                    n.children = children;
                    return n;
                }
                None => {
                    self.err_eof(&[]);
                    let mut n = Node::new(Nk::Str, start, self.src_len());
                    n.children = children;
                    return n;
                }
                Some(_) => {
                    self.err_expected(
                        &[Tk::StringEnd, Tk::StringContent, Tk::InterpolStart],
                        SYNC_NONE,
                    );
                    let (s, e) = self.skip_to(SYNC_NONE);
                    let mut n = Node::new(Nk::Str, s, e);
                    n.children = children;
                    return n;
                }
            }
        }
    }

    fn attr_set_body(&mut self, rec: bool, start: usize) -> Node {
        self.advance(); // '{'
        let mut entries: Vec<Node> = Vec::new();
        loop {
            match self.cur_kind() {
                Some(Tk::RBrace) => {
                    let end = self.cur_end();
                    self.advance();
                    let mut n = Node::new(Nk::AttrSet, start, end);
                    n.sub = if rec { 1 } else { 0 };
                    n.children = entries;
                    return n;
                }
                None => {
                    self.err_eof(&[]);
                    let mut n = Node::new(Nk::AttrSet, start, self.src_len());
                    n.sub = if rec { 1 } else { 0 };
                    n.children = entries;
                    return n;
                }
                _ => entries.push(self.entry(false)),
            }
        }
    }

    /// One entry of an attribute set or let binding.
    fn entry(&mut self, in_let: bool) -> Node {
        match self.cur_kind() {
            Some(Tk::Inherit) => self.inherit_entry(),
            Some(Tk::In) if in_let => Node::new(Nk::Error, self.cur_start(), self.cur_end()),
            _ => self.key_value(),
        }
    }

    fn inherit_entry(&mut self) -> Node {
        let start = self.cur_start();
        self.advance();
        let mut children = Vec::new();
        let mut from: Option<Node> = None;
        if self.cur_kind() == Some(Tk::LParen) {
            from = Some(self.paren());
        }
        loop {
            match self.cur_kind() {
                Some(Tk::Ident) | Some(Tk::Or) | Some(Tk::StringStart) => {
                    let t = self.cur_tok().unwrap();
                    let start = t.start;
                    if t.kind == Tk::StringStart {
                        let s = self.string();
                        let mut a = Node::new(Nk::Attr, start, s.end);
                        a.children = s.children;
                        children.push(a);
                    } else {
                        children.push(Node::new(Nk::Attr, start, t.end));
                        self.advance();
                    }
                }
                Some(Tk::Semicolon) => {
                    let end = self.cur_end();
                    self.advance();
                    let mut n = Node::new(Nk::Inherit, start, end);
                    if let Some(f) = from {
                        n.children.push(f);
                    }
                    n.children.extend(children);
                    return n;
                }
                None => {
                    self.err_eof(&[Tk::Semicolon]);
                    let mut n = Node::new(Nk::Inherit, start, self.src_len());
                    if let Some(f) = from {
                        n.children.push(f);
                    }
                    n.children.extend(children);
                    return n;
                }
                _ => {
                    self.err_expected(SEL_SET, SYNC_IDENT);
                    self.skip_to(SYNC_IDENT);
                    let end = self.prev_end();
                    let mut n = Node::new(Nk::Inherit, start, end);
                    if let Some(f) = from {
                        n.children.push(f);
                    }
                    n.children.extend(children);
                    return n;
                }
            }
        }
    }

    fn key_value(&mut self) -> Node {
        let start = self.cur_start();
        let mut children: Vec<Node> = Vec::new();
        let mut have_key = false;
        loop {
            match self.cur_kind() {
                Some(Tk::Ident) | Some(Tk::Or) => {
                    let t = self.cur_tok().unwrap();
                    children.push(Node::new(Nk::Attr, t.start, t.end));
                    self.advance();
                    have_key = true;
                }
                Some(Tk::StringStart) => {
                    let s = self.string();
                    children.push(s);
                    have_key = true;
                }
                Some(Tk::InterpolStart) => {
                    let s = self.cur_start();
                    self.advance();
                    let e = self.expr();
                    let mut end = e.end;
                    if self.cur_kind() == Some(Tk::RBrace) {
                        end = self.cur_end();
                        self.advance();
                    }
                    let mut d = Node::new(Nk::Dyn, s, end);
                    d.children.push(e);
                    children.push(d);
                    have_key = true;
                }
                Some(Tk::Select) => {
                    self.advance();
                }
                _ => break,
            }
        }
        if !have_key {
            self.err_expected(SEL_SET, SYNC_NONE);
            self.skip_to(SYNC_NONE);
            let e = self.prev_end();
            return Node::new(Nk::Error, e, e);
        }
        if self.cur_kind() == Some(Tk::Assign) {
            self.advance();
            let v = self.value_expr();
            let mut n = Node::new(Nk::KeyValue, start, v.end);
            n.children.extend(children);
            n.children.push(v);
            if self.cur_kind() == Some(Tk::Semicolon) {
                self.advance();
            } else {
                self.err_expected(&[Tk::Semicolon], SYNC_VAL);
                self.skip_to(SYNC_VAL);
                n.end = self.prev_end();
            }
            n
        } else {
            self.err_expected(&[Tk::Assign], SYNC_VAL);
            self.skip_to(SYNC_VAL);
            let e = self.prev_end();
            let mut n = Node::new(Nk::KeyValue, start, e);
            n.children.extend(children);
            n
        }
    }

    // ------------------------------------------------------------ keyword forms

    fn let_expr(&mut self) -> Node {
        let start = self.cur_start();
        self.advance();
        if self.cur_kind() == Some(Tk::LBrace) {
            let st = self.cur_start();
            let set = self.attr_set_body(true, st);
            let mut n = Node::new(Nk::Let, start, set.end);
            n.sub = 1; // legacy
            n.children.extend(set.children);
            n.bind = Some((set.start, set.end));
            return n;
        }
        let mut entries: Vec<Node> = Vec::new();
        loop {
            match self.cur_kind() {
                Some(Tk::In) => {
                    self.advance();
                    let body = self.operand();
                    let mut n = Node::new(Nk::Let, start, body.end);
                    n.children.extend(entries);
                    n.children.push(body);
                    return n;
                }
                None => {
                    self.err_eof(&[]);
                    self.errors.push(PErr {
                        start: self.src_len(),
                        end: self.src_len(),
                        msg: "Unexpected end of file".to_string(),
                    });
                    let mut n = Node::new(Nk::Let, start, self.src_len());
                    n.children = entries;
                    return n;
                }
                _ => entries.push(self.entry(true)),
            }
        }
    }

    fn if_expr(&mut self) -> Node {
        let start = self.cur_start();
        self.advance();
        let cond = self.expr();
        if !self.eat(Tk::Then) {
            self.err_eof(&[Tk::Then]);
        }
        let then = self.expr();
        if !self.eat(Tk::Else) {
            self.err_eof(&[Tk::Else]);
        }
        let els = self.expr();
        let mut n = Node::new(Nk::IfThenElse, start, els.end);
        n.children = vec![cond, then, els];
        n
    }

    fn assert_expr(&mut self) -> Node {
        let start = self.cur_start();
        self.advance();
        let cond = self.expr();
        if !self.eat(Tk::Semicolon) {
            self.err_eof(&[Tk::Semicolon]);
        }
        let body = self.expr();
        let mut n = Node::new(Nk::Assert, start, body.end);
        n.children = vec![cond, body];
        n
    }
}

fn opidx(op: Op) -> u8 {
    match op {
        Op::Add => 0,
        Op::Sub => 1,
        Op::Mul => 2,
        Op::Div => 3,
        Op::Update => 4,
        Op::Concat => 5,
        Op::Eq => 6,
        Op::Ne => 7,
        Op::Lt => 8,
        Op::Gt => 9,
        Op::Le => 10,
        Op::Ge => 11,
        Op::And => 12,
        Op::Or => 13,
        Op::Imply => 14,
    }
}
