//! Diagnostics (reports) produced by the analysis.

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Kind {
    Warning,
    Error,
}

#[derive(Clone, Debug)]
pub enum Seg {
    Txt(String),
    Hl(String),
}

#[derive(Clone, Debug)]
pub struct Fix {
    /// Byte range in the source to replace (exclusive end).
    pub start: usize,
    pub end: usize,
    pub text: String,
}

#[derive(Clone, Debug)]
pub struct Label {
    pub start: usize,
    pub end: usize,
    pub segs: Vec<Seg>,
    pub fix: Option<Fix>,
}

#[derive(Clone, Debug)]
pub struct Report {
    pub kind: Kind,
    pub code: u32,
    pub title: String,
    pub labels: Vec<Label>,
}

impl Report {
    pub fn warn(code: u32, title: &str, labels: Vec<Label>) -> Report {
        Report { kind: Kind::Warning, code, title: title.to_string(), labels }
    }
    pub fn err(title: &str, labels: Vec<Label>) -> Report {
        Report { kind: Kind::Error, code: 0, title: title.to_string(), labels }
    }
}

/// Render a label's message, optionally quoting highlighted segments.
pub fn render_label(segs: &[Seg], quote: bool) -> String {
    let mut out = String::new();
    for s in segs {
        match s {
            Seg::Txt(t) => out.push_str(t),
            Seg::Hl(t) => {
                if quote {
                    out.push('`');
                    out.push_str(t);
                    out.push('`');
                } else {
                    out.push_str(t);
                }
            }
        }
    }
    out
}
