//! Human readable ("stderr") and machine ("errfmt") diagnostic rendering.

use crate::diag::{Kind, Label, Report, Seg};

pub const ESC_RESET: &str = "\x1b[0m";
pub const C_WARN: &str = "\x1b[33m";
pub const C_ERR: &str = "\x1b[31m";
pub const C_BORDER: &str = "\x1b[38;5;246m";
pub const C_HL: &str = "\x1b[35m";
pub const C_PRIMARY: &str = "\x1b[36m";
pub const C_DIM: &str = "\x1b[38;5;249m";

pub struct Source<'a> {
    pub text: &'a str,
    /// Byte offset of the start of each line.
    pub line_starts: Vec<usize>,
}

impl<'a> Source<'a> {
    pub fn new(text: &'a str) -> Source<'a> {
        let mut line_starts = vec![0usize];
        for (i, b) in text.bytes().enumerate() {
            if b == b'\n' {
                line_starts.push(i + 1);
            }
        }
        Source { text, line_starts }
    }

    pub fn line_of(&self, off: usize) -> usize {
        match self.line_starts.binary_search(&off) {
            Ok(i) => i,
            Err(i) => i - 1,
        }
    }
    pub fn col_of(&self, off: usize) -> usize {
        let l = self.line_of(off);
        off - self.line_starts[l]
    }
    pub fn line_start(&self, line: usize) -> usize {
        self.line_starts[line]
    }
    pub fn line_end(&self, line: usize) -> usize {
        let s = self.line_starts[line];
        let bytes = self.text.as_bytes();
        let mut e = s;
        while e < bytes.len() && bytes[e] != b'\n' {
            e += 1;
        }
        e
    }
    pub fn line_text(&self, line: usize) -> &'a str {
        &self.text[self.line_start(line)..self.line_end(line)]
    }
    pub fn n_lines(&self) -> usize {
        self.line_starts.len()
    }
}

fn is_multiline(src: &Source, l: &Label) -> bool {
    src.line_of(l.start) != src.line_of(l.end)
}

/// Render one report in the "stderr" (ariadne style) format.
pub fn render_report(src: &Source, path: &str, rep: &Report) -> String {
    let mut out = String::new();
    let labels: Vec<&Label> = rep.labels.iter().collect();
    if labels.is_empty() {
        return out;
    }
    let (kind_color, kind_name) = match rep.kind {
        Kind::Warning => (C_WARN, "Warning"),
        Kind::Error => (C_ERR, "Error"),
    };
    out.push_str(&format!(
        "{}[{}{}]{} {}{}\n",
        kind_color,
        code_str(rep),
        kind_name,
        ESC_RESET,
        rep.title,
        ESC_RESET
    ));

    // Determine gutter width from the displayed line numbers.
    let mut max_num = 1usize;
    for l in &labels {
        let a = src.line_of(l.start);
        let b = src.line_of(l.end);
        for n in [a + 1, b + 1] {
            let w = n.to_string().len();
            if w > max_num {
                max_num = w;
            }
        }
    }

    let first = labels[0];
    let (fl, fc) = (src.line_of(first.start) + 1, src.col_of(first.start) + 1);
    let pre = " ".repeat(max_num + 2);
    out.push_str(&format!(
        "{}{}{}{}{}{}:{}:{}{}{}\n",
        pre,
        C_BORDER,
        "\u{256d}",
        ESC_RESET,
        C_BORDER,
        ESC_RESET,
        "",
        "",
        "",
        ""
    ));
    // The header is built explicitly to match the escape sequence order.
    out.pop();
    out.pop();
    out.push_str(&header_line(&pre, path, fl, fc));

    out.push_str(&format!("{}{}\u{2502}{}\n", pre, C_BORDER, ESC_RESET));

    // Split labels into per-line groups (single-line) and multiline labels.
    let multi: Vec<&&Label> = labels.iter().filter(|l| is_multiline(src, l)).collect();
    let single: Vec<&&Label> = labels.iter().filter(|l| !is_multiline(src, l)).collect();

    if multi.is_empty() {
        // group by line
        let mut groups: Vec<(usize, Vec<&&Label>)> = Vec::new();
        for l in single {
            let ln = src.line_of(l.start);
            match groups.last_mut() {
                Some((g, v)) if *g == ln => v.push(l),
                _ => groups.push((ln, vec![l])),
            }
        }
        for (ln, gl) in groups {
            out.push_str(&source_line(src, ln, max_num, &gl, None));
            out.push_str(&underline_line(src, ln, max_num, &gl, None));
            for (i, l) in gl.iter().enumerate() {
                if i > 0 {
                    out.push_str(&connector_line(src, ln, max_num, &gl, i));
                }
                out.push_str(&arrow_line(src, ln, max_num, &gl, i));
            }
        }
    } else {
        // multiline annotations (render in reverse order, innermost first)
        let order: Vec<&&Label> = if single.is_empty() && multi.len() > 1 {
            multi.iter().rev().copied().collect()
        } else {
            multi.clone()
        };
        for l in order {
            let a = src.line_of(l.start);
            let b = src.line_of(l.end);
            let content_width = src.line_text(b).chars().count();
            out.push_str(&mline_first(src, a, max_num));
            out.push_str(&mline_last(src, b, max_num));
            // filler
            let pad = 6 + content_width;
            out.push_str(&format!(
                "{}\u{2502}{}\n",
                dot_gutter(max_num),
                " ".repeat(pad + 1)
            ));
            out.push_str(&format!(
                "{}\u{2570}{} {}\n",
                dot_gutter(max_num),
                "\u{2500}".repeat(pad),
                crate::diag::render_label(&l.segs, false)
            ));
        }
        for l in single {
            let ln = src.line_of(l.start);
            out.push_str(&source_line(src, ln, max_num, &[l], None));
            out.push_str(&underline_line(src, ln, max_num, &[l], None));
            out.push_str(&arrow_line(src, ln, max_num, &[l], 0));
        }
    }

    out.push_str(&format!(
        "{}{}\u{256f}{}\n",
        "\u{2500}".repeat(max_num + 2),
        C_BORDER,
        ESC_RESET
    ));
    out
}

fn header_line(pre: &str, path: &str, line: usize, col: usize) -> String {
    format!(
        "{}{}\u{256d}{}{}\u{2500}{}{}[{}{}:{}:{}]{}]\n",
        pre,
        C_BORDER,
        ESC_RESET,
        C_BORDER,
        ESC_RESET,
        C_BORDER,
        ESC_RESET,
        path,
        line,
        col,
        C_BORDER
    ) + &format!("{}\n", ESC_RESET)
}

fn num_gutter(num: usize, max_num: usize) -> String {
    let s = num.to_string();
    format!(" {}{} \u{2502}{}{}", C_BORDER, " ".repeat(max_num - s.len()) + &s, ESC_RESET, " ")
}

fn dot_gutter(max_num: usize) -> String {
    format!(" {}{} \u{b7}{}", " ".repeat(0), C_BORDER, ESC_RESET)
}

fn dot_gutter_full(max_num: usize) -> String {
    format!(
        " {}{} \u{b7}{}",
        " ",
        C_BORDER,
        ESC_RESET
    )
    .replace(&" ".repeat(0), &" ".repeat(max_num))
}

fn colorize_range(text: &[char], hl: &[bool]) -> String {
    let mut out = String::new();
    for (i, c) in text.iter().enumerate() {
        let esc = if hl[i] { C_HL } else { C_DIM };
        out.push_str(esc);
        out.push(*c);
        out.push_str(ESC_RESET);
    }
    out
}

fn source_line(
    src: &Source,
    line: usize,
    max_num: usize,
    labels: &[&&Label],
    _: Option<()>,
) -> String {
    let text = src.line_text(line);
    let chars: Vec<char> = text.chars().collect();
    // byte -> char index mapping
    let mut map: Vec<usize> = vec![0; text.len() + 1];
    let mut ci = 0;
    for (i, _) in text.bytes().enumerate() {
        while ci < chars.len() {
            let off = src.line_start(line) + text[..].char_indices().nth(ci).map(|(b, _)| b).unwrap_or(0);
            if off > i {
                break;
            }
            map[i] = ci;
            break;
        }
        ci = map[i];
        let _ = ci;
    }
    let mut hl: Vec<bool> = vec![false; chars.len()];
    for l in labels {
        let s = src.col_of(l.start);
        let e = src.col_of(l.end);
        for i in s..e.min(chars.len()) {
            hl[i] = true;
        }
    }
    format!("{}{}\n", num_gutter(line + 1, max_num), colorize_range(&chars, &hl))
}

fn underline_line(
    src: &Source,
    line: usize,
    max_num: usize,
    labels: &[&&Label],
    _: Option<()>,
) -> String {
    let text = src.line_text(line);
    let n = text.chars().count();
    let mut cells: Vec<char> = vec![' '; n];
    for l in labels {
        let s = src.col_of(l.start);
        let e = src.col_of(l.end).min(n);
        let len = e.saturating_sub(s);
        if len == 0 {
            continue;
        }
        let caret = s + len / 2;
        for i in s..e {
            cells[i] = '\u{2500}';
        }
        cells[caret] = '\u{252c}';
    }
    let mut out = String::new();
    for c in cells {
        if c == ' ' {
            out.push(' ');
        } else {
            out.push_str(C_HL);
            out.push(c);
            out.push_str(ESC_RESET);
        }
    }
    out.push_str("  ");
    format!("{}{}\n", dot_gutter2(max_num), out)
}

fn dot_gutter2(max_num: usize) -> String {
    format!(" {}{} \u{b7}{}", " ".repeat(max_num), C_BORDER, ESC_RESET)
}

fn connector_line(
    src: &Source,
    line: usize,
    max_num: usize,
    labels: &[&&Label],
    from: usize,
) -> String {
    let text = src.line_text(line);
    let n = text.chars().count();
    let mut cells: Vec<char> = vec![' '; n];
    for l in labels.iter().skip(from) {
        let s = src.col_of(l.start);
        let e = src.col_of(l.end).min(n);
        let len = e.saturating_sub(s);
        if len == 0 {
            continue;
        }
        cells[s + len / 2] = '\u{2502}';
    }
    let mut out = String::new();
    for c in cells {
        if c == ' ' {
            out.push(' ');
        } else {
            out.push_str(C_HL);
            out.push(c);
            out.push_str(ESC_RESET);
        }
    }
    let _ = line;
    out.push_str("    ");
    format!("{}{}\n", dot_gutter2(max_num), out)
}

fn arrow_line(
    src: &Source,
    line: usize,
    max_num: usize,
    labels: &[&&Label],
    idx: usize,
) -> String {
    let l = labels[idx];
    let text = src.line_text(line);
    let n = text.chars().count();
    let s = src.col_of(l.start);
    let e = src.col_of(l.end).min(n);
    let max_end = labels
        .iter()
        .map(|x| src.col_of(x.end).min(n))
        .max()
        .unwrap_or(0);
    let caret = s + (e.saturating_sub(s)) / 2;
    let dashes = (max_end + 2).saturating_sub(caret + 1);
    format!(
        "{}{}\u{2570}{} {}\n",
        dot_gutter2(max_num),
        " ".repeat(caret + 1),
        "\u{2500}".repeat(dashes),
        crate::diag::render_label(&l.segs, false)
    )
}

fn mline_first(src: &Source, line: usize, max_num: usize) -> String {
    format!(
        "{}{}\u{256d}{}\u{2500}{}\u{25b6}{}{}\n",
        num_gutter(line + 1, max_num),
        C_HL,
        ESC_RESET,
        "",
        ESC_RESET,
        ""
    )
    .replace(&format!("{}{}\n", ESC_RESET, ""), "")
}

fn mline_last(src: &Source, line: usize, max_num: usize) -> String {
    let text = src.line_text(line);
    let chars: Vec<char> = text.chars().collect();
    let hl: Vec<bool> = vec![true; chars.len()];
    let marker = format!("{}\u{251c}{}\u{2500}{}\u{25b6} ", C_HL, C_HL, C_HL);
    format!("{}{}\n", num_gutter(line + 1, max_num), marker)
}

/// Machine readable format: one line per label.
pub fn render_errfmt(src: &Source, path: &str, rep: &Report) -> String {
    let mut out = String::new();
    for l in &rep.labels {
        let line = src.line_of(l.start) + 1;
        let col = src.col_of(l.start) + 1;
        let kind = match rep.kind {
            Kind::Warning => "W",
            Kind::Error => "E",
        };
        out.push_str(&format!(
            "{}>{}:{}:{}:{}:{}\n",
            path,
            line,
            col,
            kind,
            rep.code,
            crate::diag::render_label(&l.segs, true)
        ));
    }
    out
}
