    let mut out = String::new();
    for c in cells {
        if c == ' ' {
            out.push(' ');
        } else {
            out.push_str(C_HL);
            out.push(c);
            out.push_str(ESC_RESET);
        }
    }
    out.push_str("  ");
    format!("{}{}\n", dot_gutter2(max_num), out)
