fn connector_line(
    src: &Source,
    line: usize,
    max_num: usize,
    labels: &[&&Label],
    from: usize,
) -> String {
    let text = src.line_text(line);
    let n = text.chars().count();
    let mut cells: Vec<char> = vec![' '; n];
    for l in labels.iter().skip(from) {
        let s = src.col_of(l.start);
        let e = src.col_of(l.end).min(n);
        let len = e.saturating_sub(s);
        if len == 0 {
