//! Human readable ("stderr") and machine ("errfmt") diagnostic rendering.

use crate::diag::{Kind, Label, Report, Seg};

pub const ESC_RESET: &str = "\x1b[0m";
pub const C_WARN: &str = "\x1b[33m";
pub const C_ERR: &str = "\x1b[31m";
pub const C_BORDER: &str = "\x1b[38;5;246m";
pub const C_HL: &str = "\x1b[35m";
pub const C_PRIMARY: &str = "\x1b[36m";
pub const C_DIM: &str = "\x1b[38;5;249m";

pub struct Source<'a> {
    pub text: &'a str,
    /// Byte offset of the start of each line.
    pub line_starts: Vec<usize>,
}

impl<'a> Source<'a> {
    pub fn new(text: &'a str) -> Source<'a> {
        let mut line_starts = vec![0usize];
        for (i, b) in text.bytes().enumerate() {
            if b == b'\n' {
                line_starts.push(i + 1);
            }
        }
        Source { text, line_starts }
    }

    pub fn line_of(&self, off: usize) -> usize {
        match self.line_starts.binary_search(&off) {
            Ok(i) => i,
            Err(i) => i - 1,
        }
    }
    pub fn col_of(&self, off: usize) -> usize {
        let l = self.line_of(off);
        off - self.line_starts[l]
    }
    pub fn line_start(&self, line: usize) -> usize {
        self.line_starts[line]
    }
    pub fn line_end(&self, line: usize) -> usize {
        let s = self.line_starts[line];
        let bytes = self.text.as_bytes();
        let mut e = s;
        while e < bytes.len() && bytes[e] != b'\n' {
            e += 1;
        }
        e
    }
    pub fn line_text(&self, line: usize) -> &'a str {
        &self.text[self.line_start(line)..self.line_end(line)]
    }
    pub fn n_lines(&self) -> usize {
        self.line_starts.len()
    }
}

fn is_multiline(src: &Source, l: &Label) -> bool {
    src.line_of(l.start) != src.line_of(l.end)
}

/// Render one report in the "stderr" (ariadne style) format.
pub fn render_report(src: &Source, path: &str, rep: &Report) -> String {
    let mut out = String::new();
    let labels: Vec<&Label> = rep.labels.iter().collect();
    if labels.is_empty() {
        return out;
    }
    let (kind_color, kind_name) = match rep.kind {
        Kind::Warning => (C_WARN, "Warning"),
        Kind::Error => (C_ERR, "Error"),
    };
    out.push_str(&format!(
        "{}[{}{}]{} {}{}\n",
        kind_color,
        code_str(rep),
        kind_name,
        ESC_RESET,
        rep.title,
        ESC_RESET
    ));

    // Determine gutter width from the displayed line numbers.
    let mut max_num = 1usize;
    for l in &labels {
        let a = src.line_of(l.start);
        let b = src.line_of(l.end);
        for n in [a + 1, b + 1] {
            let w = n.to_string().len();
            if w > max_num {
                max_num = w;
            }
        }
    }

    let first = labels[0];
    let (fl, fc) = (src.line_of(first.start) + 1, src.col_of(first.start) + 1);
    let pre = " ".repeat(max_num + 2);
    out.push_str(&format!(
        "{}{}{}{}{}{}:{}:{}{}{}\n",
        pre,
        C_BORDER,
        "\u{256d}",
        ESC_RESET,
        C_BORDER,
        ESC_RESET,
        "",
        "",
        "",
        ""
    ));
    // The header is built explicitly to match the escape sequence order.
    out.pop();
    out.pop();
    out.push_str(&header_line(&pre, path, fl, fc));

    out.push_str(&format!("{}{}\u{2502}{}\n", pre, C_BORDER, ESC_RESET));

    // Split labels into per-line groups (single-line) and multiline labels.
    let multi: Vec<&&Label> = labels.iter().filter(|l| is_multiline(src, l)).collect();
    let single: Vec<&&Label> = labels.iter().filter(|l| !is_multiline(src, l)).collect();

    if multi.is_empty() {
        // group by line
        let mut groups: Vec<(usize, Vec<&&Label>)> = Vec::new();
        for l in single {
            let ln = src.line_of(l.start);
            match groups.last_mut() {
                Some((g, v)) if *g == ln => v.push(l),
                _ => groups.push((ln, vec![l])),
            }
        }
        for (ln, gl) in groups {
            out.push_str(&source_line(src, ln, max_num, &gl, None));
            out.push_str(&underline_line(src, ln, max_num, &gl, None));
            for (i, l) in gl.iter().enumerate() {
