                }
                out.push_str(&arrow_line(src, ln, max_num, &gl, i));
            }
        }
    } else {
        // multiline annotations (render in reverse order, innermost first)
        let order: Vec<&&Label> = if single.is_empty() && multi.len() > 1 {
            multi.iter().rev().copied().collect()
        } else {
            multi.clone()
        };
        for l in order {
            let a = src.line_of(l.start);
            let b = src.line_of(l.end);
            let content_width = src.line_text(b).chars().count();
            out.push_str(&mline_first(src, a, max_num));
            out.push_str(&mline_last(src, b, max_num));
            // filler
            let pad = 6 + content_width;
            out.push_str(&format!(
                "{}\u{2502}{}\n",
                dot_gutter(max_num),
                " ".repeat(pad + 1)
            ));
            out.push_str(&format!(
                "{}\u{2570}{} {}\n",
                dot_gutter(max_num),
                "\u{2500}".repeat(pad),
                crate::diag::render_label(&l.segs, false)
            ));
        }
        for l in single {
            let ln = src.line_of(l.start);
            out.push_str(&source_line(src, ln, max_num, &[l], None));
            out.push_str(&underline_line(src, ln, max_num, &[l], None));
            out.push_str(&arrow_line(src, ln, max_num, &[l], 0));
        }
    }

    out.push_str(&format!(
        "{}{}\u{256f}{}\n",
        "\u{2500}".repeat(max_num + 2),
        C_BORDER,
        ESC_RESET
    ));
    out
