//! Human readable ("stderr") and machine ("errfmt") diagnostic rendering.

use crate::diag::{render_label, Kind, Label, Report};

pub const R: &str = "\x1b[0m";
pub const C_WARN: &str = "\x1b[33m";
pub const C_ERR: &str = "\x1b[31m";
pub const C_B: &str = "\x1b[38;5;246m";
pub const C_HL: &str = "\x1b[35m";
pub const C_P: &str = "\x1b[36m";
pub const C_D: &str = "\x1b[38;5;249m";

pub struct Source<'a> {
    pub text: &'a str,
    pub line_starts: Vec<usize>,
}

impl<'a> Source<'a> {
    pub fn new(text: &'a str) -> Source<'a> {
        let mut line_starts = vec![0usize];
        for (i, b) in text.bytes().enumerate() {
            if b == b'\n' {
                line_starts.push(i + 1);
            }
        }
        Source { text, line_starts }
    }

    pub fn line_of(&self, off: usize) -> usize {
        match self.line_starts.binary_search(&off) {
            Ok(i) => i,
            Err(i) => i - 1,
        }
    }
    pub fn col_of(&self, off: usize) -> usize {
        let l = self.line_of(off);
        off - self.line_starts[l]
    }
    pub fn line_start(&self, line: usize) -> usize {
        self.line_starts[line]
    }
    pub fn line_end(&self, line: usize) -> usize {
        let s = self.line_starts[line];
        let bytes = self.text.as_bytes();
        let mut e = s;
        while e < bytes.len() && bytes[e] != b'\n' {
            e += 1;
        }
        e
    }
    pub fn line_text(&self, line: usize) -> &'a str {
        &self.text[self.line_start(line)..self.line_end(line)]
    }
}

fn code_str(rep: &Report) -> String {
    match rep.kind {
        Kind::Warning => format!("[W{:02}] ", rep.code),
        Kind::Error => "[E00] ".to_string(),
    }
}

struct Ctx {
    max_num: usize,
}

impl Ctx {
    fn num_gutter(&self, num: usize) -> String {
        let s = num.to_string();
        let pad = " ".repeat(self.max_num - s.len());
        format!(" {}{}{} \u{2502}{} ", C_B, pad, s, R)
    }
    fn dot_gutter(&self) -> String {
        format!(" {}{} \u{b7}{}", C_B, " ".repeat(self.max_num), R)
    }
    fn bar_gutter(&self) -> String {
        format!(" {}{} \u{b7}{} ", C_B, " ".repeat(self.max_num), R)
    }
    fn pre(&self) -> String {
        " ".repeat(self.max_num + 2)
    }
}

/// Column index (within the line, 0-based) of a byte offset.
fn col(src: &Source, off: usize) -> usize {
    src.col_of(off)
}

fn highlighted_line(text: &str, hl_from: usize, hl_to: usize) -> String {
    let chars: Vec<char> = text.chars().collect();
    let mut out = String::new();
    for (i, c) in chars.iter().enumerate() {
        let esc = if i >= hl_from && i < hl_to { C_HL } else { C_D };
        out.push_str(esc);
        out.push(*c);
        out.push_str(R);
    }
    out
}

fn underline_cells(n: usize, labels: &[&Label], src: &Source) -> Vec<char> {
    let mut cells = vec![' '; n];
    for l in labels {
        let s = col(src, l.start);
        let e = col(src, l.end).min(n);
        if e <= s {
            if s < n {
                cells[s] = '\u{2502}';
            }
            continue;
        }
        for i in s..e {
            cells[i] = '\u{2500}';
        }
        cells[s + (e - s) / 2] = '\u{252c}';
    }
    cells
}

fn cells_to_str(cells: &[char]) -> String {
    let mut out = String::new();
    for c in cells {
        if *c == ' ' {
            out.push(' ');
        } else {
            out.push_str(C_HL);
            out.push(*c);
            out.push_str(R);
        }
    }
    out
}

/// Render a single report in the ariadne-like format.
pub fn render_report(src: &Source, path: &str, rep: &Report) -> String {
    let labels: Vec<&Label> = rep.labels.iter().collect();
    if labels.is_empty() {
        return String::new();
    }
    let mut out = String::new();
    let (kc, kn) = match rep.kind {
        Kind::Warning => (C_WARN, "Warning"),
        Kind::Error => (C_ERR, "Error"),
    };
    out.push_str(&format!(
        "{}{}{}{} {}{}\n",
        kc,
        code_str(rep),
        kn,
        R,
        rep.title,
        R
    ));

    let mut max_num = 1usize;
    for l in &labels {
        for off in [l.start, l.end] {
            let w = (src.line_of(off) + 1).to_string().len();
            if w > max_num {
                max_num = w;
            }
        }
    }
    let ctx = Ctx { max_num };

    let first = labels[0];
    out.push_str(&header(&ctx, path, src.line_of(first.start) + 1, col(src, first.start) + 1));
    out.push_str(&format!("{}{}\u{2502}{}\n", ctx.pre(), C_B, R));

    let multi: Vec<&Label> = labels
        .iter()
        .filter(|l| src.line_of(l.start) != src.line_of(l.end))
        .copied()
        .collect();
    let single: Vec<&Label> = labels
        .iter()
        .filter(|l| src.line_of(l.start) == src.line_of(l.end))
        .copied()
        .collect();

    if !multi.is_empty() {
        let order: Vec<&Label> = if single.is_empty() && multi.len() > 1 {
            multi.iter().rev().copied().collect()
        } else {
            multi.clone()
        };
        for l in order {
            let a = src.line_of(l.start);
            let b = src.line_of(l.end);
            let last_len = src.line_text(b).chars().count();
            out.push_str(&format!(
                "{}{}\u{256d}{}\u{2500}{}\u{25b6}{} {}\n",
                ctx.num_gutter(a + 1),
                C_HL,
                R,
                C_HL,
                R,
                highlighted_line(src.line_text(a), 0, src.line_text(a).chars().count())
            ));
            out.push_str(&format!(
                "{}{}\u{251c}{}\u{2500}{}\u{25b6}{} {}\n",
                ctx.num_gutter(b + 1),
                C_HL,
                R,
                C_HL,
                R,
                highlighted_line(src.line_text(b), 0, src.line_text(b).chars().count())
            ));
            out.push_str(&format!(
                "{}{}{}\u{2502}{}{}{}\n",
                ctx.bar_gutter(),
                C_HL,
                R,
                R,
                " ".repeat(6 + last_len),
                R
            ));
            out.push_str(&format!(
                "{}{}\u{2570}{}{}{}\u{2500}{}{} {}\n",
                ctx.bar_gutter(),
                C_HL,
                R,
                R,
                C_HL,
                R,
                " ".repeat(0),
                ""
            ));
            // rebuild the arrow line properly
            out.pop();
            out.push_str(&format!(
                "{}{}\u{2570}{}{}{}{}{}\n",
                ctx.bar_gutter(),
                C_HL,
                R,
                R,
                dashes_hl(6 + last_len),
                " ".repeat(0),
                ""
            ));
            let _ = &out;
            out.push_str(&format!(
                " {}\n",
                render_label(&l.segs, false)
            ));
        }
        for l in &single {
            let ln = src.line_of(l.start);
            let gl = vec![*l];
            out.push_str(&single_source(src, ln, &ctx, &gl));
            out.push_str(&single_underline(src, ln, &ctx, &gl));
            out.push_str(&single_arrow(src, ln, &ctx, &gl, 0));
        }
    } else {
        let mut groups: Vec<(usize, Vec<&Label>)> = Vec::new();
        for l in single {
            let ln = src.line_of(l.start);
            match groups.last_mut() {
                Some((g, v)) if *g == ln => v.push(l),
                _ => groups.push((ln, vec![l])),
            }
        }
        for (ln, gl) in groups {
            out.push_str(&single_source(src, ln, &ctx, &gl));
            out.push_str(&single_underline(src, ln, &ctx, &gl));
            for i in 0..gl.len() {
                if i > 0 {
                    out.push_str(&single_connector(src, ln, &ctx, &gl, i));
                }
                out.push_str(&single_arrow(src, ln, &ctx, &gl, i));
            }
        }
    }

    out.push_str(&format!(
        "{}{}{}\u{256f}{}\n",
        "\u{2500}".repeat(max_num + 2),
        C_B,
        R,
        R
    ));
    out
}

fn dashes_hl(n: usize) -> String {
    let mut s = String::new();
    for _ in 0..n {
        s.push_str(C_HL);
        s.push('\u{2500}');
        s.push_str(R);
    }
    s
}

fn header(ctx: &Ctx, path: &str, line: usize, c: usize) -> String {
    format!(
        "{}{}\u{256d}{}{}{}\u{2500}{}{}{}[{}{}:{}:{}]{}]\n",
        ctx.pre(),
        C_B,
        R,
        C_B,
        R,
        C_B,
        R,
        C_B,
        R,
        path,
        line,
        c,
        C_B
    ) + &format!("{}\n", R)
}

fn single_source(src: &Source, ln: usize, ctx: &Ctx, gl: &[&Label]) -> String {
    let text = src.line_text(ln);
    let chars: Vec<char> = text.chars().collect();
    let mut hl: Vec<bool> = vec![false; chars.len()];
    for l in gl {
        let s = col(src, l.start);
        let e = col(src, l.end).min(chars.len());
        for i in s..e {
            hl[i] = true;
        }
    }
    let mut out = String::new();
    for (i, c) in chars.iter().enumerate() {
        out.push_str(if hl[i] { C_HL } else { C_D });
        out.push(*c);
        out.push_str(R);
    }
    format!("{}{}\n", ctx.num_gutter(ln + 1), out)
}

fn single_underline(src: &Source, ln: usize, ctx: &Ctx, gl: &[&Label]) -> String {
    let n = src.line_text(ln).chars().count();
    let cells = underline_cells(n, gl, src);
    let mut body = cells_to_str(&cells);
    let zero = gl.iter().any(|l| col(src, l.start) == col(src, l.end));
    body.push_str(if zero { " " } else { "  " });
    format!("{}{}\n", ctx.dot_gutter(), body)
}

fn single_connector(src: &Source, ln: usize, ctx: &Ctx, gl: &[&Label], from: usize) -> String {
    let n = src.line_text(ln).chars().count();
    let mut cells = vec![' '; n];
    for l in gl.iter().skip(from) {
        let s = col(src, l.start);
        let e = col(src, l.end).min(n);
        if e <= s {
            continue;
        }
        cells[s + (e - s) / 2] = '\u{2502}';
    }
    let mut body = cells_to_str(&cells);
    let width = n + 2;
    while body.chars().count() < width {
        body.push(' ');
    }
    format!("{}{}\n", ctx.dot_gutter(), body)
}

fn single_arrow(src: &Source, ln: usize, ctx: &Ctx, gl: &[&Label], idx: usize) -> String {
    let l = gl[idx];
    let n = src.line_text(ln).chars().count();
    let s = col(src, l.start);
    let e = col(src, l.end).min(n);
    let max_end = gl.iter().map(|x| col(src, x.end).min(n)).max().unwrap_or(0);
    let caret = s + (e.saturating_sub(s)) / 2;
    let dashes = (max_end + 1).saturating_sub(caret + 1);
    let mut body = " ".repeat(caret + 1);
    body.push_str(C_HL);
    body.push('\u{2570}');
    body.push_str(R);
    body.push_str(&dashes_hl(dashes));
    body.push(' ');
    body.push_str(&render_label(&l.segs, false));
    format!("{}{}\n", ctx.dot_gutter(), body)
}

/// Machine readable format: one line per label.
pub fn render_errfmt(src: &Source, path: &str, rep: &Report) -> String {
    let mut out = String::new();
    for l in &rep.labels {
        let line = src.line_of(l.start) + 1;
        let c = src.col_of(l.start) + 1;
        let kind = match rep.kind {
            Kind::Warning => "W",
            Kind::Error => "E",
        };
        out.push_str(&format!(
            "{}>{}:{}:{}:{}:{}\n",
            path,
            line,
            c,
            kind,
            rep.code,
            render_label(&l.segs, true)
        ));
    }
    out
}
