            }
        }
        for (ln, gl) in groups {
            out.push_str(&single_source(src, ln, &ctx, &gl));
            out.push_str(&single_underline(src, ln, &ctx, &gl));
            for i in 0..gl.len() {
                if i > 0 {
                    out.push_str(&single_connector(src, ln, &ctx, &gl, i));
                }
                out.push_str(&single_arrow(src, ln, &ctx, &gl, i));
            }
        }
    }

    out.push_str(&format!(
        "{}{}{}\u{256f}{}\n",
        "\u{2500}".repeat(max_num + 2),
        C_B,
        R,
        R
    ));
    out
}

fn dashes_hl(n: usize) -> String {
