        let mut e = s;
        while e < bytes.len() && bytes[e] != b'\n' {
            e += 1;
        }
        e
    }
    pub fn line_text(&self, line: usize) -> &'a str {
        &self.text[self.line_start(line)..self.line_end(line)]
    }
}

fn code_str(rep: &Report) -> String {
    match rep.kind {
        Kind::Warning => format!("[W{:02}] ", rep.code),
        Kind::Error => "[E00] ".to_string(),
    }
}

struct Ctx {
    max_num: usize,
}

impl Ctx {
    fn num_gutter(&self, num: usize) -> String {
        let s = num.to_string();
        let pad = " ".repeat(self.max_num - s.len());
        format!(" {}{}{} \u{2502}{} ", C_B, pad, s, R)
    }
    fn dot_gutter(&self) -> String {
        format!(" {}{} \u{b7}{} ", C_B, " ".repeat(self.max_num + 1), R)
    }
    fn pre(&self) -> String {
        " ".repeat(self.max_num + 2)
    }
}

fn col(src: &Source, off: usize) -> usize {
    src.col_of(off)
}

fn hl_chars(text: &str) -> String {
    let mut out = String::new();
    for c in text.chars() {
