    if labels.is_empty() {
        return String::new();
    }
    let mut out = String::new();
    let (kc, kn) = match rep.kind {
        Kind::Warning => (C_WARN, "Warning"),
        Kind::Error => (C_ERR, "Error"),
    };
    out.push_str(&format!(
        "{}{}{}{} {}{}\n",
        kc, code_str(rep), kn, R, rep.title, R
    ));

    let mut max_num = 1usize;
    for l in &labels {
        for off in [l.start, l.end] {
            let w = (src.line_of(off) + 1).to_string().len();
            if w > max_num {
                max_num = w;
            }
        }
    }
    let ctx = Ctx { max_num };

    let first = labels[0];
    out.push_str(&header(&ctx, path, src.line_of(first.start) + 1, col(src, first.start) + 1));
    out.push_str(&format!("{}{}\u{2502}{}\n", ctx.pre(), C_B, R));

    let multi: Vec<&Label> = labels
        .iter()
        .filter(|l| src.line_of(l.start) != src.line_of(l.end))
        .copied()
        .collect();
    let single: Vec<&Label> = labels
        .iter()
        .filter(|l| src.line_of(l.start) == src.line_of(l.end))
        .copied()
        .collect();

    if !multi.is_empty() {
        let order: Vec<&Label> = if single.is_empty() && multi.len() > 1 {
            multi.iter().rev().copied().collect()
        } else {
            multi.clone()
        };
        for l in order {
            let a = src.line_of(l.start);
            let b = src.line_of(l.end);
            let last_len = src.line_text(b).chars().count();
            out.push_str(&format!(
                "{}{}\u{256d}{}\u{2500}{}\u{25b6}{} {}\n",
                ctx.num_gutter(a + 1),
                C_HL,
                R,
                C_HL,
                R,
                hl_chars(src.line_text(a))
            ));
            out.push_str(&format!(
                "{}{}\u{251c}{}\u{2500}{}\u{25b6}{} {}\n",
                ctx.num_gutter(b + 1),
                C_HL,
                R,
                C_HL,
                R,
                hl_chars(src.line_text(b))
            ));
            out.push_str(&format!(
                "{}{}\u{2502}{}{}{}\n",
                ctx.dot_gutter(),
                C_HL,
                R,
                " ".repeat(6 + last_len),
                R
            ));
            out.push_str(&format!(
                "{}{}\u{2570}{}{}{} {}\n",
                ctx.dot_gutter(),
                C_HL,
                R,
                dashes_hl(6 + last_len),
                R,
                render_label(&l.segs, false)
            ));
        }
        for l in &single {
            let ln = src.line_of(l.start);
            let gl = vec![*l];
            out.push_str(&single_source(src, ln, &ctx, &gl));
            out.push_str(&single_underline(src, ln, &ctx, &gl));
            out.push_str(&single_arrow(src, ln, &ctx, &gl, 0));
        }
    } else {
        let mut groups: Vec<(usize, Vec<&Label>)> = Vec::new();
        for l in single {
            let ln = src.line_of(l.start);
            match groups.last_mut() {
                Some((g, v)) if *g == ln => v.push(l),
                _ => groups.push((ln, vec![l])),
            }
        }
        for (ln, gl) in groups {
            out.push_str(&single_source(src, ln, &ctx, &gl));
            out.push_str(&single_underline(src, ln, &ctx, &gl));
            for i in 0..gl.len() {
                if i > 0 {
                    out.push_str(&single_connector(src, ln, &ctx, &gl, i));
                }
                out.push_str(&single_arrow(src, ln, &ctx, &gl, i));
            }
        }
    }

    out.push_str(&format!(
        "{}{}\u{256f}{}\n",
        "\u{2500}".repeat(max_num + 2),
        C_B,
        R
    ));
