{"command": "cat > src/diff.rs <<'RSEOF'
//! Unified diff rendering, compatible with the reference implementation.

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Op {
    Equal,
    Delete,
    Insert,
}

fn split_lines(s: &str) -> Vec<&str> {
    let mut out = Vec::new();
    let bytes = s.as_bytes();
    let mut start = 0;
    for i in 0..bytes.len() {
        if bytes[i] == b'\n' {
            out.push(&s[start..i + 1]);
            start = i + 1;
        }
    }
    if start < s.len() {
        out.push(&s[start..]);
    }
    out
}

/// Longest common subsequence over the line lists, returning a list of ops
/// with (old_index, new_index).
fn diff_ops(old: &[&str], new: &[&str]) -> Vec<(Op, Option<usize>, Option<usize>)> {
    let n = old.len();
    let m = new.len();
    // LCS table
    let mut dp: Vec<Vec<u32>> = vec![vec![0u32; m + 1]; n + 1];
    for i in (0..n).rev() {
        for j in (0..m).rev() {
            dp[i][j] = if old[i] == new[j] {
                dp[i + 1][j + 1] + 1
            } else {
                dp[i + 1][j].max(dp[i][j + 1])
            };
        }
    }
    let mut ops = Vec::new();
    let (mut i, mut j) = (0usize, 0usize);
    while i < n && j < m {
        if old[i] == new[j] {
            ops.push((Op::Equal, Some(i), Some(j)));
            i += 1;
            j += 1;
        } else if dp[i + 1][j] >= dp[i][j + 1] {
            ops.push((Op::Delete, Some(i), None));
            i += 1;
        } else {
            ops.push((Op::Insert, None, Some(j)));
            j += 1;
        }
    }
    while i < n {
        ops.push((Op::Delete, Some(i), None));
        i += 1;
    }
    while j < m {
        ops.push((Op::Insert, None, Some(j)));
        j += 1;
    }
    ops
}

const CTX: usize = 4;

/// Produce the unified diff, or `None` when there is no difference.
pub fn unified_diff(old: &str, new: &str, old_label: &str, new_label: &str) -> Option<String> {
    if old == new {
        return None;
    }
    let o: Vec<&str> = split_lines(old);
    let n: Vec<&str> = split_lines(new);
    let ops = diff_ops(&o, &n);
    if ops.iter().all(|(op, _, _)| *op == Op::Equal) {
        return None;
    }

    // Determine which op indices carry a change.
    let changed: Vec<usize> = ops
        .iter()
        .enumerate()
        .filter(|(_, (op, _, _))| *op != Op::Equal)
        .map(|(i, _)| i)
        .collect();
    if changed.is_empty() {
        return None;
    }

    // Group changed op indices into hunks: consecutive changes separated by
    // more than 2*CTX equal lines start a new hunk.
    let mut hunks: Vec<Vec<usize>> = Vec::new();
    let mut cur: Vec<usize> = vec![changed[0]];
    for &c in &changed[1..] {
        // count equal ops between cur.last() and c
        let equal_count = (cur.last().unwrap() + 1..c)
            .filter(|i| ops[*i].0 == Op::Equal)
            .count();
        if equal_count <= 2 * CTX + 1 {
            cur.push(c);
        } else {
            hunks.push(std::mem::replace(&mut cur, vec![c]));
        }
    }
    hunks.push(cur);

    let mut out = String::new();
    out.push_str(&format!("--- {}\n", old_label));
    out.push_str(&format!("+++ {} [fixed]\n", new_label));
    let old_missing_nl = !old.is_empty() && !old.ends_with('\n');
    let new_missing_nl = !new.is_empty() && !new.ends_with('\n');

    for hunk in &hunks {
        let lo = hunk[0].saturating_sub(CTX);
        let hi = (hunk.last().unwrap() + CTX + 1).min(ops.len());
        // expand context while the neighbouring ops are equal
        let mut lo = lo;
        while lo > 0 && ops[lo - 1].0 == Op::Equal {
            lo -= 1;
        }
        let mut hi = hi;
        while hi < ops.len() && ops[hi].0 == Op::Equal {
            hi += 1;
        }
        let mut old_start = None;
        let mut new_start = None;
        let mut old_count = 0usize;
        let mut new_count = 0usize;
        for i in lo..hi {
            match ops[i] {
                (Op::Equal, oi, ni) => {
                    if oi.is_some() {
                        if old_start.is_none() {
                            old_start = oi;
                        }
                        old_count += 1;
                    }
                    if ni.is_some() {
                        if new_start.is_none() {
                            new_start = ni;
                        }
                        new_count += 1;
                    }
                }
                (Op::Delete, oi, _) => {
                    if oi.is_some() {
                        if old_start.is_none() {
                            old_start = oi;
                        }
                        old_count += 1;
                    }
                }
                (Op::Insert, _, ni) => {
                    if ni.is_some() {
                        if new_start.is_none() {
                            new_start = ni;
                        }
                        new_count += 1;
                    }
                }
            }
        }
        let old_start = old_start.unwrap_or(0);
        let new_start = new_start.unwrap_or(0);
        let fmt = |s: usize, c: usize| {
            if c == 1 {
                format!("{}", s + 1)
            } else {
                format!("{},{}", s + 1, c)
            }
        };
        out.push_str(&format!(
            "@@ -{} +{} @@\n",
            fmt(old_start, old_count),
            fmt(new_start, new_count)
        ));
        for i in lo..hi {
            match ops[i] {
                (Op::Equal, oi, ni) => {
                    let line = if oi.is_some() { o[oi.unwrap()] } else { n[ni.unwrap()] };
                    out.push(' ');
                    out.push_str(line.trim_end_matches('\n'));
                    out.push('\n');
                    let last_old = oi.map(|x| x + 1 == o.len()).unwrap_or(false);
                    let last_new = ni.map(|x| x + 1 == n.len()).unwrap_or(false);
                    if (last_old && old_missing_nl) || (last_new && new_missing_nl) {
                        out.push_str("\\ No newline at end of file\n");
                    }
                }
                (Op::Delete, oi, _) => {
                    let line = o[oi.unwrap()];
                    out.push('-');
                    out.push_str(line.trim_end_matches('\n'));
                    out.push('\n');
                    if oi.unwrap() + 1 == o.len() && old_missing_nl {
                        out.push_str("\\ No newline at end of file\n");
                    }
                }
                (Op::Insert, _, ni) => {
                    let line = n[ni.unwrap()];
                    out.push('+');
                    out.push_str(line.trim_end_matches('\n'));
                    out.push('\n');
                    if ni.unwrap() + 1 == n.len() && new_missing_nl {
                        out.push_str("\\ No newline at end of file\n");
                    }
                }
            }
        }
    }
    out.push('\n');
    Some(out)
}
RSEOF
echo ok"}

