//! Fix engine: applies the fixes attached to labels, repeatedly.

use crate::diag::Report;
use crate::lint::{Config, Linter};
use crate::parse::Parser;
use crate::render::Source;

fn analyze(src: &str, cfg: &Config) -> Vec<Report> {
    let r = Parser::parse(src);
    let mut l = Linter::new(src, &r.root, cfg);
    l.run();
    l.reports
}

/// Adjust the "empty inherit" fix range to swallow the preceding trivia.
fn widen_empty_inherit(src: &str, start: usize, end: usize) -> (usize, usize) {
    let bytes = src.as_bytes();
    let mut i = start;
    while i > 0 && (bytes[i - 1].is_ascii_whitespace()) {
        i -= 1;
    }
    // i is now the byte just after the previous significant token
    (i, end)
}

fn collect(src: &str, cfg: &Config) -> Vec<(usize, usize, String)> {
    let reports = analyze(src, cfg);
    let mut fixes: Vec<(usize, usize, String)> = Vec::new();
    for r in &reports {
        for l in &r.labels {
            if let Some(f) = &l.fix {
                let (s, e) = if r.code == 14 {
                    widen_empty_inherit(src, f.start, f.end)
                } else {
                    (f.start, f.end)
                };
                fixes.push((s, e, f.text.clone()));
            }
        }
    }
    fixes.sort_by_key(|(s, e, _)| (*s, std::cmp::Reverse(*e)));
    fixes
}

/// Apply fixes repeatedly until a fixed point (or the pass limit).
pub fn fix_all(src: &str, cfg: &Config) -> String {
    let mut cur = src.to_string();
    for _ in 0..64 {
        let fixes = collect(&cur, cfg);
        if fixes.is_empty() {
            break;
        }
        let next = apply(&cur, &fixes);
        if next == cur {
            break;
        }
        cur = next;
    }
    cur
}

fn apply(src: &str, fixes: &[(usize, usize, String)]) -> String {
    let mut out = String::new();
    let mut last = 0usize;
    for (s, e, t) in fixes {
        if *s < last {
            continue;
        }
        if *s > src.len() || *e > src.len() {
            continue;
        }
        out.push_str(&src[last..*s]);
        out.push_str(t);
        last = *e;
    }
    out.push_str(&src[last..]);
    out
}

/// Apply exactly one fix, the first whose label contains the position.
pub fn fix_single(src: &str, cfg: &Config, line: usize, col: usize) -> Option<String> {
    let srcbox = Source::new(src);
    if line == 0 || line > srcbox.line_starts.len() {
        return None;
    }
    let ls = srcbox.line_starts[line - 1];
    let le = srcbox.line_end(line - 1);
    if col > le - ls {
        return None;
    }
    let pos = ls + col;
    let reports = analyze(src, cfg);
    for r in &reports {
        for l in &r.labels {
            if l.start <= pos && pos + 1 < l.end {
                if let Some(f) = &l.fix {
                    let (s, e) = if r.code == 14 {
                        widen_empty_inherit(src, f.start, f.end)
                    } else {
                        (f.start, f.end)
                    };
                    let fixes = vec![(s, e, f.text.clone())];
                    return Some(apply(src, &fixes));
                }
            }
        }
    }
    None
}

pub fn has_fix_at(src: &str, cfg: &Config, line: usize, col: usize) -> bool {
    let srcbox = Source::new(src);
    if line == 0 || line > srcbox.line_starts.len() {
        return false;
    }
    let ls = srcbox.line_starts[line - 1];
    let le = srcbox.line_end(line - 1);
    if col > le - ls {
        return false;
    }
    let pos = ls + col;
    let reports = analyze(src, cfg);
    reports
        .iter()
        .any(|r| r.labels.iter().any(|l| l.start <= pos && pos + 1 < l.end && l.fix.is_some()))
}
