/// Minimal TOML subset parser good enough for statix.toml files.
fn strip_comment(line: &str) -> &str {
    let bytes = line.as_bytes();
    let mut in_str = false;
    let mut quote = b'"';
    for (i, &c) in bytes.iter().enumerate() {
        match c {
            b'"' | b'\'' => {
                if in_str && c == quote {
                    in_str = false;
                } else if !in_str {
                    in_str = true;
                    quote = c;
                }
            }
            b'#' if !in_str => return &line[..i],
            _ => {}
        }
    }
    line
}

fn parse_array(line: &str, key: &str, lineno: usize) -> Result<Vec<String>, VErr> {
    let s = line.trim();
    if !s.starts_with('[') {
        return Err(VErr::Parse(format!(
            "invalid type: {}, expected a sequence for key `{}` at line {} column 1",
            "string", key, lineno
        )));
    }
    if !s.ends_with(']') {
        return Err(VErr::Parse(format!(
            "unexpected eof encountered at line {} column {}",
            lineno + 1,
            1
        )));
    }
    let inner = &s[1..s.len() - 1];
    let mut out = Vec::new();
    let mut rest = inner.trim();
    while !rest.is_empty() {
        let (val, tail) = if let Some(stripped) = rest.strip_prefix('\'') {
            let end = match stripped.find('\'') {
                Some(e) => e,
                None => {
                    return Err(VErr::Parse(format!(
                        "unterminated string at line {} column {}",
                        lineno,
                        1
                    )))
                }
            };
            (&stripped[..end], &stripped[end + 1..])
        } else if let Some(stripped) = rest.strip_prefix('"') {
            let end = match stripped.find('"') {
                Some(e) => e,
                None => {
                    return Err(VErr::Parse(format!(
                        "unterminated string at line {} column {}",
                        lineno,
                        1
                    )))
                }
            };
            (&stripped[..end], &stripped[end + 1..])
        } else {
            // non-string value
            let end = rest.find(',').unwrap_or(rest.len());
            let tok = rest[..end].trim().to_string();
            let kind = if tok.parse::<i64>().is_ok() {
                format!("integer `{}`", tok)
            } else if tok.parse::<f64>().is_ok() {
                format!("floating-point `{}`", tok)
            } else if tok == "true" || tok == "false" {
                format!("boolean `{}`", tok)
            } else {
                format!("string \"{}\"", tok)
            };
            let col = line.find(&tok).map(|i| i + 1).unwrap_or(1);
            return Err(VErr::Parse(format!(
                "invalid type: {}, expected a string for key `{}` at line {} column {}",
                kind,
                key,
                lineno,
                col
            )));
        };
        out.push(val.to_string());
        rest = tail.trim_start();
        if let Some(r) = rest.strip_prefix(',') {
            rest = r.trim_start();
        }
    }
    Ok(out)
}

pub fn load_config(p: &Path) -> Result<Config, VErr> {
    let text = match fs::read_to_string(p) {
        Ok(t) => t,
        Err(e) => return Err(VErr::Io(e.to_string())),
    };
    let mut cfg = Config::default();
    for (i, raw) in text.lines().enumerate() {
        let line = strip_comment(raw);
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let (key, rest) = match line.split_once('=') {
            Some((k, r)) => (k.trim(), r),
            None => {
                let tok = line.split_whitespace().next().unwrap_or("");
                let col = line.find(tok).map(|x| x + 1).unwrap_or(1);
                let what = if tok.starts_with('{') { "left brace" } else { "table key" };
                return Err(VErr::Parse(format!(
                    "expected a table key, found a {} at line {} column {}",
                    what,
                    i + 1,
                    col
                )));
            }
        };
        match key {
            "disabled" => cfg.disabled = parse_array(rest, "disabled", i + 1)?,
            "ignore" => cfg.ignore = parse_array(rest, "ignore", i + 1)?,
            _ => {}
        }
    }
    Ok(cfg)
}

// ------------------------------------------------------------------ walking

/// Does the glob pattern match the path? `*` matches any run of characters
/// (including `/`), `?` is literal, `[...]` is a character class.
pub fn glob_match(pat: &str, s: &str) -> bool {
    let p: Vec<char> = pat.chars().collect();
    let t: Vec<char> = s.chars().collect();
    m(&p, &t)
}

fn m(p: &[char], t: &[char]) -> bool {
    if p.is_empty() {
        return t.is_empty();
    }
    match p[0] {
        '*' => {
            for i in 0..=t.len() {
                if m(&p[1..], &t[i..]) {
                    return true;
                }
            }
            false
        }
        '[' => {
            if t.is_empty() {
                return false;
            }
            let mut i = 1;
            let mut neg = false;
            if i < p.len() && (p[i] == '!' || p[i] == '^') {
                neg = true;
                i += 1;
            }
            let mut matched = false;
            let mut first = true;
            while i < p.len() && (p[i] != ']' || first) {
                first = false;
                if i + 2 < p.len() && p[i + 1] == '-' && p[i + 2] != ']' {
                    if t[0] >= p[i] && t[0] <= p[i + 2] {
                        matched = true;
                    }
                    i += 3;
                } else {
                    if t[0] == p[i] {
                        matched = true;
                    }
                    i += 1;
            }
            }
            if i >= p.len() {
                return false;
            }
            if matched == neg {
                return false;
            }
            m(&p[i + 1..], &t[1..])
        }
        c => {
            if t.is_empty() || t[0] != c {
                return false;
            }
            m(&p[1..], &t[1..])
        }
    }
}

fn norm(p: &str) -> &str {
    p.trim_end_matches('/')
}

fn ignored(pats: &[String], rel: &str, joined: &str) -> bool {
    pats.iter().any(|p| {
        let p = norm(p);
        glob_match(p, rel) || glob_match(p, joined)
    })
}

/// Collect the `.nix` files under `target`.
pub fn collect(target: &Path, cfg: &Config, unrestricted: bool) -> Result<Vec<PathBuf>, VErr> {
    let meta = match fs::metadata(target) {
        Ok(m) => m,
        Err(_) => return Err(VErr::NotFound(target.display().to_string())),
    };
    let mut pats: Vec<String> = cfg.ignore.clone();
    if meta.is_dir() {
        let gi = target.join(".gitignore");
        if !unrestricted {
            if let Ok(text) = fs::read_to_string(&gi) {
                for line in text.lines() {
                    let line = line.trim();
                    if line.is_empty() || line.starts_with('!') || line.starts_with('#') {
                        continue;
                    }
                    pats.push(line.to_string());
                }
            }
        }
    }
    let mut out = Vec::new();
    if meta.is_file() {
        out.push(target.to_path_buf());
        return Ok(out);
    }
    let rel_root = PathBuf::new();
    walk_dir(target, &rel_root, &pats, &mut out);
    out.sort();
    Ok(out)
}

fn walk_dir(dir: &Path, rel: &Path, pats: &[String], out: &mut Vec<PathBuf>) {
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return,
    };
    let mut ents: Vec<PathBuf> = entries.filter_map(|e| e.ok()).map(|e| e.path()).collect();
    ents.sort();
    for p in ents {
        let name = match p.file_name().and_then(|s| s.to_str()) {
            Some(n) => n.to_string(),
            None => continue,
        };
        let child_rel = rel.join(&name);
        let rels = child_rel.to_string_lossy().to_string();
        if name == ".git" {
            continue;
        }
        if ignored(pats, &rels, &rels) {
            continue;
        }
        let meta = match fs::metadata(&p) {
            Ok(m) => m,
            Err(_) => continue,
        };
        if meta.is_dir() {
            walk_dir(&p, &child_rel, pats, out);
        } else if name.ends_with(".nix") {
            out.push(p);
        }
    }
}
