            msg: format!(
                "error: {}\n\nUSAGE:\n    {}\n\nFor more information try --help\n",
                msg, usage
            ),
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Fmt {
    Stderr,
    Errfmt,
}

pub struct Opts {
    pub target: String,
    pub conf: String,
    pub ignore: Vec<String>,
    pub stdin: bool,
    pub unrestricted: bool,
    pub dry: bool,
    pub pos: Option<String>,
    pub fmt: Fmt,
    pub target_given: bool,
}

impl Default for Opts {
    fn default() -> Self {
        Opts {
            target: ".".to_string(),
            conf: ".".to_string(),
            ignore: Vec::new(),
            stdin: false,
            unrestricted: false,
            dry: false,
            pos: None,
            fmt: Fmt::Stderr,
            target_given: false,
        }
    }
}

pub enum Cmd {
    Check(Box<Opts>),
    Fix(Box<Opts>),
    Single(Box<Opts>),
    Explain(String),
    List,
    Dump,
}

fn is_flag_char(a: &str) -> bool {
    a.starts_with('-') && a != "-"
}

pub fn parse(bin: &str, args: &[String]) -> Result<Cmd, CliErr> {
    let mut i = 0;
    if i >= args.len() {
        return Err(CliErr {
            msg: main_help(bin),
        });
    }
    let first = &args[i];
    match first.as_str() {
        "-h" | "--help" => {
            return Err(CliErr { msg: main_help(bin) })
        }
        "-V" | "--version" => {
            return Err(CliErr { msg: format!("{}\n", VERSION) })
        }
        "help" => {
            i += 1;
            if i >= args.len() {
                return Err(CliErr { msg: main_help(bin) });
            }
            let sub = &args[i];
            return match sub.as_str() {
                "check" => Err(CliErr { msg: sub_help(bin, "check", &H_CHECK) }),
                "fix" => Err(CliErr { msg: sub_help(bin, "fix", &H_FIX) }),
                "single" => Err(CliErr { msg: sub_help(bin, "single", &H_SINGLE) }),
                "explain" => Err(CliErr { msg: sub_help(bin, "explain", &H_EXPLAIN) }),
                "list" => Err(CliErr { msg: sub_help(bin, "list", &H_LIST) }),
                "dump" => Err(CliErr { msg: sub_help(bin, "dump", &H_DUMP) }),
                "help" => Err(CliErr { msg: help_subcmd(bin) }),
                other => Err(CliErr::new(
                    format!(
                        "Found argument '{}' which wasn't expected, or isn't valid in this context",
                        other
                    ),
                    format!("{} <SUBCOMMAND>", bin),
                )),
            };
        }
        "check" | "fix" | "single" | "explain" | "list" | "dump" => {}
        other => {
            return Err(CliErr::new(
                format!(
                    "Found argument '{}' which wasn't expected, or isn't valid in this context",
                    other
                ),
                format!("{} <SUBCOMMAND>", bin),
            ))
        }
    }
    let sub = first.as_str();
    i += 1;
    match sub {
        "explain" => {
            let mut target: Option<String> = None;
            let mut usage = format!("{} explain <TARGET>", bin);
            while i < args.len() {
                let a = &args[i];
                if a == "-h" || a == "--help" {
                    return Err(CliErr { msg: sub_help(bin, "explain", &H_EXPLAIN) });
                }
                if a == "--" {
                    i += 1;
                    continue;
                }
                if is_flag_char(a) {
                    return Err(CliErr::new(
                        format!(
                            "Found argument '{}' which wasn't expected, or isn't valid in this context",
                            a
                        ),
                        usage.clone(),
                    ));
                }
                if target.is_some() {
                    return Err(CliErr::new(
                        format!(
                            "Found argument '{}' which wasn't expected, or isn't valid in this context",
                            a
                        ),
                        usage.clone(),
                    ));
                }
                target = Some(a.clone());
                i += 1;
            }
            match target {
                Some(t) => {
                    if crate::docs::parse_code(&t).is_none() {
                        return Err(CliErr::new(
                            format!(
                                "Invalid value for '<TARGET>': unable to parse `{}` as warning code",
                                t
                            ),
                            usage,
                        ));
                    }
                    Ok(Cmd::Explain(t))
                }
                None => Err(CliErr::new(
                    "The following required arguments were not provided:\n    <TARGET>".to_string(),
                    usage,
                )),
            }
        }
        "list" | "dump" => {
            let usage = format!("{} {}", bin, sub);
            while i < args.len() {
                let a = &args[i];
                if a == "-h" || a == "--help" {
                    let h = if sub == "list" { &H_LIST } else { &H_DUMP };
                    return Err(CliErr { msg: sub_help(bin, sub, h) });
                }
                if a == "--" {
                    i += 1;
                    continue;
                }
                return Err(CliErr::new(
                    format!(
                        "Found argument '{}' which wasn't expected, or isn't valid in this context",
                        a
                    ),
                    usage.clone(),
                ));
            }
            Ok(if sub == "list" { Cmd::List } else { Cmd::Dump })
        }
        _ => {
            let h = match sub {
                "check" => &H_CHECK,
                "fix" => &H_FIX,
                _ => &H_SINGLE,
            };
            let usage = format!("{} {} {}", bin, sub, h.usage_args);
            let usage_req = format!(
                "{} {} --position <POSITION> <TARGET>",
                bin,
                sub
            );
            let mut o = Opts::default();
            let mut positional_only = false;
            while i < args.len() {
                let a = &args[i].clone();
                if !positional_only && a == "--" {
                    positional_only = true;
                    i += 1;
                    continue;
                }
                if !positional_only && is_flag_char(a) {
                    let (name, inline) = match a.strip_prefix("--") {
                        Some(r) => match r.split_once('=') {
                            Some((n, v)) => (n.to_string(), Some(v.to_string())),
                            None => (r.to_string(), None),
                        },
                        None => {
                            let body = &a[1..];
                            if body.is_empty() {
                                return Err(CliErr::new(
                                    format!(
                                        "Found argument '{}' which wasn't expected, or isn't valid in this context",
                                        a
                                    ),
                                    usage.clone(),
                                ));
                            }
                            let c = body.chars().next().unwrap();
                            if body.len() > 1 {
                                (c.to_string(), Some(body[1..].to_string()))
                            } else {
                                (c.to_string(), None)
                            }
                        }
                    };
                    let long = |n: &str| -> bool {
                        match n {
                            "help" | "stdin" | "unrestricted" | "dry-run" | "config"
                            | "ignore" | "format" | "position" => true,
                            _ => false,
                        }
                    };
                    let canonical = |n: &str| -> &'static str {
                        match n {
                            "help" => "h",
                            "stdin" => "s",
                            "unrestricted" => "u",
                            "dry-run" => "d",
                            "config" => "c",
                            "ignore" => "i",
                            "format" => "o",
                            "position" => "p",
                            _ => "",
                        }
                    };
                    let key = if a.starts_with("--") { canonical(&name).to_string() } else { name.clone() };
                    if !a.starts_with("--") && !long(&name) && !matches!(key.as_str(), "h"|"s"|"u"|"d"|"c"|"i"|"o"|"p") {
                        return Err(CliErr::new(
                            format!(
                                "Found argument '{}' which wasn't expected, or isn't valid in this context\n\n\tIf you tried to supply `{}` as a value rather than a flag, use `-- {}`\n",
                                a, a, a
                            ),
                            usage.clone(),
                        ));
                    }
                    match key.as_str() {
                        "h" => return Err(CliErr { msg: sub_help(bin, sub, h) }),
                        "s" => {
                            o.stdin = true;
                            i += 1;
                        }
                        "u" => {
                            o.unrestricted = true;
                            i += 1;
                        }
                        "d" => {
                            o.dry = true;
                            i += 1;
                        }
                        "c" | "o" | "p" | "i" => {
                            let val = match inline {
                                Some(v) => {
                                    i += 1;
                                    v
                                }
                                None => {
                                    i += 1;
                                    if i >= args.len() {
                                        let disp = match key.as_str() {
                                            "c" => "--config <CONF_PATH>",
                                            "o" => "--format <FORMAT>",
                                            "p" => "--position <POSITION>",
                                            _ => "--ignore <IGNORE>...",
                                        };
                                        return Err(CliErr::new(
                                            format!(
                                                "The argument '{}' requires a value but none was supplied",
                                                disp
                                            ),
                                            usage.clone(),
                                        ));
                                    }
                                    let v = args[i].clone();
                                    i += 1;
                                    v
                                }
                            };
                            match key.as_str() {
                                "c" => o.conf = val,
                                "o" => {
                                    o.fmt = match val.as_str() {
                                        "stderr" => Fmt::Stderr,
                                        "errfmt" => Fmt::Errfmt,
                                        "json" => {
                                            return Err(CliErr::new(
                                                "Invalid value for '--format <FORMAT>': statix was not compiled with the `json` feature flag".to_string(),
                                                usage.clone(),
                                            ))
                                        }
                                        _ => {
                                            return Err(CliErr::new(
                                                "Invalid value for '--format <FORMAT>': unknown output format, try: json, errfmt".to_string(),
                                                usage.clone(),
                                            ))
                                        }
                                    };
                                }
                                "p" => {
                                    if let Err(_) = parse_pos(&val) {
                                        return Err(CliErr::new(
                                            format!(
                                                "Invalid value for '--position <POSITION>': unable to parse `{}` as line and column",
                                                val
                                            ),
                                            usage.clone(),
                                        ));
                                    }
                                    o.pos = Some(val);
                                }
                                _ => {
                                    o.ignore.push(val);
                                    // greedy: consume further values
                                    while i < args.len() {
                                        let nx = &args[i];
                                        if is_flag_char(nx) {
                                            break;
                                        }
                                        o.ignore.push(nx.clone());
                                        i += 1;
                                    }
                                }
                            }
                        }
                        _ => {
                            return Err(CliErr::new(
                                format!(
                                    "Found argument '{}' which wasn't expected, or isn't valid in this context\n\n\tIf you tried to supply `{}` as a value rather than a flag, use `-- {}`\n",
                                    a, a, a
                                ),
                                usage.clone(),
                            ))
                        }
                    }
                    continue;
                }
                if !o.target_given {
                    o.target = a.clone();
                    o.target_given = true;
                    i += 1;
                } else {
                    return Err(CliErr::new(
                        format!(
                            "Found argument '{}' which wasn't expected, or isn't valid in this context",
                            a
                        ),
                        usage.clone(),
                    ));
                }
            }
            if sub == "single" && o.pos.is_none() {
                let u = if o.target_given { usage_req.clone() } else { usage.clone() };
                return Err(CliErr::new(
                    "The following required arguments were not provided:\n    --position <POSITION>".to_string(),
                    u,
                ));
            }
            Ok(match sub {
                "check" => Cmd::Check(Box::new(o)),
                "fix" => Cmd::Fix(Box::new(o)),
                _ => Cmd::Single(Box::new(o)),
            })
        }
    }
}

pub fn parse_pos(s: &str) -> Option<(usize, usize)> {
    let (a, b) = s.split_once(',')?;
    let l: usize = a.parse().ok()?;
    let c: usize = b.parse().ok()?;
    Some((l, c))
}
RSEOF
echo ok"}

