    }
}

pub fn parse_pos(s: &str) -> Option<(usize, usize)> {
    let (a, b) = s.split_once(',')?;
    let l: usize = a.parse().ok()?;
    let c: usize = b.parse().ok()?;
    Some((l, c))
}
