        if !reports.is_empty() {
            any = true;
        }
        if emit(&src, &f.display().to_string(), &reports, o.fmt, &mut out) {
            let _ = out.flush();
            panic_ariadne();
        }
    }
    if any {
        1
    } else {
        0
    }
}

fn run_fix(o: &cli::Opts) -> i32 {
    let cfg = match load_config(Path::new(&o.conf)) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("config error: {}", e.to_string());
            return 0;
        }
    };
    let stdout = std::io::stdout();
    let mut out = stdout.lock();
    if o.stdin {
        let src = read_stdin();
        let fixed = fix::fix_all(&src, &cfg);
        if o.dry {
            if let Some(d) = diff::unified_diff(&src, &fixed, "<stdin>", "<stdin>") {
                let _ = out.write_all(d.as_bytes());
            }
        } else {
            let _ = out.write_all(fixed.as_bytes());
        }
        return 0;
    }
    let files = match vfs::collect(Path::new(&o.target), &cfg, o.unrestricted) {
        Ok(f) => f,
        Err(e) => {
            eprintln!("config error: {}", e.to_string());
            return 0;
        }
    };
    for f in files {
        let src = match fs::read_to_string(&f) {
            Ok(s) => s,
            Err(_) => continue,
        };
        let fixed = fix::fix_all(&src, &cfg);
        if fixed == src {
            continue;
        }
        if o.dry {
            if let Some(d) = diff::unified_diff(&src, &fixed, &f.display().to_string(), &f.display().to_string()) {
                let _ = out.write_all(d.as_bytes());
            }
        } else {
            let _ = fs::write(&f, &fixed);
        }
    }
    0
}

fn run_single(o: &cli::Opts) -> i32 {
    let cfg = match load_config(Path::new(&o.conf)) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("config error: {}", e.to_string());
            return 0;
        }
    };
    let src = if o.stdin {
        read_stdin()
    } else {
        match fs::read_to_string(Path::new(&o.target)) {
            Ok(s) => s,
            Err(e) => {
                eprintln!("config error: {}", vfs::io_err(&e));
                return 0;
            }
        }
    };
    let (line, col) = cli::parse_pos(o.pos.as_deref().unwrap_or("1,0")).unwrap_or((1, 0));
    let stdout = std::io::stdout();
    let mut out = stdout.lock();
    if o.dry {
        if let Some(fixed) = fix::fix_single(&src, &cfg, line, col) {
            if let Some(d) = diff::unified_diff(&src, &fixed, "<stdin>", "<stdin>") {
                let _ = out.write_all(d.as_bytes());
            }
        }
        return 0;
    }
    let (l, c) = (line, col);
    if !fix::pos_in_bounds(&src, l, c) {
        eprintln!("single fix error: position out of bounds: line {}, col {}", l, c);
        return 0;
    }
    match fix::fix_single(&src, &cfg, l, c) {
        Some(fixed) => {
            let _ = out.write_all(fixed.as_bytes());
        }
        None => {
            eprintln!("single fix error: nothing to fix");
        }
    }
    0
}

fn run_explain(t: &str) -> i32 {
    match docs::parse_code(t) {
        Some((true, n)) if n > 0 => match docs::DOCS.iter().find(|(c, _)| *c as u64 == n) {
            Some((_, d)) => {
                print!("{}", d);
                0
            }
            None => {
                eprintln!("explain error: lint with code `{}` not found", n);
                0
            }
        },
        _ => {
            println!("syntax error");
            0
        }
    }
}

fn load_config(p: &Path) -> Result<Config, vfs::VErr> {
    let f = vfs::resolve_config(p)?;
    vfs::load_config(&f)
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let bin = args
        .first()
        .map(|a| {
            Path::new(a)
                .file_name()
                .and_then(|s| s.to_str())
                .unwrap_or("statix")
                .to_string()
        })
        .unwrap_or_else(|| "statix".to_string());
    let code = match cli::parse(&bin, &args[1..]) {
        Err(e) => {
            if e.is_help {
                print!("{}", e.msg);
                let _ = std::io::stdout().flush();
                0
            } else {
                eprint!("{}", e.msg);
                let _ = std::io::stderr().flush();
                2
            }
        }
        Ok(cmd) => match cmd {
            Cmd::Check(o) => run_check(&o),
            Cmd::Fix(o) => run_fix(&o),
            Cmd::Single(o) => run_single(&o),
            Cmd::Explain(t) => run_explain(&t),
            Cmd::List => {
                let mut out = String::new();
                for c in 1..=23u32 {
                    let name = lint::lint_name(c);
                    if !name.is_empty() {
                        out.push_str(&format!("W{:02} {}\n", c, name));
                    }
                }
                print!("{}", out);
                0
            }
            Cmd::Dump => {
                println!("disabled = []\nignore = ['.direnv']\n");
                0
            }
        },
    };
    std::process::exit(code);
}
RSEOF
