cat > src/lint.rs <<'RSEOF'
//! The lint rules.

use crate::diag::{Fix, Label, Report, Seg};
use crate::parse::PErr;
use crate::tree::{Lit, Nk, Node, Op, UOp};

pub struct Config {
    pub disabled: Vec<String>,
    pub ignore: Vec<String>,
}

impl Default for Config {
    fn default() -> Self {
        Config { disabled: Vec::new(), ignore: vec![".direnv".to_string()] }
    }
}

pub struct Linter<'a> {
    src: &'a str,
    pub reports: Vec<Report>,
    cfg: &'a Config,
}

fn txt(s: &str) -> Seg {
    Seg::Txt(s.to_string())
}
fn hl(s: &str) -> Seg {
    Seg::Hl(s.to_string())
}

#[derive(Clone, Copy, PartialEq)]
enum PCtx {
    Default,
    Binding,
    LetBody,
}

/// Expressions that never need surrounding parentheses.
pub fn is_primitive(n: &Node) -> bool {
    matches!(
        n.kind,
        Nk::Ident | Nk::Select | Nk::Str | Nk::List | Nk::AttrSet | Nk::Paren | Nk::Dyn
    )
}

pub fn lint_name(code: u32) -> &'static str {
    match code {
        1 => "bool_comparison",
        2 => "empty_let_in",
        3 => "manual_inherit",
        4 => "manual_inherit_from",
        5 => "legacy_let_syntax",
        6 => "collapsible_let_in",
        7 => "eta_reduction",
        8 => "useless_parens",
        10 => "empty_pattern",
        11 => "redundant_pattern_bind",
        12 => "unquoted_uri",
        14 => "empty_inherit",
        17 => "deprecated_to_path",
        18 => "bool_simplification",
        19 => "useless_has_attr",
        20 => "repeated_keys",
        23 => "empty_list_concat",
        _ => "",
    }
}

impl<'a> Linter<'a> {
    pub fn new(src: &'a str, _root: &'a Node, cfg: &'a Config) -> Linter<'a> {
        Linter { src, reports: Vec::new(), cfg }
    }

    fn text(&self, a: usize, b: usize) -> &'a str {
        &self.src[a..b]
    }

    fn disabled(&self, code: u32) -> bool {
        self.cfg.disabled.iter().any(|d| d == lint_name(code))
    }

    /// End of an entry including its trailing `;`.
    fn entry_end(&self, n: &Node) -> usize {
        let bytes = self.src.as_bytes();
        let mut i = n.end;
        while i < bytes.len() && bytes[i].is_ascii_whitespace() {
            i += 1;
        }
        if i < bytes.len() && bytes[i] == b';' {
            i + 1
        } else {
            n.end
        }
    }

    /// Start of the previous entry (for the empty-inherit fix).
    pub fn prev_entry_end(src: &str, start: usize) -> usize {
        let bytes = src.as_bytes();
        let mut i = start;
        while i > 0 && bytes[i - 1].is_ascii_whitespace() {
            i -= 1;
        }
        i
    }

    pub fn run(&mut self, root: &'a Node) {
        self.collapsible(root);
        self.traverse(root, PCtx::Default);
    }

    // ------------------------------------------------------------ pass 1

    fn collapsible(&mut self, n: &'a Node) {
        if n.kind == Nk::Let && n.sub == 0 && n.children.len() >= 2 {
            let body = n.children.last().unwrap();
            if body.kind == Nk::Let && body.sub == 0 {
                if !self.disabled(6) {
                    let in_start = n.in_pos;
                    let fix = if in_start > 0 {
                        Some(Fix { start: in_start, end: body.start, text: String::new() })
                    } else {
                        None
                    };
                    let mut l1 = Label {
                        start: n.start,
                        end: n.end,
                        segs: vec![
                            txt("This "),
                            hl("let in"),
                            txt(" expression contains a nested "),
                            hl("let in"),
                            txt(" expression"),
                        ],
                        fix: None,
                    };
                    l1.fix = fix.clone();
                    let mut l2 = Label {
                        start: body.start,
                        end: body.end,
                        segs: vec![txt("This "), hl("let in"), txt(" expression is nested")],
                        fix: None,
                    };
                    l2.fix = fix;
                    self.reports.push(Report::warn(
                        6,
                        "These let-in expressions are collapsible",
                        vec![l1, l2],
                    ));
                }
            }
        }
        for c in &n.children {
            self.collapsible(c);
        }
    }

    // ------------------------------------------------------------ pass 2

    fn traverse(&mut self, n: &'a Node, ctx: PCtx) {
        match n.kind {
            Nk::Let => {
                if n.sub == 1 {
                    self.legacy_let(n);
                    for e in &n.children {
                        self.entry(e);
                    }
                } else {
                    self.empty_let(n);
                    let (entries, body) = n.children.split_at(n.children.len() - 1);
                    for e in entries {
                        self.entry(e);
                    }
                    if let Some(b) = body.first() {
                        self.parens(b, PCtx::LetBody);
                        self.traverse(b, PCtx::Default);
                    }
                }
            }
            Nk::AttrSet => {
                self.repeated_keys(n);
                for e in &n.children {
                    self.entry(e);
                }
            }
            Nk::Lambda => {
                self.empty_pattern(n);
                self.redundant_bind(n);
                self.eta(n);
                if let Some(body) = n.children.get(1) {
                    self.parens(body, PCtx::Default);
                    self.traverse(body, PCtx::Default);
                }
            }
            Nk::Paren => {
                self.parens(n, ctx);
                if let Some(c) = n.children.first() {
                    self.traverse(c, PCtx::Default);
                }
            }
            Nk::BinOp => {
                self.bool_comparison(n);
                self.empty_list_concat(n);
                for c in &n.children {
                    self.traverse(c, PCtx::Default);
                }
            }
            Nk::UnaryOp => {
                self.bool_simplification(n);
                for c in &n.children {
                    self.traverse(c, PCtx::Default);
                }
            }
            Nk::IfThenElse => {
                self.useless_has_attr(n);
                for c in &n.children {
                    self.traverse(c, PCtx::Default);
                }
            }
            Nk::Apply => {
                self.deprecated_to_path(n);
                for c in &n.children {
                    self.traverse(c, PCtx::Default);
                }
            }
            Nk::List => {
                for c in &n.children {
                    self.traverse(c, PCtx::Default);
                }
            }
            Nk::Select | Nk::HasAttr | Nk::Str | Nk::Dyn | Nk::Assert | Nk::Root => {
                for c in &n.children {
                    self.traverse(c, PCtx::Default);
                }
            }
            _ => {}
        }
    }

    fn entry(&mut self, e: &'a Node) {
        match e.kind {
            Nk::KeyValue => {
                self.manual_inherit(e);
                if let Some(v) = e.children.last() {
                    self.parens(v, PCtx::Binding);
                    self.traverse(v, PCtx::Default);
                }
            }
            Nk::Inherit => {
                let has_from = e.children.first().map(|c| c.kind == Nk::Paren).unwrap_or(false);
                let names = e.children.len() - if has_from { 1 } else { 0 };
                if names == 0 {
                    self.empty_inherit(e);
                }
                for c in &e.children {
                    self.traverse(c, PCtx::Default);
                }
            }
            _ => {}
        }
    }

    fn parens(&mut self, n: &'a Node, ctx: PCtx) {
        if n.kind != Nk::Paren || self.disabled(8) {
            if n.kind == Nk::Paren {
                if let Some(c) = n.children.first() {
                    self.traverse(c, PCtx::Default);
                }
            }
            return;
        }
        let inner = match n.children.first() {
            Some(c) => c,
            None => return,
        };
        let segs = match ctx {
            PCtx::Binding => vec![txt("Useless parentheses around value in binding")],
            PCtx::LetBody => vec![
                txt("Useless parentheses around body of "),
                hl("let"),
                txt(" expression"),
            ],
            PCtx::Default => {
                vec![txt("Useless parentheses around primitive expression")]
            }
        };
        let inner_txt = self.text(inner.start, inner.end).to_string();
        let fix = Fix { start: n.start, end: n.end, text: inner_txt };
        let mut lab = Label { start: n.start, end: n.end, segs, fix: None };
        lab.fix = Some(fix);
        self.reports.push(Report::warn(8, "These parentheses can be omitted", vec![lab]));
    }

    // -------------------------------------------------------------- W01

    fn bool_lit(&self, n: &Node) -> Option<bool> {
        if n.kind != Nk::Ident {
            return None;
        }
        match self.text(n.start, n.end) {
            "true" => Some(true),
            "false" => Some(false),
            _ => None,
        }
    }

    fn bool_comparison(&mut self, n: &'a Node) {
        let eq = matches!(n.op(), Some(Op::Eq));
        if !eq && !matches!(n.op(), Some(Op::Ne)) {
            return;
        }
        let (l, r) = match (n.children.get(0), n.children.get(1)) {
            (Some(l), Some(r)) => (l, r),
            _ => return,
        };
        let lb = self.bool_lit(l);
        let rb = self.bool_lit(r);
        let (lit, other) = if lb.is_some() {
            (lb.unwrap(), r)
        } else if rb.is_some() {
            (rb.unwrap(), l)
        } else {
            return;
        };
        if self.disabled(1) {
            return;
        }
        let keep = if rb.is_some() { l } else { r };
        let negate = match (n.op(), rb.unwrap_or(lb.unwrap())) {
            (Some(Op::Eq), b) => !b,
            _ => rb.unwrap_or(lb.unwrap()),
        };
        let text = if negate {
            format!("!{}", self.text(keep.start, keep.end))
        } else {
            self.text(keep.start, keep.end).to_string()
        };
        let fix = Fix { start: n.start, end: n.end, text };
        let lit_txt = if lit { "true" } else { "false" };
        let primary = self.text(other.start, other.end).to_string();
        let mut lab = Label {
            start: n.start,
            end: n.end,
            segs: vec![
                txt("Comparing "),
                hl(&primary),
                txt(" with boolean literal "),
                hl(lit_txt),
            ],
            fix: None,
        };
        lab.fix = Some(fix);
        self.reports.push(Report::warn(1, "Unnecessary comparison with boolean", vec![lab]));
    }

    // -------------------------------------------------------------- W02

    fn empty_let(&mut self, n: &'a Node) {
        if !n.children.is_empty() {
            return;
        }
        if self.disabled(2) {
            return;
        }
        let fix = Fix {
            start: n.start,
            end: n.end,
            text: String::new(),
        };
        let mut lab = Label {
            start: n.start,
            end: n.end,
            segs: vec![txt("This let-in expression has no entries")],
            fix: None,
        };
        lab.fix = Some(fix);
        self.reports.push(Report::warn(2, "Useless let-in expression", vec![lab]));
    }

    // -------------------------------------------------------------- W03 / W04

    fn manual_inherit(&mut self, n: &'a Node) {
        if n.children.len() < 2 {
            return;
        }
        let key = &n.children[0];
        let val = n.children.last().unwrap();
        if key.kind != Nk::Attr {
            return;
        }
        let key_name = self.text(key.start, key.end).to_string();
        let entry_end = self.entry_end(n);
        match val.kind {
            Nk::Ident => {
                if self.text(val.start, val.end) != key_name {
                    return;
                }
                if self.disabled(3) {
                    return;
                }
                let fix = Fix {
                    start: n.start,
                    end: entry_end,
                    text: format!("inherit {};", key_name),
                };
                let mut lab = Label {
                    start: n.start,
                    end: entry_end,
                    segs: vec![txt("This assignment is better written with "), hl("inherit")],
                    fix: None,
                };
                lab.fix = Some(fix);
                self.reports.push(Report::warn(3, "Assignment instead of inherit", vec![lab]));
            }
            Nk::Select => {
                if val.children.len() != 2 {
                    return;
                }
                let attr = &val.children[1];
                if attr.kind != Nk::Attr {
                    return;
                }
                if self.text(attr.start, attr.end) != key_name {
                    return;
                }
                if self.disabled(4) {
                    return;
                }
                let base = &val.children[0];
                let base_txt = self.text(base.start, base.end).to_string();
                let fix = Fix {
                    start: n.start,
                    end: entry_end,
                    text: format!("inherit ({}) {};", base_txt, key_name),
                };
                let mut lab = Label {
                    start: n.start,
                    end: entry_end,
                    segs: vec![txt("This assignment is better written with "), hl("inherit")],
                    fix: None,
                };
                lab.fix = Some(fix);
                self.reports.push(Report::warn(
                    4,
                    "Assignment instead of inherit from",
                    vec![lab],
                ));
            }
            _ => {}
        }
    }

    // -------------------------------------------------------------- W05

    fn legacy_let(&mut self, n: &'a Node) {
        let has_body = n.children.iter().any(|e| {
            e.kind == Nk::KeyValue
                && !e.children.is_empty()
                && e.children[0].kind == Nk::Attr
                && self.text(e.children[0].start, e.children[0].end) == "body"
        });
        if !has_body {
            return;
        }
        if self.disabled(5) {
            return;
        }
        let (s, e) = match n.bind {
            Some(r) => r,
            None => (n.start, n.end),
        };
        let fix = Fix { start: s, end: e, text: self.legacy_rec_text(n) };
        let mut lab = Label {
            start: s,
            end: e,
            segs: vec![
                txt("Prefer "),
                hl("rec"),
                txt(" over undocumented "),
                hl("let"),
                txt(" syntax"),
            ],
            fix: None,
        };
        lab.fix = Some(fix);
        self.reports.push(Report::warn(5, "Using undocumented `let` syntax", vec![lab]));
    }

    fn legacy_rec_text(&self, n: &Node) -> String {
        let mut out = String::from("rec {\n");
        for e in &n.children {
            if e.kind == Nk::Inherit {
                out.push_str("  ");
                out.push_str(&self.entry_body_text(e));
                out.push('\n');
            }
        }
        for e in &n.children {
            out.push_str("  ");
            out.push_str(&self.entry_body_text(e));
            out.push('\n');
        }
        out.push_str("}.body");
        out
    }

    fn entry_body_text(&self, e: &Node) -> String {
        let bytes = self.src.as_bytes();
        let mut end = e.end;
        while end > e.start && bytes[end - 1] == b';' {
            end -= 1;
            break;
        }
        self.text(e.start, end).to_string()
    }

    // -------------------------------------------------------------- W07

    fn eta(&mut self, n: &'a Node) {
        if n.children.len() != 2 {
            return;
        }
        let params = &n.children[0];
        if params.kind != Nk::Pattern || params.sub != 1 || params.bind.is_some() {
            return;
        }
        let body = &n.children[1];
        if body.kind != Nk::Apply || body.children.len() != 2 {
            return;
        }
        let f = &body.children[0];
        let arg = &body.children[1];
        if f.kind != Nk::Ident || arg.kind != Nk::Ident {
            return;
        }
        if arg.start != params.start || f.start == params.start {
            return;
        }
        if self.disabled(7) {
            return;
        }
        let f_txt = self.text(f.start, f.end).to_string();
        let fix = Fix { start: n.start, end: n.end, text: f_txt.clone() };
        let mut lab = Label {
            start: n.start,
            end: n.end,
            segs: vec![txt("Found eta-reduction: "), hl(&f_txt)],
            fix: None,
        };
        lab.fix = Some(fix);
        self.reports.push(Report::warn(
            7,
            "This function expression is eta reducible",
            vec![lab],
        ));
    }

    // -------------------------------------------------------------- W10 / W11

    fn empty_pattern(&mut self, n: &'a Node) {
        let params = match n.children.first() {
            Some(p) => p,
            None => return,
        };
        if params.kind != Nk::Pattern || params.sub != 0 || params.bind.is_some() {
            return;
        }
        if !params.children.is_empty() || self.disabled(10) {
            return;
        }
        let fix = Fix { start: params.start, end: params.end, text: "_".to_string() };
        let mut lab = Label {
            start: params.start,
            end: params.end,
            segs: vec![txt("This pattern is empty, use "), hl("_"), txt(" instead")],
            fix: None,
        };
        lab.fix = Some(fix);
        self.reports.push(Report::warn(
            10,
            "Found empty pattern in function argument",
            vec![lab],
        ));
    }

    fn redundant_bind(&mut self, n: &'a Node) {
        let params = match n.children.first() {
            Some(p) => p,
            None => return,
        };
        if params.kind != Nk::Pattern {
            return;
        }
        let bind = match params.bind {
            Some(b) => b,
            None => return,
        };
        if !params.children.is_empty() || self.disabled(11) {
            return;
        }
        let name = self.text(bind.0, bind.1).to_string();
        let fix = Fix { start: params.start, end: params.end, text: name.clone() };
        let mut lab = Label {
            start: params.start,
            end: params.end,
            segs: vec![
                txt("This pattern bind is redundant, use "),
                hl(&name),
                txt(" instead"),
            ],
            fix: None,
        };
        lab.fix = Some(fix);
        self.reports.push(Report::warn(
            11,
            "Found redundant pattern bind in function argument",
            vec![lab],
        ));
    }

    // -------------------------------------------------------------- W12

    fn unquoted_uri(&mut self, n: &'a Node) {
        if n.kind != Nk::Literal || n.lit() != Some(Lit::Uri) {
            return;
        }
        if self.disabled(12) {
            return;
        }
        let t = self.text(n.start, n.end).to_string();
        let fix = Fix { start: n.start, end: n.end, text: format!("\"{}\"", t) };
        let mut lab = Label {
            start: n.start,
            end: n.end,
            segs: vec![txt("Consider quoting this URI expression")],
            fix: None,
        };
        lab.fix = Some(fix);
        self.reports.push(Report::warn(12, "Found unquoted URI expression", vec![lab]));
    }

    // -------------------------------------------------------------- W14

    fn empty_inherit(&mut self, n: &'a Node) {
        if self.disabled(14) {
            return;
        }
        let fix = Fix { start: n.start, end: n.end, text: String::new() };
        let mut lab = Label {
            start: n.start,
            end: n.end,
            segs: vec![txt("Remove this empty "), hl("inherit"), txt(" statement")],
            fix: None,
        };
        lab.fix = Some(fix);
        self.reports.push(Report::warn(14, "Found empty inherit statement", vec![lab]));
    }

    // -------------------------------------------------------------- W17

    fn deprecated_to_path(&mut self, n: &'a Node) {
        if n.children.len() != 2 {
            return;
        }
        let callee = &n.children[0];
        let t = self.text(callee.start, callee.end);
        let ok = (callee.kind == Nk::Ident && t == "toPath")
            || (callee.kind == Nk::Select
                && callee.children.len() == 2
                && callee.children[0].kind == Nk::Ident
                && callee.children[1].kind == Nk::Attr
                && t == "builtins.toPath");
        if !ok || self.disabled(17) {
            return;
        }
        let lab = Label {
            start: callee.start,
            end: callee.end,
            segs: vec![
                hl(t),
                txt(" is deprecated, see "),
                hl(":doc builtins.toPath"),
                txt(" within the REPL for more"),
            ],
            fix: None,
        };
        self.reports.push(Report::warn(
            17,
            "Found usage of deprecated builtin toPath",
            vec![lab],
        ));
    }

    // -------------------------------------------------------------- W18

    fn bool_simplification(&mut self, n: &'a Node) {
        if n.uop() != Some(UOp::Invert) {
            return;
        }
        let inner = match n.children.first() {
            Some(c) => c,
            None => return,
        };
        let inner = match inner.kind {
            Nk::Paren => match inner.children.first() {
                Some(c) => c,
                None => return,
            },
            _ => inner,
        };
        if inner.kind != Nk::BinOp || inner.op() != Some(Op::Eq) {
            return;
        }
        let (l, r) = match (inner.children.get(0), inner.children.get(1)) {
            (Some(l), Some(r)) => (l, r),
            _ => return,
        };
        if self.disabled(18) {
            return;
        }
        let lt = self.text(l.start, l.end).to_string();
        let rt = self.text(r.start, r.end).to_string();
        let fix = Fix { start: n.start, end: n.end, text: format!("{} != {}", lt, rt) };
        let mut lab = Label {
            start: n.start,
            end: n.end,
            segs: vec![txt("Try "), hl("!="), txt(" instead of "), hl("!(... == ...)")],
            fix: None,
        };
        lab.fix = Some(fix);
        self.reports.push(Report::warn(
            18,
            "This boolean expression can be simplified",
            vec![lab],
        ));
    }

    // -------------------------------------------------------------- W19

    fn useless_has_attr(&mut self, n: &'a Node) {
        if n.children.len() != 3 {
            return;
        }
        let cond = &n.children[0];
        let then = &n.children[1];
        let els = &n.children[2];
        if cond.kind != Nk::HasAttr || cond.children.len() != 2 {
            return;
        }
        let base = &cond.children[0];
        let attr = &cond.children[1];
        if then.kind != Nk::Select || then.children.len() != 2 {
            return;
        }
        let then_base = &then.children[0];
        let then_attr = &then.children[1];
        if then_base.start != base.start || then_attr.start != attr.start {
            return;
        }
        if self.disabled(19) {
            return;
        }
        let sel_txt = self.text(then.start, then.end).to_string();
        let dflt_txt = self.text(els.start, els.end).to_string();
        let combined = if is_primitive(els) {
            format!("{} or {}", sel_txt, dflt_txt)
        } else {
            format!("{} or ({})", sel_txt, dflt_txt)
        };
        let fix = Fix { start: n.start, end: n.end, text: combined.clone() };
        let mut lab = Label {
            start: n.start,
            end: n.end,
            segs: vec![
                txt("Consider using "),
                hl(&combined),
                txt(" instead of this "),
                hl("if"),
                txt(" expression"),
            ],
            fix: None,
        };
        lab.fix = Some(fix);
        self.reports.push(Report::warn(
            19,
            "This `if` expression can be simplified with `or`",
            vec![lab],
        ));
    }

    // -------------------------------------------------------------- W20

    fn repeated_keys(&mut self, n: &'a Node) {
        let mut groups: Vec<(String, Vec<&'a Node>)> = Vec::new();
        for e in &n.children {
            if e.kind != Nk::KeyValue || e.children.is_empty() {
                continue;
            }
            let k0 = &e.children[0];
            if k0.kind != Nk::Attr {
                continue;
            }
            let name = self.text(k0.start, k0.end).to_string();
            match groups.iter_mut().find(|(g, _)| *g == name) {
                Some((_, v)) => v.push(e),
                None => groups.push((name, vec![e])),
            }
        }
        for (name, entries) in groups {
            if entries.len() < 3 {
                continue;
            }
            if entries[0].children.len() < 2 {
                continue;
            }
            if self.disabled(20) {
                continue;
            }
            let subkeys: Vec<String> = entries
                .iter()
                .take(3)
                .map(|e| {
                    let path: Vec<&Node> = e.children[..e.children.len() - 1].iter().collect();
                    path[1..]
                        .iter()
                        .map(|a| self.text(a.start, a.end).to_string())
                        .collect::<Vec<_>>()
                        .join(".")
                })
                .collect();
            let suggestion = format!(
                "{} = {{ {} }}",
                name,
                subkeys
                    .iter()
                    .map(|s| format!("{}=...;", s))
                    .collect::<Vec<_>>()
                    .join(" ")
            );
            let mut labels = Vec::new();
            let last_idx = entries.len() - 1;
            let omitted = entries.len() - 3;
            for (i, e) in entries.iter().enumerate() {
                if i > 2 {
                    break;
                }
                let is_last = i == 2 || i == last_idx;
                let key_end = e.children[e.children.len() - 2].end;
                let segs = if i == 0 {
                    vec![txt("The key "), hl(&name), txt(" is first assigned here ...")]
                } else if is_last {
                    let mut s = vec![txt("... and here.")];
                    if omitted > 0 {
                        let unit = if omitted == 1 { "occurrence" } else { "occurrences" };
                        s.push(txt(&format!(" (`{}` {} omitted)", omitted, unit)));
                    }
                    s.push(txt(" Try "));
                    s.push(hl(&suggestion));
                    s.push(txt(" instead."));
                    s
                } else {
                    vec![txt("... repeated here ...")]
                };
                labels.push(Label { start: e.start, end: key_end, segs, fix: None });
            }
            self.reports
                .push(Report::warn(20, "Avoid repeated keys in attribute sets", labels));
        }
    }

    // -------------------------------------------------------------- W23

    fn empty_list_concat(&mut self, n: &'a Node) {
        if n.op() != Some(Op::Concat) || n.children.len() != 2 {
            return;
        }
        let (l, r) = (&n.children[0], &n.children[1]);
        let empty = |x: &Node| x.kind == Nk::List && x.children.is_empty();
        let keep = if empty(l) {
            r
        } else if empty(r) {
            l
        } else {
            return;
        };
        if self.disabled(23) {
            return;
        }
        let fix = Fix {
            start: n.start,
            end: n.end,
            text: self.text(keep.start, keep.end).to_string(),
        };
        let mut lab = Label {
            start: n.start,
            end: n.end,
            segs: vec![
                txt("Concatenation with the empty list, "),
                hl("[]"),
                txt(", is a no-op"),
            ],
            fix: None,
        };
        lab.fix = Some(fix);
        self.reports.push(Report::warn(
            23,
            "Unnecessary concatenation with empty list",
            vec![lab],
        ));
    }

    // -------------------------------------------------------------- errors

    pub fn error_reports(&mut self, errs: &[PErr]) {
        for e in errs {
            let (s, en) = if e.start == e.end && e.start == self.src.len() {
                (0usize, 0usize)
            } else {
                (e.start, e.end)
            };
            let lab = Label {
                start: s,
                end: en,
                segs: vec![txt(&e.msg)],
                fix: None,
            };
            self.reports.push(Report::err("Syntax error", vec![lab]));
        }
    }
}
RSEOF
echo ok

function.arguments:
{"command": "cat > src/lint.rs <<'RSEOF'
//! The lint rules.

use crate::diag::{Fix, Label, Report, Seg};
use crate::parse::PErr;
use crate::tree::{Lit, Nk, Node, Op, UOp};

pub struct Config {
    pub disabled: Vec<String>,
    pub ignore: Vec<String>,
}

impl Default for Config {
    fn default() -> Self {
        Config { disabled: Vec::new(), ignore: vec![".direnv".to_string()] }
    }
}

pub struct Linter<'a> {
    src: &'a str,
    pub reports: Vec<Report>,
    cfg: &'a Config,
}

fn txt(s: &str) -> Seg {
    Seg::Txt(s.to_string())
}
fn hl(s: &str) -> Seg {
    Seg::Hl(s.to_string())
}

#[derive(Clone, Copy, PartialEq)]
enum PCtx {
    Default,
    Binding,
    LetBody,
}

/// Expressions that never need surrounding parentheses.
pub fn is_primitive(n: &Node) -> bool {
    matches!(
        n.kind,
        Nk::Ident | Nk::Select | Nk::Str | Nk::List | Nk::AttrSet | Nk::Paren | Nk::Dyn
    )
}

pub fn lint_name(code: u32) -> &'static str {
    match code {
        1 => "bool_comparison",
        2 => "empty_let_in",
        3 => "manual_inherit",
        4 => "manual_inherit_from",
        5 => "legacy_let_syntax",
        6 => "collapsible_let_in",
        7 => "eta_reduction",
        8 => "useless_parens",
        10 => "empty_pattern",
        11 => "redundant_pattern_bind",
        12 => "unquoted_uri",
        14 => "empty_inherit",
        17 => "deprecated_to_path",
        18 => "bool_simplification",
        19 => "useless_has_attr",
        20 => "repeated_keys",
        23 => "empty_list_concat",
        _ => "",
    }
}

impl<'a> Linter<'a> {
    pub fn new(src: &'a str, _root: &'a Node, cfg: &'a Config) -> Linter<'a> {
        Linter { src, reports: Vec::new(), cfg }
    }

    fn text(&self, a: usize, b: usize) -> &'a str {
        &self.src[a..b]
    }

    fn disabled(&self, code: u32) -> bool {
        self.cfg.disabled.iter().any(|d| d == lint_name(code))
    }

    /// End of an entry including its trailing `;`.
    fn entry_end(&self, n: &Node) -> usize {
        let bytes = self.src.as_bytes();
        let mut i = n.end;
        while i < bytes.len() && bytes[i].is_ascii_whitespace() {
            i += 1;
        }
        if i < bytes.len() && bytes[i] == b';' {
            i + 1
        } else {
            n.end
        }
    }

    /// Start of the previous entry (for the empty-inherit fix).
    pub fn prev_entry_end(src: &str, start: usize) -> usize {
        let bytes = src.as_bytes();
        let mut i = start;
        while i > 0 && bytes[i - 1].is_ascii_whitespace() {
            i -= 1;
        }
        i
    }

    pub fn run(&mut self, root: &'a Node) {
        self.collapsible(root);
        self.traverse(root, PCtx::Default);
    }

    // ------------------------------------------------------------ pass 1

    fn collapsible(&mut self, n: &'a Node) {
        if n.kind == Nk::Let && n.sub == 0 && n.children.len() >= 2 {
            let body = n.children.last().unwrap();
            if body.kind == Nk::Let && body.sub == 0 {
                if !self.disabled(6) {
                    let in_start = n.in_pos;
                    let fix = if in_start > 0 {
                        Some(Fix { start: in_start, end: body.start, text: String::new() })
                    } else {
                        None
                    };
                    let mut l1 = Label {
                        start: n.start,
                        end: n.end,
                        segs: vec![
                            txt("This "),
                            hl("let in"),
                            txt(" expression contains a nested "),
                            hl("let in"),
                            txt(" expression"),
                        ],
                        fix: None,
                    };
                    l1.fix = fix.clone();
                    let mut l2 = Label {
                        start: body.start,
                        end: body.end,
                        segs: vec![txt("This "), hl("let in"), txt(" expression is nested")],
                        fix: None,
                    };
                    l2.fix = fix;
                    self.reports.push(Report::warn(
                        6,
                        "These let-in expressions are collapsible",
                        vec![l1, l2],
                    ));
                }
            }
        }
        for c in &n.children {
            self.collapsible(c);
        }
    }

    // ------------------------------------------------------------ pass 2

    fn traverse(&mut self, n: &'a Node, ctx: PCtx) {
        match n.kind {
            Nk::Let => {
                if n.sub == 1 {
                    self.legacy_let(n);
                    for e in &n.children {
                        self.entry(e);
                    }
                } else {
                    self.empty_let(n);
                    let (entries, body) = n.children.split_at(n.children.len() - 1);
                    for e in entries {
                        self.entry(e);
                    }
                    if let Some(b) = body.first() {
                        self.parens(b, PCtx::LetBody);
