        return Err(VErr::Io("No such file or directory (os error 2)".to_string()));
    }
    let mut cur = p.to_path_buf();
    loop {
        let cand = cur.join("statix.toml");
        if cand.is_file() {
            return Ok(Some(cand));
        }
        match cur.parent() {
