{"command": "cd /workspace && python3 - <<'PY'
p='src/main.rs'; s=open(p).read()
s=s.replace("""fn analyze(src: &str, cfg: &Config) -> Vec<Report> {""","""fn debug_dump(src: &str) {
    let toks = tok::Lexer::tokenize(src);
    eprintln!("TOKENS:");
    for t in &toks {
        eprintln!("  {:?} {}..{} {:?}", t.kind, t.start, t.end, &src[t.start..t.end]);
    }
    let r = parse::Parser::parse(src);
    eprintln!("ERRORS:");
    for e in &r.errors {
        eprintln!("  {}..{} {}", e.start, e.end, e.msg);
    }
    fn dump(n: &tree::Node, d: usize, src: &str) {
        eprintln!("{}{:?} {}..{} sub={} bind={:?} {:?}", "  ".repeat(d), n.kind, n.start, n.end, n.sub, n.bind, &src[n.start..n.end.min(src.len())]);
        for c in &n.children {
            dump(c, d + 1, src);
        }
    }
    eprintln!("TREE:");
    dump(&r.root, 0, src);
}

fn analyze(src: &str, cfg: &Config) -> Vec<Report> {""")
s=s.replace("""fn run_check(o: &cli::Opts) -> i32 {""","""fn run_check(o: &cli::Opts) -> i32 {
    if std::env::var("STATIX_DEBUG").is_ok() {
        let s = if o.stdin { read_stdin() } else { fs::read_to_string(Path::new(&o.target)).unwrap_or_default() };
        debug_dump(&s);
    }""")
open(p,'w').write(s)
